#!/usr/bin/env python3
"""Smart irrigation controller for Raspberry Pi.

Controls a solenoid valve on BCM GPIO 17 and reads a capacitive soil
moisture sensor via an MCP3008 SPI ADC (bus 0, CE0, channel 0) every 5 s.
Exposes a JSON command interface over TCP on port 8080.
"""

import argparse
import json
import logging
import signal
import socket
import sys
import time

import spidev
from gpiozero import OutputDevice

# ---------------------------------------------------------------------------
# Defaults
# ---------------------------------------------------------------------------
DEFAULT_MOISTURE_THRESHOLD = 30
DEFAULT_WEB_PORT = 8080
DEFAULT_LOG_FILE = "irrigation.log"
DEFAULT_VALVE_PIN = 17
DEFAULT_SPI_CHANNEL = 0

# MCP3008 full-scale code for a 3.3 V reference (10-bit ADC)
ADC_FULL_SCALE = 1023

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_valve: OutputDevice | None = None
_spi: spidev.SpiDev | None = None
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _read_moisture(spi: spidev.SpiDev, channel: int) -> int:
    """Read a raw 10-bit value from the MCP3008 on the given channel.

    Raises RuntimeError on SPI bus errors or sensor-absent conditions
    (all-zeros or all-ones reads).
    """
    if not 0 <= channel <= 7:
        raise ValueError(f"Invalid MCP3008 channel {channel}")

    # MCP3008 single-ended read: start bit, config byte, padding
    r = spi.xfer2([0x01, (0x08 | channel) << 4, 0x00])
    if len(r) != 3:
        raise RuntimeError(f"Unexpected SPI response length: {len(r)}")

    value = ((r[1] & 0x03) << 8) | r[2]

    if value == 0:
        raise RuntimeError("MCP3008 returned all-zeros — sensor absent or wiring fault")
    if value == ADC_FULL_SCALE:
        raise RuntimeError("MCP3008 returned all-ones — sensor absent or wiring fault")

    return value


def _calculate_moisture(raw: int) -> float:
    """Convert raw ADC code to a 0.0–100.0 % moisture estimate."""
    return round((raw / ADC_FULL_SCALE) * 100.0, 2)


def _validate_moisture(raw: int) -> float:
    """Return moisture percentage, or raise RuntimeError on sensor faults."""
    try:
        return _calculate_moisture(raw)
    except RuntimeError as exc:
        logging.error("Sensor read failed: %s", exc)
        raise


def _control_valve(state: bool) -> None:
    """Drive the solenoid valve to the requested state."""
    global _valve
    if _valve is None:
        return
    try:
        _valve.value = state
    except Exception as exc:
        logging.error("Failed to set valve state: %s", exc)


def _handle_client(conn: socket.socket, addr: tuple) -> None:
    """Handle a single TCP client connection."""
    global _running
    try:
        while _running:
            data = conn.recv(1024)
            if not data:
                break

            try:
                payload = json.loads(data.decode("utf-8").strip())
            except (json.JSONDecodeError, UnicodeDecodeError):
                logging.warning("Invalid JSON from %s: %r", addr, data)
                continue

            if not isinstance(payload, dict):
                logging.warning("Non-object payload from %s: %r", addr, payload)
                continue

            action = payload.get("action")
            if action == "get_status":
                try:
                    raw = _read_moisture(_spi, DEFAULT_SPI_CHANNEL)
                    moisture = _validate_moisture(raw)
                    valve_state = _valve.value if _valve else False
                    response = {
                        "moisture": moisture,
                        "valve_state": valve_state,
                        "threshold": DEFAULT_MOISTURE_THRESHOLD,
                    }
                except RuntimeError:
                    response = {"error": "sensor_read_failed"}
                conn.sendall(json.dumps(response).encode("utf-8"))
            elif action == "toggle_valve":
                try:
                    _control_valve(not _valve.value if _valve else False)
                    response = {"status": "valve_toggled"}
                    conn.sendall(json.dumps(response).encode("utf-8"))
                except Exception as exc:
                    response = {"error": str(exc)}
                    conn.sendall(json.dumps(response).encode("utf-8"))
            else:
                response = {"error": "unknown_action"}
                conn.sendall(json.dumps(response).encode("utf-8"))
    except socket.timeout:
        pass
    except OSError as exc:
        logging.error("Socket error with %s: %s", addr, exc)
    finally:
        try:
            conn.close()
        except OSError:
            pass


def _server_loop(port: int) -> None:
    """Run the TCP command server until interrupted."""
    global _running
    server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    try:
        server.bind(("", port))
        server.listen(5)
        server.settimeout(1.0)
        logging.info("Web server listening on port %d", port)
        while _running:
            try:
                conn, addr = server.accept()
            except socket.timeout:
                continue
            except OSError as exc:
                if _running:
                    logging.error("Accept error: %s", exc)
                break
            logging.info("Connection from %s", addr)
            conn.settimeout(10.0)
            _handle_client(conn, addr)
    except OSError as exc:
        logging.error("Server bind/listen failed: %s", exc)
    finally:
        try:
            server.close()
        except OSError:
            pass


def _cleanup() -> None:
    """Release all hardware resources."""
    global _valve, _spi
    if _valve is not None:
        try:
            _valve.close()
        except Exception:
            pass
        _valve = None
    if _spi is not None:
        try:
            _spi.close()
        except Exception:
            pass
        _spi = None
    logging.info("Cleanup complete")


def main() -> int:
    global _valve, _spi

    parser = argparse.ArgumentParser(description="Smart Irrigation System")
    parser.add_argument("--moisture_threshold", type=int, default=DEFAULT_MOISTURE_THRESHOLD,
                        help="Moisture threshold (0-100) for valve activation")
    parser.add_argument("--web_port", type=int, default=DEFAULT_WEB_PORT,
                        help="TCP port for the web interface")
    parser.add_argument("--log_file", type=str, default=DEFAULT_LOG_FILE,
                        help="Path to the log file")
    parser.add_argument("--valve_pin", type=int, default=DEFAULT_VALVE_PIN,
                        help="BCM GPIO pin for the solenoid valve")
    parser.add_argument("--spi_channel", type=int, default=DEFAULT_SPI_CHANNEL,
                        help="MCP3008 SPI channel (0-7)")
    args = parser.parse_args()

    logging.basicConfig(
        filename=args.log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    logging.info("Starting Smart Irrigation System")

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # --- GPIO (solenoid valve) ---
    try:
        _valve = OutputDevice(args.valve_pin, active_high=True, initial_value=False)
    except Exception as exc:
        logging.error("Failed to initialise valve on GPIO %d: %s", args.valve_pin, exc)
        return 1

    # --- SPI / MCP3008 ---
    try:
        _spi = spidev.SpiDev()
        _spi.open(0, 0)          # bus 0, CE0
        _spi.max_speed_hz = 1_000_000
        _spi.mode = 0
    except Exception as exc:
        logging.error("Failed to open SPI bus 0, CE0: %s", exc)
        _cleanup()
        return 1

    # --- Server thread ---
    server_thread = threading.Thread(target=_server_loop, args=(args.web_port,), daemon=True)
    server_thread.start()

    # --- Main loop ---
    try:
        while _running:
            try:
                raw = _read_moisture(_spi, args.spi_channel)
                moisture = _validate_moisture(raw)
                logging.info("Moisture: %.2f%%", moisture)

                if moisture < args.moisture_threshold:
                    _control_valve(True)
                    logging.info("Valve ON (moisture < threshold)")
                elif moisture > args.moisture_threshold + 10:
                    _control_valve(False)
                    logging.info("Valve OFF (moisture > threshold + 10)")

            except RuntimeError:
                # Sensor fault — keep valve in its current state
                pass

            # Sleep in small increments so signals are caught promptly
            for _ in range(50):
                if not _running:
                    break
                time.sleep(0.1)
    except Exception as exc:
        logging.error("Unexpected error in main loop: %s", exc)
    finally:
        _cleanup()
        logging.info("Exiting Smart Irrigation System")
    return 0


if __name__ == "__main__":
    import threading
    sys.exit(main())

