        channels (list): List of MCP3008 channels for analog sensors.
        spi_speed (int): SPI clock speed in Hz (default 1000000).
        log_queue (queue.Queue): Queue for logging events.
    """

    def __init__(self, sensor_id, sensor_type, threshold, sample_rate,
                 gpio_pins, channels, spi_speed, log_queue):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.spi = None
        self.gpio_devices = []
        self._running = True

        if self.sensor_type == 'digital':
            if not gpio_pins:
                raise ValueError(f"gpio_pins must be provided for digital sensor {sensor_id}")
            for pin in gpio_pins:
                try:
                    dev = DigitalInputDevice(pin, pull_up=False, bounce_time=0.1)
                    self.gpio_devices.append(dev)
                except Exception as e:
                    logging.error(f"Failed to initialize GPIO pin {pin} for sensor {sensor_id}: {e}")
                    raise
        elif self.sensor_type == 'analog':
            if not channels:
                raise ValueError(f"channels must be provided for analog sensor {sensor_id}")
            try:
                self.spi = spidev.SpiDev()
                self.spi.open(0, 0)
                self.spi.max_speed_hz = self.spi_speed
                self.spi.mode = 0
            except Exception as e:
                logging.error(f"Failed to initialize SPI for sensor {sensor_id}: {e}")
                raise

    def read_sensor(self):
        """Reads the sensor and returns the value or None on error."""
        if self.sensor_type == 'digital':
            if not self.gpio_devices:
                return None
            for dev in self.gpio_devices:
                try:
                    return int(dev.value)
                except Exception as e:
                    logging.error(f"Error reading digital sensor {self.sensor_id} on pin {dev.pin}: {e}")
                    return None
        elif self.sensor_type == 'analog':
            if self.spi is None:
                return None
            try:
                for channel in self.channels:
                    if not 0 <= channel <= 7:
                        logging.error(f"Invalid MCP3008 channel {channel} for sensor {self.sensor_id}")
                        continue
                    adc = self._read_mcp3008(channel)
                    if adc is not None:
                        return adc
            except Exception as e:
                logging.error(f"Error reading analog sensor {self.sensor_id} on channel {channel}: {e}")
                return None
        return None

    def _read_mcp3008(self, channel):
        """Reads a single-ended channel from the MCP3008."""
        try:
            r = self.spi.xfer2([1, (8 + channel) << 4, 0])
            return ((r[1] & 3) << 8) + r[2]
        except Exception as e:
            logging.error(f"SPI transfer failed on channel {channel} for sensor {self.sensor_id}: {e}")
            return None

    def detect_event(self, value):
        """Detects an event based on the sensor value and threshold."""
        if self.sensor_type == 'digital' and value == 1:
            return True
        elif self.sensor_type == 'analog' and value is not None and value >= self.threshold:
            return True
        return False

    def log_event(self, value):
        """Logs an event to the queue."""
        try:
            self.log_queue.put((self.sensor_id, value))
        except Exception as e:
            logging.error(f"Error logging event for sensor {self.sensor_id}: {e}")

    def run(self):
        """Main loop for reading and logging sensor data."""
        while self._running:
            try:
                value = self.read_sensor()
                if self.detect_event(value):
                    self.log_event(value)
                time.sleep(1.0 / self.sample_rate)
            except Exception as e:
                logging.error(f"Error in sensor {self.sensor_id} loop: {e}")
                time.sleep(1.0)

    def stop(self):
        """Stops the sensor loop."""
        self._running = False

    def cleanup(self):
        """Releases resources."""
        self.stop()
        if self.spi is not None:
            try:
                self.spi.close()
            except Exception as e:
                logging.error(f"Error closing SPI for sensor {self.sensor_id}: {e}")
        for dev in self.gpio_devices:
            try:
                dev.close()
            except Exception as e:
                logging.error(f"Error closing GPIO for sensor {self.sensor_id}: {e}")


def main():
    parser = argparse.ArgumentParser(description="Sound Sensor Event Logger")
    parser.add_argument("--sensor_type", type=str, default="digital",
                        choices=["digital", "analog"],
                        help="Type of sound sensor (digital or analog)")
    parser.add_argument("--threshold", type=int, default=500,
                        help="Threshold value for analog sensors")
    parser.add_argument("--sample_rate", type=int, default=10,
                        help="Sampling rate in Hz")
    parser.add_argument("--log_file", type=str, default="sound_events.log",
                        help="Path to the log file")
    parser.add_argument("--gpio_pins", type=str, nargs='+', default=[],
                        help="GPIO pins for digital sensors (BCM numbering)")
    parser.add_argument("--channels", type=str, nargs='+', default=[],
                        help="MCP3008 channels for analog sensors")
    parser.add_argument("--spi_speed", type=int, default=1000000,
                        help="SPI clock speed in Hz")
    parser.add_argument("--sensor_ids", type=str, nargs='+', default=["sensor1"],
                        help="IDs for the sound sensors")
    args = parser.parse_args()

    logging.basicConfig(filename=args.log_file, level=logging.INFO,
                        format='%(asctime)s - %(levelname)s - %(message)s')

    log_queue = queue.Queue()
    sensors = []

    def signal_handler(signum, frame):
        logging.info("Signal received, shutting down...")
        for s in sensors:
            s.stop()
        for s in sensors:
            s.cleanup()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        gpio_pins = [int(p) for p in args.gpio_pins]
        channels = [int(c) for c in args.channels]
    except ValueError:
        logging.error("Invalid GPIO pin or MCP3008 channel values provided.")
        sys.exit(1)

    for sensor_id in args.sensor_ids:
        try:
            sensor = SoundSensor(sensor_id, args.sensor_type, args.threshold,
                                 args.sample_rate, gpio_pins, channels,
                                 args.spi_speed, log_queue)
            sensors.append(sensor)
            thread = threading.Thread(target=sensor.run, daemon=True)
            thread.start()
        except Exception as e:
            logging.error(f"Failed to initialize sensor {sensor_id}: {e}")

    try:
        while True:
            try:
                sensor_id, value = log_queue.get(timeout=1)
                logging.info(f"Sensor {sensor_id}: Value = {value}")
            except queue.Empty:
                pass
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received, shutting down...")
    finally:
        for s in sensors:
            s.stop()
        for s in sensors:
            s.cleanup()


