import time
import signal
import sys
import logging
from datetime import datetime

import board
import busio
import adafruit_max30102

LOG_FILE = 'heart_rate_log.txt'
SAMPLE_INTERVAL = 1.0
WINDOW_SECONDS = 4.0
WINDOW_SAMPLES = int(SAMPLE_INTERVAL * WINDOW_SECONDS)

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s [%(levelname)s] %(message)s',
)
logger = logging.getLogger(__name__)

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _format_hr(hr_value):
    """Defensively format the heart-rate value for logging."""
    if hr_value is None:
        return 'N/A'
    try:
        return int(hr_value)
    except (TypeError, ValueError):
        try:
            return int(float(hr_value))
        except (TypeError, ValueError):
            return str(hr_value)


def _log_and_print(hr_value):
    """Log the heart-rate value to file and print to console."""
    timestamp = datetime.now().isoformat(timespec='seconds')
    hr_str = _format_hr(hr_value)
    logger.info('Heart Rate: %s BPM', hr_str)
    try:
        with open(LOG_FILE, 'a') as f:
            f.write(f'{timestamp}, {hr_str}\n')
    except OSError as exc:
        logger.error('Failed to write log file: %s', exc)


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    i2c = None
    sensor = None

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        sensor = adafruit_max30102.MAX30102(i2c)
        logger.info('MAX30102 initialized on I2C bus.')

        recent_peaks = []

        while _running:
            try:
                ir, red = sensor.get_ir_sample(), sensor.get_red_sample()
            except (OSError, ValueError, RuntimeError) as exc:
                logger.warning('Sensor read failed: %s', exc)
                time.sleep(SAMPLE_INTERVAL)
                continue

            if ir is None or red is None:
                logger.warning('Sensor returned None sample.')
                time.sleep(SAMPLE_INTERVAL)
                continue

            logger.debug('IR=%s RED=%s', ir, red)

            try:
                hr_value = sensor.get_heart_rate()
            except (OSError, ValueError, RuntimeError) as exc:
                logger.warning('Heart-rate read failed: %s', exc)
                hr_value = None

            if hr_value is not None:
                recent_peaks.append(hr_value)
                if len(recent_peaks) > WINDOW_SAMPLES:
                    recent_peaks.pop(0)

                if len(recent_peaks) == WINDOW_SAMPLES:
                    logger.info('Rolling window full.')
                    _log_and_print(hr_value)

            time.sleep(SAMPLE_INTERVAL)

    except Exception as exc:
        logger.error('Fatal error: %s', exc)
        sys.exit(1)
    finally:
        logger.info('Cleaning up resources.')
        if sensor is not None:
            try:
                sensor.deinit()
            except Exception:
                pass
        if i2c is not None:
            try:
                i2c.deinit()
            except Exception:
                pass
        logger.info('Program terminated.')


if __name__ == '__main__':
    main()

