import spidev
import time
import datetime
import os
import json
import signal
import sys
import RPi.GPIO as GPIO

# Configuration file path
CONFIG_FILE = "config.json"

# Default configuration values
DEFAULT_CONFIG = {
    "mq2_channel": 0,
    "mq7_channel": 1,
    "mq135_channel": 2,
    "mq2_warning": 0.5,
    "mq2_critical": 1.0,
    "mq7_warning": 0.3,
    "mq7_critical": 0.8,
    "mq135_warning": 0.2,
    "mq135_critical": 0.5,
    "actuator_pin": 17
}

# Global variables for cleanup
spi = None
actuator_pin = None
running = True

def signal_handler(sig, frame):
    """Handle SIGINT (Ctrl+C) for graceful shutdown."""
    global running
    print("\nInterrupt received, shutting down...")
    running = False

def load_config():
    """Loads configuration from config.json, falling back to defaults."""
    try:
        with open(CONFIG_FILE, "r") as f:
            config = json.load(f)
        print("Configuration loaded from config.json")
        return config
    except FileNotFoundError:
        print(f"Warning: {CONFIG_FILE} not found. Using default configuration.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        print(f"Warning: Invalid JSON in {CONFIG_FILE}: {e}. Using default configuration.")
        return DEFAULT_CONFIG.copy()

def read_mcp3008(channel):
    """Reads a single-ended channel from the MCP3008 ADC."""
    if not 0 <= channel <= 7:
        raise ValueError("Channel must be between 0 and 7")
    # MCP3008 SPI command: start bit, single-ended mode, channel selection
    adc = spi.xfer2([1, (8 + channel) << 4, 0])
    data = ((adc[1] & 3) << 8) + adc[2]
    return data

def convert_to_voltage(adc_value):
    """Converts 10-bit ADC value to voltage (3.3V reference)."""
    return (adc_value / 1023.0) * 3.3

def log_data(timestamp, mq2_voltage, mq7_voltage, mq135_voltage):
    """Logs sensor data to a CSV file."""
    log_file_path = os.path.join(os.path.expanduser("~"), "logs", "industrial_air_quality.log")
    log_dir = os.path.dirname(log_file_path)
    if log_dir:
        os.makedirs(log_dir, exist_ok=True)
    try:
        with open(log_file_path, "a") as f:
            f.write(f"{timestamp},{mq2_voltage:.3f},{mq7_voltage:.3f},{mq135_voltage:.3f}\n")
    except IOError as e:
        print(f"Error writing to log file: {e}")

def check_thresholds(mq2_voltage, mq7_voltage, mq135_voltage, config):
    """Checks sensor voltages against thresholds and controls the actuator."""
    global actuator_pin
    if mq2_voltage > config["mq2_critical"]:
        print(f"CRITICAL: MQ-2 voltage ({mq2_voltage:.3f}V) exceeds critical threshold ({config['mq2_critical']}V)")
        if actuator_pin is not None:
            GPIO.output(actuator_pin, GPIO.HIGH)
    elif mq2_voltage > config["mq2_warning"]:
        print(f"WARNING: MQ-2 voltage ({mq2_voltage:.3f}V) exceeds warning threshold ({config['mq2_warning']}V)")
    else:
        if actuator_pin is not None:
            GPIO.output(actuator_pin, GPIO.LOW)

    if mq7_voltage > config["mq7_critical"]:
        print(f"CRITICAL: MQ-7 voltage ({mq7_voltage:.3f}V) exceeds critical threshold ({config['mq7_critical']}V)")
        if actuator_pin is not None:
            GPIO.output(actuator_pin, GPIO.HIGH)
    elif mq7_voltage > config["mq7_warning"]:
        print(f"WARNING: MQ-7 voltage ({mq7_voltage:.3f}V) exceeds warning threshold ({config['mq7_warning']}V)")
    else:
        if actuator_pin is not None:
            GPIO.output(actuator_pin, GPIO.LOW)

    if mq135_voltage > config["mq135_critical"]:
        print(f"CRITICAL: MQ-135 voltage ({mq135_voltage:.3f}V) exceeds critical threshold ({config['mq135_critical']}V)")
        if actuator_pin is not None:
            GPIO.output(actuator_pin, GPIO.HIGH)
    elif mq135_voltage > config["mq135_warning"]:
        print(f"WARNING: MQ-135 voltage ({mq135_voltage:.3f}V) exceeds warning threshold ({config['mq135_warning']}V)")
    else:
        if actuator_pin is not None:
            GPIO.output(actuator_pin, GPIO.LOW)

def cleanup():
    """Clean up GPIO and SPI resources."""
    global spi, actuator_pin
    print("Cleaning up resources...")
    if actuator_pin is not None:
        try:
            GPIO.output(actuator_pin, GPIO.LOW)
            GPIO.cleanup(actuator_pin)
        except Exception as e:
            print(f"Error during GPIO cleanup: {e}")
    if spi is not None:
        try:
            spi.close()
        except Exception as e:
            print(f"Error closing SPI: {e}")
    print("Cleanup complete.")

def main():
    """Main function to read sensors, log data, and control the actuator."""
    global spi, actuator_pin, running

    signal.signal(signal.SIGINT, signal_handler)

    try:
        config = load_config()
        actuator_pin = config["actuator_pin"]

        # Initialize GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(actuator_pin, GPIO.OUT, initial=GPIO.LOW)

        # Initialize SPI
        spi = spidev.SpiDev()
        spi.open(0, 0)  # Bus 0, CE0
        spi.max_speed_hz = 1000000  # 1 MHz

        while running:
            try:
                mq2_adc = read_mcp3008(config["mq2_channel"])
                mq7_adc = read_mcp3008(config["mq7_channel"])
                mq135_adc = read_mcp3008(config["mq135_channel"])

                mq2_voltage = convert_to_voltage(mq2_adc)
                mq7_voltage = convert_to_voltage(mq7_adc)
                mq135_voltage = convert_to_voltage(mq135_adc)

                timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                log_data(timestamp, mq2_voltage, mq7_voltage, mq135_voltage)

                check_thresholds(mq2_voltage, mq7_voltage, mq135_voltage, config)

                time.sleep(5)

            except (IOError, ValueError) as e:
                print(f"Error during sensor reading: {e}")
                time.sleep(5)
            except Exception as e:
                print(f"An unexpected error occurred: {e}")
                time.sleep(5)

    except Exception as e:
        print(f"Fatal error during initialization: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

