import io
import time
import json
import signal
import threading
import queue
import logging
from PIL import Image

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class CameraHandler:
    """Handles camera capture, frame encoding, and motion detection."""

    def __init__(self, config):
        self.config = config
        self.camera = None
        self.frame_queue = queue.Queue(maxsize=self.config['max_frame_queue_size'])
        self.running = False
        self.gpio_pin = None
        self.led_timer = None
        self.motion_detected = False
        self.last_frame = None
        self.frame_count = 0
        self.alert_triggered = False
        self.alert_timer = None

    def initialize_camera(self):
        """Initializes the Raspberry Pi Camera Module."""
        if Picamera2 is None:
            logger.error("picamera2 library is not installed.")
            return False

        try:
            self.camera = Picamera2()
            config_cam = self.camera.create_still_configuration(
                main={"size": (self.config['camera_resolution_width'], self.config['camera_resolution_height'])}
            )
            self.camera.configure(config_cam)
            self.camera.start()
            time.sleep(self.config['camera_warm_up_time'])
            logger.info("Camera initialized successfully.")
            return True
        except Exception as e:
            logger.error(f"Error initializing camera: {e}")
            self.camera = None
            return False

    def initialize_gpio(self):
        """Initializes the GPIO pin for the LED."""
        if GPIO is None:
            logger.warning("RPi.GPIO library is not installed. LED functionality will be disabled.")
            return

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.config['gpio_pin'], GPIO.OUT, initial=GPIO.LOW)
            logger.info(f"GPIO pin {self.config['gpio_pin']} initialized successfully.")
        except Exception as e:
            logger.error(f"Error initializing GPIO: {e}")

    def capture_and_process_frames(self):
        """Captures frames from the camera, encodes them, and puts them in the queue."""
        while self.running:
            try:
                frame = self.camera.capture_array()
                if frame is None:
                    logger.warning("Captured frame is None.")
                    time.sleep(0.1)
                    continue

                image = Image.fromarray(frame)
                jpeg_frame = io.BytesIO()
                image.save(jpeg_frame, format='JPEG', quality=self.config['jpeg_quality'])
                jpeg_frame.seek(0)

                self.frame_queue.put(jpeg_frame, timeout=1)
                self.frame_count += 1
                self.last_frame = jpeg_frame

                if self.config['motion_detection']:
                    self.detect_motion(jpeg_frame)

                time.sleep(0.1)

            except queue.Full:
                logger.warning("Frame queue is full. Dropping frame.")
                try:
                    self.frame_queue.get_nowait()
                    self.frame_queue.task_done()
                except queue.Empty:
                    pass

            except Exception as e:
                logger.error(f"Error capturing or processing frame: {e}")
                time.sleep(0.1)

    def detect_motion(self, frame):
        """Detects motion in the current frame."""
        if self.config['motion_detection']:
            try:
                if self.frame_count > self.config['motion_detection_frame_interval']:
                    if self.last_frame:
                        self.last_frame.seek(0)
                        last_image = Image.open(self.last_frame)
                        frame.seek(0)
                        current_image = Image.open(frame)

                        diff = Image.new('L', (current_image.width, current_image.height))
                        diff = Image.eval(current_image.convert('L'), self.difference_function)

                        if self.config['motion_detection_threshold'] < diff.getextrema()[1]:
                            if not self.motion_detected:
                                logger.info("Motion detected!")
                                self.motion_detected = True
                                self.trigger_alert()
                        else:
                            self.motion_detected = False

                    self.frame_count = 0
                else:
                    self.frame_count += 1

            except Exception as e:
                logger.error(f"Error detecting motion: {e}")

    def difference_function(self, pixel_value):
        """Calculates the absolute difference between two pixel values."""
        if self.last_frame:
            self.last_frame.seek(0)
            last_image = Image.open(self.last_frame)
            return abs(pixel_value - last_image.getpixel((0, 0)))
        return 0

    def trigger_alert(self):
        """Triggers an alert (LED on)."""
        if self.config['gpio_pin'] and GPIO:
            try:
                GPIO.output(self.config['gpio_pin'], GPIO.HIGH)
                self.alert_triggered = True
                self.led_timer = threading.Timer(self.config['led_activation_duration'], self.turn_off_led)
                self.led_timer.daemon = True
                self.led_timer.start()
            except Exception as e:
                logger.error(f"Error triggering alert: {e}")
        else:
            logger.warning("GPIO pin or RPi.GPIO not configured. LED alert disabled.")

    def turn_off_led(self):
        """Turns off the LED."""
        if self.config['gpio_pin'] and GPIO:
            try:
                GPIO.output(self.config['gpio_pin'], GPIO.LOW)
                self.alert_triggered = False
            except Exception as e:
                logger.error(f"Error turning off LED: {e}")

    def cleanup(self):
        """Cleans up resources."""
        self.running = False
        if self.camera:
            try:
                self.camera.stop()
                self.camera.close()
            except Exception as e:
                logger.error(f"Error closing camera: {e}")
            self.camera = None

        if self.led_timer:
            self.led_timer.cancel()
            self.led_timer = None

        if self.alert_timer:
            self.alert_timer.cancel()
            self.alert_timer = None

        if GPIO and self.config['gpio_pin']:
            try:
                GPIO.output(self.config['gpio_pin'], GPIO.LOW)
                GPIO.cleanup(self.config['gpio_pin'])
            except Exception as e:
                logger.error(f"Error cleaning up GPIO: {e}")

        logger.info("Camera handler cleaned up.")


def load_config(config_file):
    """Loads configuration from a JSON file."""
    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
        logger.info(f"Configuration loaded from {config_file}")
        return config
    except FileNotFoundError:
        logger.error(f"Configuration file not found: {config_file}")
        return None
    except json.JSONDecodeError:
        logger.error(f"Invalid JSON format in configuration file: {config_file}")
        return None
    except Exception as e:
        logger.error(f"Error loading configuration: {e}")
        return None


def main():
    """Main function to run the camera handler."""
    config_file = 'config.json'
    config = load_config(config_file)

    if not config:
        return

    camera_handler = CameraHandler(config)
    camera_handler.config['gpio_pin'] = int(config['gpio_pin'])
    camera_handler.config['motion_detection_threshold'] = int(config['motion_detection_threshold'])
    camera_handler.config['led_activation_duration'] = float(config['led_activation_duration'])

    if not camera_handler.initialize_camera():
        return

    if camera_handler.config['gpio_pin']:
        camera_handler.initialize_gpio()

    camera_thread = threading.Thread(target=camera_handler.capture_and_process_frames)
    camera_thread.daemon = True
    camera_thread.start()

    def signal_handler(sig, frame):
        logger.info("Program interrupted. Cleaning up...")
        camera_handler.cleanup()
        exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            time.sleep(1)
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}")
    finally:
        camera_handler.cleanup()


if __name__ == "__main__":
    main()

