    level=logging.ERROR,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


class SensorReader:
    """
    Abstract base class for sensor readers.
    Subclasses must implement:
        - _initialize_sensor()
        - _read_sensor()
        - _validate_data()
    """

    def __init__(self, sensor_type, sensor_id, config):
        self.sensor_type = sensor_type
        self.sensor_id = sensor_id
        self.config = config
        self.sensor = None
        self.i2c_address = None
        self.sampling_interval = 60  # BMP280/BME280 default interval

    def initialize(self):
        """Initialize the sensor and store configuration."""
        try:
            self._initialize_sensor()
            self.i2c_address = self.config.get(f'{self.sensor_type.lower()}_address')
            self.sampling_interval = self.config.getint('Sampling_Interval_Seconds', 60)
            logging.info(f"Sensor {self.sensor_type} {self.sensor_id} initialized successfully.")
            return True
        except Exception as e:
            logging.error(f"Error initializing sensor {self.sensor_type} {self.sensor_id}: {e}")
            return False

    def read_sensor_data(self):
        """Read data from the sensor and return a dictionary of validated data."""
        try:
            data = self._read_sensor()
            if data is None:
                raise ValueError("Sensor returned None")
            return self._validate_data(data)
        except Exception as e:
            logging.error(f"Error reading sensor {self.sensor_type} {self.sensor_id}: {e}")
            return None

    def _validate_data(self, data):
        """Validate sensor data against acceptable ranges."""
        pressure = data.get('pressure_pa')
        temperature = data.get('temperature_c')
        humidity = data.get('humidity_percent')

        if pressure is not None and not (70000 <= pressure <= 110000):
            logging.warning(f"Invalid pressure reading from {self.sensor_type} {self.sensor_id}: {pressure}")
            return None

        if temperature is not None and not (-20 <= temperature <= 50):
            logging.warning(f"Invalid temperature reading from {self.sensor_type} {self.sensor_id}: {temperature}")
            return None

        if humidity is not None and not (0 <= humidity <= 100):
            logging.warning(f"Invalid humidity reading from {self.sensor_type} {self.sensor_id}: {humidity}")
            return None

        return data

    def close(self):
        """Release sensor resources."""
        if self.sensor is not None:
            try:
                self.sensor.close()
            except Exception as e:
                logging.error(f"Error closing sensor {self.sensor_type} {self.sensor_id}: {e}")


class BMP280Reader(SensorReader):
