class DatabaseManager:
    """Manages the SQLite database for storing sensor data."""

    def __init__(self, db_file='wildlife_data.db'):
        self.db_file = db_file
        self.conn = None
        self.cursor = None
        self._connect()

    def _connect(self):
        """Connect to the SQLite database."""
        try:
            self.conn = sqlite3.connect(self.db_file)
            self.cursor = self.conn.cursor()
            self._create_table()
        except sqlite3.Error as e:
            logging.error(f"Database connection error: {e}")
            raise

    def _create_table(self):
        """Create the sensor_data table if it doesn't exist."""
        try:
            self.cursor.execute('''
                CREATE TABLE IF NOT EXISTS sensor_data (
                    timestamp TEXT,
                    sensor_type TEXT,
                    sensor_id TEXT,
                    pressure_pa REAL,
                    temperature_c REAL,
                    humidity_percent REAL
                )
            ''')
            self.conn.commit()
        except sqlite3.Error as e:
            logging.error(f"Database table creation error: {e}")
            raise

    def store_sensor_data(self, sensor_data):
        """Store sensor data in the database."""
        if not sensor_data:
            return
        try:
            timestamp = sensor_data['timestamp']
            sensor_type = sensor_data['sensor_type']
            sensor_id = sensor_data['sensor_id']
            pressure_pa = sensor_data.get('pressure_pa')
            temperature_c = sensor_data.get('temperature_c')
            humidity_percent = sensor_data.get('humidity_percent')

            self.cursor.execute('''
                INSERT INTO sensor_data (timestamp, sensor_type, sensor_id, pressure_pa, temperature_c, humidity_percent)
                VALUES (?, ?, ?, ?, ?, ?)
            ''', (timestamp, sensor_type, sensor_id, pressure_pa, temperature_c, humidity_percent))
            self.conn.commit()
        except sqlite3.Error as e:
            logging.error(f"Database insertion error: {e}")

    def close(self):
        """Close the database connection."""
        if self.conn:
            try:
                self.conn.close()
            except sqlite3.Error as e:
                logging.error(f"Database connection close error: {e}")


def load_config(config_file='config.txt'):
    """Load configuration from a file with key=value lines and # comments."""
    config = {}
    try:
        with open(config_file, 'r') as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith('#'):
                    if '=' in line:
                        key, value = line.split('=', 1)
                        config[key.strip()] = value.strip()
        return config
    except FileNotFoundError:
        logging.warning(f"Configuration file '{config_file}' not found. Using default values.")
        return {}
    except Exception as e:
        logging.error(f"Error loading configuration file: {e}")
        return {}


def main():
    """Main function to run the sensor reading and data logging program."""
    config = load_config()
    db_file = config.get('Database_File', 'wildlife_data.db')
    db = DatabaseManager(db_file)

    sensors = []
    sensor_types = ['BMP280', 'BME280', 'MS8607']

    for sensor_type in sensor_types:
        sensor_id = config.get(f'{sensor_type.lower()}_id')
        if sensor_id:
            reader = None
            if sensor_type == 'BMP280':
                reader = BMP280Reader(sensor_type, sensor_id, config)
            elif sensor_type == 'BME280':
                reader = BME280Reader(sensor_type, sensor_id, config)
            elif sensor_type == 'MS8607':
                reader = MS8607Reader(sensor_type, sensor_id, config)

            if reader and reader.initialize():
                sensors.append(reader)

    if not sensors:
        logging.warning("No sensors found or initialized. Exiting gracefully.")
        db.close()
        sys.exit(0)

    try:
        while _running:
            for reader in sensors:
                sensor_data = reader.read_sensor_data()
                if sensor_data:
                    sensor_data['timestamp'] = time.strftime('%Y-%m-%d %H:%M:%S')
                    sensor_data['sensor_type'] = reader.sensor_type
                    sensor_data['sensor_id'] = reader.sensor_id
                    db.store_sensor_data(sensor_data)
                time.sleep(reader.sampling_interval)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        for reader in sensors:
            reader.close()
        db.close()
        print("Program finished.")


if __name__ == "__main__":
    main()

