import time
import datetime
import logging
import signal
import sys
import requests
from picamera import Picamera
import RPi.GPIO as GPIO

# Configuration
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 1000000
MOISTURE_CHANNELS = [0, 1, 2, 3]
VALVE_PINS = [17, 27, 22, 23]
WEATHER_API_URL = "http://api.openweathermap.org/data/2.5/weather"
WEATHER_API_KEY = "YOUR_API_KEY"
LOG_FILE = "irrigation.log"

# Logging setup
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Global state for cleanup
spi = None
camera = None
running = True

def signal_handler(sig, frame):
    global running
    logging.info(f"Received signal {sig}, shutting down...")
    running = False

def cleanup():
    global spi, camera
    logging.info("Cleaning up resources...")
    try:
        for pin in VALVE_PINS:
            GPIO.output(pin, GPIO.LOW)
    except Exception as e:
        logging.error(f"Error turning off valves during cleanup: {e}")
    try:
        if spi is not None:
            spi.close()
    except Exception as e:
        logging.error(f"Error closing SPI: {e}")
    try:
        if camera is not None:
            camera.stop()
            camera.close()
    except Exception as e:
        logging.error(f"Error closing camera: {e}")
    try:
        GPIO.cleanup()
    except Exception as e:
        logging.error(f"Error cleaning up GPIO: {e}")
    logging.info("Cleanup complete.")

def read_mcp3008(channel):
    """Reads analog value from MCP3008 ADC via SPI."""
    if not 0 <= channel <= 7:
        raise ValueError("Channel must be between 0 and 7")
    try:
        adc = spi.xfer2([1, (8 + channel) << 4, 0])
        data = ((adc[1] & 3) << 8) + adc[2]
        return data
    except Exception as e:
        logging.error(f"SPI read error on channel {channel}: {e}")
        return None

def get_weather_data():
    """Fetches weather data from OpenWeatherMap API."""
    try:
        params = {
            'q': 'London,uk',
            'appid': WEATHER_API_KEY,
            'units': 'metric'
        }
        response = requests.get(WEATHER_API_URL, params=params, timeout=10)
        response.raise_for_status()
        data = response.json()
        return data
    except requests.exceptions.RequestException as e:
        logging.error(f"Weather API request failed: {e}")
        return None

def capture_image():
    """Captures an image using the Raspberry Pi camera."""
    try:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"plant_image_{timestamp}.jpg"
        camera.capture_file(filename)
        logging.info(f"Captured image: {filename}")
        return filename
    except Exception as e:
        logging.error(f"Camera capture failed: {e}")
        return None

def control_valve(zone, state):
    """Controls the irrigation valve for a specific zone."""
    try:
        pin = VALVE_PINS[zone - 1]
        GPIO.output(pin, state)
        logging.info(f"Zone {zone} valve set to {'ON' if state else 'OFF'}")
    except Exception as e:
        logging.error(f"Error controlling valve for zone {zone}: {e}")

def irrigation_cycle(zone, moisture_threshold, irrigation_duration):
    """Performs the irrigation cycle for a specific zone."""
