import signal
import sys
import time

import smbus
from gpiozero import Button

I2C_BUS = 1
I2C_ADDR = 0x20
SENSOR_BITS = 8
DEBOUNCE_S = 0.05
LOOP_DELAY_S = 1.0

_running = True


def _handle_int(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_int)

    try:
        bus = smbus.SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            btn = Button(17, pull_up=True, bounce_time=DEBOUNCE_S)
        except Exception as exc:
            print(f"Error: cannot initialise GPIO17 as input: {exc}", file=sys.stderr)
            sys.exit(1)

        def on_falling():
            time.sleep(DEBOUNCE_S)
            try:
                data = bus.read_byte(I2C_ADDR)
            except OSError as exc:
                print(f"I2C read error: {exc}", file=sys.stderr)
                return
            for i in range(SENSOR_BITS):
                if (data >> i) & 1 == 0:
                    print(f"Obstacle detected by sensor {i}")
        btn.when_activated = on_falling

        print("Polling PCF8574 proximity sensors on I2C bus 1 at address 0x20. Press Ctrl+C to exit.")
        while _running:
            time.sleep(LOOP_DELAY_S)
    finally:
        try:
            btn.close()
        except Exception:
            pass
        try:
            bus.close()
        except Exception:
            pass
        print("Resources cleaned up. Exiting.")


if __name__ == "__main__":
    main()

