import board
import busio
import digitalio
import adafruit_epd.epd
from adafruit_epd import il0373
from adafruit_bme280 import basic as adafruit_bme280

# ---------------------------------------------------------------------------
# Pin / bus configuration (BCM numbering via board constants)
# ---------------------------------------------------------------------------
BME280_CS_PIN = board.D5          # GPIO7  (CE1)
BME280_SCK_PIN = board.D6         # GPIO11 (SCK)
BME280_MOSI_PIN = board.D10       # GPIO10 (MOSI)
BME280_MISO_PIN = board.D9        # GPIO9  (MISO)
EPD_CS_PIN = board.D10            # GPIO5  (CE0)
EPD_DC_PIN = board.D6             # GPIO6  (data/command)
EPD_RST_PIN = board.D9            # GPIO9  (reset)
EPD_BUSY_PIN = board.D10          # GPIO10 (busy)

UPDATE_INTERVAL_S = 60
EPD_WIDTH = 128
EPD_HEIGHT = 296

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_spi = None
_bme280 = None
_epd = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _spi, _bme280, _epd
    if _epd is not None:
        try:
            _epd.clear()
        except Exception:
            pass
    if _bme280 is not None:
        try:
            _bme280.deinit()
        except Exception:
            pass
    if _spi is not None:
        try:
            _spi.deinit()
        except Exception:
            pass


def _init_spi():
    global _spi
    try:
        return busio.SPI(board.SCK, MOSI=board.MOSI, MISO=board.MISO)
    except Exception as exc:
        print(f"[ERROR] SPI bus init failed: {exc}")
        return None


def _init_bme280(spi):
    global _bme280
    try:
        return adafruit_bme280.Adafruit_BME280_SPI(spi, cs=BME280_CS_PIN,
                                                   sclk_pin=BME280_SCK_PIN,
                                                   mosi_pin=BME280_MOSI_PIN,
                                                   miso_pin=BME280_MISO_PIN)
    except (RuntimeError, ValueError) as exc:
        print(f"[ERROR] BME280 init failed (sensor absent or wiring bad): {exc}")
        return None
    except Exception as exc:
        print(f"[ERROR] Unexpected BME280 init failure: {exc}")
        return None


def _init_epd():
    global _epd
    try:
        return il0373.IL0373(EPD_WIDTH, EPD_HEIGHT,
                              cs=EPD_CS_PIN,
                              dc=EPD_DC_PIN,
                              rst=EPD_RST_PIN,
                              busy=EPD_BUSY_PIN)
    except Exception as exc:
        print(f"[ERROR] EPD init failed: {exc}")
        return None


def _read_sensor(bme280):
    try:
        return bme280.temperature, bme280.humidity, bme280.pressure
    except (RuntimeError, ValueError) as exc:
        print(f"[WARN] BME280 read failed: {exc}")
        return None, None, None
    except Exception as exc:
        print(f"[WARN] Unexpected BME280 read error: {exc}")
        return None, None, None


def _update_display(epd, temp, hum, pres):
    try:
        epd.fill(epd.WHITE)
        epd.text(f"Temp: {temp:.1f} C", 10, 10, epd.BLACK)
        epd.text(f"Hum: {hum:.1f} %", 10, 30, epd.BLACK)
        epd.text(f"Pres: {pres:.1f} hPa", 10, 50, epd.BLACK)
        epd.display()
    except Exception as exc:
        print(f"[WARN] EPD update failed: {exc}")


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _spi = _init_spi()
    if _spi is None:
        print("[FATAL] Cannot continue without SPI bus.")
        sys.exit(1)

    _bme280 = _init_bme280(_spi)
    if _bme280 is None:
        print("[WARN] BME280 not available; will retry on next cycle.")

    _epd = _init_epd()
    if _epd is None:
        print("[WARN] EPD not available; will retry on next cycle.")

    while _running:
        temp, hum, pres = _read_sensor(_bme280)

        if temp is not None and hum is not None and pres is not None:
            if _epd is not None:
                _update_display(_epd, temp, hum, pres)
            else:
                print(f"Sensor OK  Temp: {temp:.1f} C  Hum: {hum:.1f} %  Pres: {pres:.1f} hPa")
        else:
            print("[WARN] Skipping display update due to sensor read failure.")

        # Sleep in small increments so signals are caught promptly
        slept = 0
        while _running and slept < UPDATE_INTERVAL_S:
            time.sleep(1)
            slept += 1

    _cleanup()


if __name__ == "__main__":
    main()

