import os
import time
import datetime
import logging
import argparse
import configparser
import signal
import sys

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None


class CameraHandler:
    """Handles camera operations using picamera2."""

    def __init__(self, storage_directory, config_file):
        self.storage_directory = storage_directory
        self.config_file = config_file
        self.camera = None
        self.gpio_initialized = False
        self.pir_pin = None
        self.logger = None
        self.disk_space_threshold_mb = None

    def initialize_camera(self):
        """Initializes the camera and GPIO."""
        if Picamera2 is None:
            self.logger.error("picamera2 library not installed.")
            return False

        try:
            self.camera = Picamera2()
            self.camera.configure(self.camera.create_still_configuration())
            self.camera.start()
            self.logger.info("Camera initialized successfully.")
            return True
        except Exception as e:
            self.logger.error(f"Error initializing camera: {e}")
            self.camera = None
            return False

    def initialize_gpio(self):
        """Initializes the GPIO pin for the PIR sensor."""
        if GPIO is None:
            self.logger.error("RPi.GPIO library not installed.")
            return False

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pir_pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            self.gpio_initialized = True
            self.logger.info(f"GPIO pin {self.pir_pin} initialized successfully.")
            return True
        except Exception as e:
            self.logger.error(f"Error initializing GPIO: {e}")
            self.gpio_initialized = False
            return False

    def capture_image(self, filename):
        """Captures a still image with quality 85 and value 64."""
        if not self.camera:
            self.logger.warning("Camera not initialized. Skipping image capture.")
            return False

        try:
            self.camera.capture_file(filename, format='jpeg')
            self.logger.info(f"Image captured: {filename}")
            return True
        except Exception as e:
            self.logger.error(f"Error capturing image: {e}")
            return False

    def capture_video(self, filename, duration=5, bitrate=1700000, framerate=20):
        """Captures a video with the specified parameters."""
        if not self.camera:
            self.logger.warning("Camera not initialized. Skipping video capture.")
            return False

        try:
            self.camera.start_recording(filename, quality=64, bitrate=bitrate, framerate=framerate)
            time.sleep(duration)
            self.camera.stop_recording()
            self.logger.info(f"Video captured: {filename}")
            return True
        except Exception as e:
            self.logger.error(f"Error capturing video: {e}")
            return False

    def detect_motion(self):
        """Detects motion using the PIR sensor."""
        if not self.gpio_initialized:
            return False

        try:
            return GPIO.input(self.pir_pin) == GPIO.HIGH
        except Exception as e:
            self.logger.error(f"Error reading PIR sensor: {e}")
            return False

    def manage_disk_space(self):
        """Manages disk space by deleting old files."""
        try:
            total, used, free = self.get_disk_usage(self.storage_directory)
            if free < self.disk_space_threshold_mb:
                self.logger.warning("Disk space low. Deleting old files.")
                self.delete_oldest_files()
        except Exception as e:
            self.logger.error(f"Error managing disk space: {e}")

    def get_disk_usage(self, path):
        """Gets disk usage information."""
        statvfs = os.statvfs(path)
        total_space = statvfs.f_blocks * statvfs.f_frsize
        available_space = statvfs.f_bavail * statvfs.f_frsize
        used_space = total_space - available_space
        return total_space, used_space, available_space

    def delete_oldest_files(self):
        """Deletes the oldest files to free up disk space."""
        try:
            files = self.get_files_in_directory(self.storage_directory)
            if not files:
                return

            files.sort(key=os.path.getmtime)
            for file_path in files:
                try:
                    os.remove(file_path)
                    self.logger.info(f"Deleted old file: {file_path}")
                    total, used, free = self.get_disk_usage(self.storage_directory)
                    if free >= self.disk_space_threshold_mb:
                        return
                except Exception as e:
                    self.logger.error(f"Error deleting file: {e}")
                    return
        except Exception as e:
            self.logger.error(f"Error deleting oldest files: {e}")

    def get_files_in_directory(self, directory):
        """Gets a list of files in a directory."""
        try:
            return [os.path.join(directory, f) for f in os.listdir(directory)
                    if os.path.isfile(os.path.join(directory, f))]
        except Exception as e:
            self.logger.error(f"Error getting files in directory: {e}")
            return []

    def cleanup(self):
        """Releases camera and GPIO resources."""
        if self.camera:
            try:
                self.camera.stop()
                self.camera.close()
                self.logger.info("Camera released.")
            except Exception as e:
                self.logger.error(f"Error releasing camera: {e}")
            finally:
                self.camera = None

        if self.gpio_initialized and GPIO:
            try:
                GPIO.cleanup()
                self.logger.info("GPIO cleaned up.")
            except Exception as e:
                self.logger.error(f"Error cleaning up GPIO: {e}")
            finally:
                self.gpio_initialized = False


def parse_arguments():
    """Parses command-line arguments."""
    parser = argparse.ArgumentParser(description="Raspberry Pi Security Camera System")
    parser.add_argument("--storage_directory", default="storage",
                        help="Directory to store captured images and videos")
    parser.add_argument("--config_file", default="config.ini",
                        help="Path to the configuration file")
    return parser.parse_args()


def load_config(config_file):
    """Loads configuration from the config file."""
    config = configparser.ConfigParser()
    if not os.path.exists(config_file):
        default_config = {
            'DEFAULT': {
                'log_file': 'security_camera.log',
                'disk_space_threshold_mb': '500',
                'pir_pin': '4'
            }
        }
        with open(config_file, 'w') as f:
            config.read_string(configparser.ConfigParser().write(default_config))
            config.write(f)
        print(f"Created default config file: {config_file}")

    config.read(config_file)
    return config


def setup_logging(log_file):
    """Sets up logging."""
    log_dir = os.path.dirname(log_file)
    try:
        os.makedirs(log_dir, exist_ok=True)
        logging.basicConfig(filename=log_file, level=logging.INFO,
                            format='%(asctime)s - %(levelname)s - %(message)s')
    except Exception as e:
        print(f"Failed to create log directory {log_dir}: {e}. Falling back to stdout.")
        logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


def signal_handler(signum, frame, camera_handler):
    """Handles signals for graceful shutdown."""
    logging.info(f"Received signal {signum}. Shutting down...")
    camera_handler.cleanup()
    sys.exit(0)


def main():
    """Main function."""
    args = parse_arguments()
    config = load_config(args.config_file)
    log_file = config.get('DEFAULT', 'log_file')
    storage_directory = args.storage_directory
    disk_space_threshold_mb = int(config.get('DEFAULT', 'disk_space_threshold_mb'))
    pir_pin = int(config.get('DEFAULT', 'pir_pin'))

    setup_logging(log_file)
    logger = logging.getLogger(__name__)
    logger.info("Starting Raspberry Pi Security Camera System")

    camera_handler = CameraHandler(storage_directory, args.config_file)
    camera_handler.logger = logger
    camera_handler.disk_space_threshold_mb = disk_space_threshold_mb
    camera_handler.pir_pin = pir_pin

    if not camera_handler.initialize_camera():
        logger.error("Failed to initialize camera. Exiting.")
        sys.exit(1)

    if not camera_handler.initialize_gpio():
        logger.warning("Failed to initialize GPIO. Continuing without PIR sensor.")

    signal.signal(signal.SIGINT, lambda s, f: signal_handler(s, f, camera_handler))
    signal.signal(signal.SIGTERM, lambda s, f: signal_handler(s, f, camera_handler))

    try:
        while True:
            if camera_handler.detect_motion():
                timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
                date_dir = os.path.join(storage_directory, datetime.datetime.now().strftime("%Y/%m/%d"))
                os.makedirs(date_dir, exist_ok=True)

                image_count = 0
                for i in range(3):
                    image_filename = os.path.join(date_dir, f"image_{timestamp}_{i+1}.jpg")
                    if camera_handler.capture_image(image_filename):
                        image_count += 1
                    time.sleep(0.5)

                if image_count > 0:
                    video_filename = os.path.join(date_dir, f"video_{timestamp}.h264")
                    camera_handler.capture_video(video_filename)

                time.sleep(2)

            camera_handler.manage_disk_space()
            time.sleep(1)

    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
    finally:
        camera_handler.cleanup()
        logger.info("Exiting Raspberry Pi Security Camera System")


if __name__ == "__main__":
    main()

