import sys
import time
import datetime
import random
import speech_recognition as sr
from gpiozero import OutputDevice

# Constants
DHT_PIN = 4
LIGHT_PIN = 17
WAKE_WORD = "Greenhouse"

# Global variables
lights_on = False
camera = None
dht_device = None

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Simulated GPIO class for fallback
class SimulatedOutputDevice:
    def __init__(self, pin):
        self.pin = pin
        self.state = False
    def on(self):
        self.state = True
    def off(self):
        self.state = False
    def close(self):
        pass

# Initialize GPIO using gpiozero
try:
    from gpiozero import OutputDevice
    lights = OutputDevice(LIGHT_PIN)
    logging.info("GPIO initialized successfully.")
except Exception as e:
    logging.warning(f"Failed to initialize GPIO: {e}. Using simulated GPIO.")
    lights = SimulatedOutputDevice(LIGHT_PIN)

# Initialize DHT11 sensor
try:
    import adafruit_dht
    import board
    dht_device = adafruit_dht.DHT11(board.D4)
    logging.info("DHT11 sensor initialized successfully.")
except Exception as e:
    logging.warning(f"Failed to initialize DHT11 sensor: {e}. Using simulated temperature.")
    dht_device = None

# Initialize Camera
try:
    from picamera2 import Picamera2
    camera = Picamera2()
    camera.configure(camera.create_still_configuration())
    camera.start()
    logging.info("Camera initialized successfully.")
except Exception as e:
    logging.warning(f"Failed to initialize camera: {e}. Using simulated camera.")
    camera = None

def read_temperature():
    """Reads temperature from DHT11 sensor or simulates it."""
    if dht_device is not None:
        try:
            temperature = dht_device.temperature
            if temperature is not None:
                return temperature
            else:
                logging.warning("DHT11 returned None temperature.")
        except RuntimeError as e:
            logging.warning(f"DHT11 read error: {e}. Using simulated temperature.")
        except Exception as e:
            logging.error(f"Unexpected error reading DHT11: {e}. Using simulated temperature.")
    return random.uniform(15, 35)

def take_picture():
    """Takes a picture using the camera or simulates it."""
    if camera is not None:
        try:
            timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
            filename = f"greenhouse_{timestamp}.jpg"
            camera.capture(filename)
            logging.info(f"Picture taken and saved as {filename}")
            return filename
        except Exception as e:
            logging.error(f"Error taking picture: {e}")
            return None
    logging.info("Simulating taking a picture.")
    timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    return f"greenhouse_{timestamp}.jpg"

def control_lights(command):
    """Controls the lights based on the given command."""
    global lights_on
    if "turn on the lights" in command:
        lights.on()
        lights_on = True
        logging.info("Lights turned on.")
    elif "turn off the lights" in command:
        lights.off()
        lights_on = False
        logging.info("Lights turned off.")
    else:
        logging.info(f"Lights command not recognized: {command}")

def process_command(command):
    """Processes the given voice command."""
    if "what is the temperature" in command:
        temperature = read_temperature()
        logging.info(f"Temperature: {temperature:.1f}°C")
    elif "take a picture" in command:
        filename = take_picture()
        if filename:
            logging.info(f"Picture saved as {filename}")
    else:
        logging.info(f"Command not recognized: {command}")

def cleanup(signum=None, frame=None):
    """Clean up resources on exit."""
    logging.info("Cleaning up resources...")
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
    if camera is not None:
        try:
            camera.stop()
            camera.close()
        except Exception:
            pass
    if lights is not None:
        lights.close()
    sys.exit(0)

def main():
    """Main function to run the greenhouse control system."""
    parser = argparse.ArgumentParser(description="Greenhouse Control System")
    parser.add_argument("--wake_word", default=WAKE_WORD, help="Wake word to activate the system")
    args = parser.parse_args()
    WAKE_WORD = args.wake_word

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    recognizer = sr.Recognizer()

    try:
        with sr.Microphone() as source:
            recognizer.adjust_for_ambient_noise(source, duration=0.5)
            logging.info("Say something!")
            audio = recognizer.listen(source, timeout=5)

        try:
            command = recognizer.recognize_google(audio).lower()
            logging.info(f"You said: {command}")

            if WAKE_WORD in command:
                command = command.replace(WAKE_WORD, "")
                process_command(command)
            else:
                logging.info("Wake word not detected.")

        except sr.UnknownValueError:
            logging.warning("Google Web Speech API could not understand audio")
        except sr.RequestError as e:
            logging.error(f"Could not request results from Google Web Speech API; {e}")

    except sr.WaitTimeoutError:
        logging.info("Listening timeout. No speech detected.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

