import io
import os
import time
import signal
import logging
import configparser
from datetime import datetime

import numpy as np
import cv2
import smbus
from picamera2 import Picamera2
from picamera2.encoders import H264Encoder
from picamera2.outputs import FfmpegOutput

CONFIG_FILE = 'config.ini'
DEFAULT_CONFIG = {
    'camera': {
        'fps': '24',
        'resolution_width': '640',
        'resolution_height': '480',
        'low_res_width': '320',
        'low_res_height': '240',
    },
    'motion_detection': {
        'motion_threshold': '25',
        'motion_sensitivity': '50',
        'debounce_time': '5',
        'recording_duration': '10',
    },
    'storage': {
        'disk_space_limit': '5000',
    },
    'logging': {
        'log_level': 'INFO',
    },
}

running = True


def signal_handler(signum, frame):
    global running
    running = False


def load_config(config_file):
    config = configparser.ConfigParser()
    config.read(config_file)
    for section, defaults in DEFAULT_CONFIG.items():
        if section not in config:
            config[section] = {}
        for option, value in defaults.items():
            config.set(section, option, value)
    return config


def log_message(level, message):
    logging.log(level, message)


def log_error(message):
    log_message(logging.ERROR, message)


def log_info(message):
    log_message(logging.INFO, message)


def log_debug(message):
    log_message(logging.DEBUG, message)


def parse_int(config, section, option, fallback):
    try:
        return int(config.get(section, option))
    except ValueError:
        log_error(f"Invalid integer for [{section}][{option}], using fallback {fallback}")
        return fallback


def parse_float(config, section, option, fallback):
    try:
        return float(config.get(section, option))
    except ValueError:
        log_error(f"Invalid float for [{section}][{option}], using fallback {fallback}")
        return fallback


def parse_bool(config, section, option, fallback):
    try:
        return config.getboolean(section, option)
    except ValueError:
        log_error(f"Invalid boolean for [{section}][{option}], using fallback {fallback}")
        return fallback


def parse_string(config, section, option, fallback):
    return config.get(section, option)


def initialize_camera(config):
    try:
        picam2 = Picamera2()
        video_config = picam2.create_video_configuration(
            main={"size": (
                parse_int(config, 'camera', 'resolution_width', 640),
                parse_int(config, 'camera', 'resolution_height', 480),
            )},
            lores={"size": (
                parse_int(config, 'camera', 'low_res_width', 320),
                parse_int(config, 'camera', 'low_res_height', 240),
            )},
            encode="lores",
        )
        picam2.configure(video_config)
        picam2.start()
        log_info("Camera initialized successfully.")
        return picam2
    except Exception as e:
        log_error(f"Failed to initialize camera: {e}")
        return None


def initialize_i2c_bus():
    try:
        bus = smbus.SMBus(1)
        log_info("I2C bus initialized successfully.")
        return bus
    except Exception as e:
        log_error(f"Failed to initialize I2C bus: {e}")
        return None


def initialize_bh1750(bus):
    try:
        bus.write_byte(0x23, 0x01)
        time.sleep(0.01)
        bus.write_byte(0x23, 0x00)
        time.sleep(0.18)
        data = bus.read_i2c_block_data(0x23, 0x00, 2)
        lux = (data[0] + (data[1] << 8)) / 1.2
        log_info(f"BH1750 initialized, ambient light: {lux:.2f} lux")
        return lux
    except Exception as e:
        log_error(f"Failed to initialize BH1750: {e}")
        return None


def read_bh1750(bus):
    try:
        bus.write_byte(0x23, 0x01)
        time.sleep(0.01)
        bus.write_byte(0x23, 0x00)
        time.sleep(0.18)
        data = bus.read_i2c_block_data(0x23, 0x00, 2)
        lux = (data[0] + (data[1] << 8)) / 1.2
        return lux
    except Exception as e:
        log_error(f"Failed to read BH1750: {e}")
        return None


def detect_motion(frame1, frame2, config):
    try:
        threshold = parse_int(config, 'motion_detection', 'motion_threshold', 25)
        sensitivity = parse_int(config, 'motion_detection', 'motion_sensitivity', 50)
        diff = cv2.absdiff(frame1, frame2)
        gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
        _, thresh = cv2.threshold(gray, threshold, 255, cv2.THRESH_BINARY)
        contours, _ = cv2.findContours(thresh, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        for contour in contours:
            if cv2.contourArea(contour) > (sensitivity * 10):
                return True
        return False
    except Exception as e:
        log_error(f"Error detecting motion: {e}")
        return False


def record_video(picam2, config, bus, light_sensor_enabled):
    global running
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    filename = f"/home/pi/security_footage/camera1_{timestamp}.h264"
    log_info(f"Motion detected, starting recording: {filename}")

    try:
        encoder = H264Encoder(bitrate=10000000)
        output = FfmpegOutput(filename)
        picam2.start_encoder(encoder, output)

        start_time = time.time()
        recording_duration = parse_int(config, 'motion_detection', 'recording_duration', 10)
        debounce_time = parse_int(config, 'motion_detection', 'debounce_time', 5)

        while running and (time.time() - start_time < recording_duration):
            time.sleep(0.1)

        picam2.stop_encoder()

        log_info("Video recording complete.")

        if light_sensor_enabled:
            light_level = read_bh1750(bus)
            if light_level is not None:
                log_info(f"Ambient light level: {light_level:.2f} lux")

        time.sleep(debounce_time)

    except Exception as e:
        log_error(f"Error recording video: {e}")
        try:
            picam2.stop_encoder()
        except Exception:
            pass


def manage_disk_space(config):
    try:
        disk_space_limit = parse_int(config, 'storage', 'disk_space_limit', 5000)
        footage_directory = "/home/pi/security_footage"
        if not os.path.exists(footage_directory):
            os.makedirs(footage_directory)

        total_size = 0
        files = []
        for filename in os.listdir(footage_directory):
            filepath = os.path.join(footage_directory, filename)
            if os.path.isfile(filepath):
                total_size += os.path.getsize(filepath)
                files.append((os.path.getmtime(filepath), filepath))

        files.sort()

        while total_size > disk_space_limit and files:
            oldest_file = files.pop()
            filepath = oldest_file[1]
            try:
                os.remove(filepath)
                total_size -= os.path.getsize(filepath)
                log_info(f"Deleted oldest file: {filepath}")
            except Exception as e:
                log_error(f"Error deleting file {filepath}: {e}")
    except Exception as e:
        log_error(f"Error managing disk space: {e}")


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config(CONFIG_FILE)
    log_level = parse_string(config, 'logging', 'log_level', 'INFO')
    logging.basicConfig(level=log_level, format='%(asctime)s - %(levelname)s - %(message)s')

    picam2 = initialize_camera(config)
    if picam2 is None:
        log_error("Camera initialization failed. Exiting.")
        return

    bus = initialize_i2c_bus()
    light_sensor_enabled = bus is not None
    if light_sensor_enabled:
        initialize_bh1750(bus)

    try:
        while running:
            frame1 = picam2.capture_array("lores")
            if frame1 is None:
                log_error("Failed to capture frame1")
                time.sleep(1)
                continue

            time.sleep(0.1)
            frame2 = picam2.capture_array("lores")
            if frame2 is None:
                log_error("Failed to capture frame2")
                time.sleep(1)
                continue

            if detect_motion(frame1, frame2, config):
                record_video(picam2, config, bus, light_sensor_enabled)

            manage_disk_space(config)

    except Exception as e:
        log_error(f"Unexpected error in main loop: {e}")
    finally:
        log_info("Shutting down...")
        try:
            picam2.stop()
        except Exception:
            pass
        try:
            if bus:
                bus.close()
        except Exception:
            pass
        log_info("Shutdown complete.")


if __name__ == "__main__":
    main()

