        debounce_time = parse_int(config, 'motion_detection', 'debounce_time', 5)

        while running and (time.time() - start_time < recording_duration):
            time.sleep(0.1)

        picam2.stop_encoder()

        log_info("Video recording complete.")

        if light_sensor_enabled:
            light_level = read_bh1750(bus)
            if light_level is not None:
                log_info(f"Ambient light level: {light_level:.2f} lux")

        time.sleep(debounce_time)

    except Exception as e:
        log_error(f"Error recording video: {e}")
        try:
            picam2.stop_encoder()
        except Exception:
            pass


def manage_disk_space(config):
    try:
        disk_space_limit = parse_int(config, 'storage', 'disk_space_limit', 5000)
        footage_directory = "/home/pi/security_footage"
        if not os.path.exists(footage_directory):
            os.makedirs(footage_directory)

        total_size = 0
        files = []
        for filename in os.listdir(footage_directory):
            filepath = os.path.join(footage_directory, filename)
            if os.path.isfile(filepath):
                total_size += os.path.getsize(filepath)
                files.append((os.path.getmtime(filepath), filepath))

        files.sort()

        while total_size > disk_space_limit and files:
            oldest_file = files.pop()
            filepath = oldest_file[1]
            try:
                os.remove(filepath)
                total_size -= os.path.getsize(filepath)
                log_info(f"Deleted oldest file: {filepath}")
            except Exception as e:
                log_error(f"Error deleting file {filepath}: {e}")
    except Exception as e:
        log_error(f"Error managing disk space: {e}")


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config(CONFIG_FILE)
    log_level = parse_string(config, 'logging', 'log_level', 'INFO')
    logging.basicConfig(level=log_level, format='%(asctime)s - %(levelname)s - %(message)s')

    picam2 = initialize_camera(config)
    if picam2 is None:
        log_error("Camera initialization failed. Exiting.")
        return

    bus = initialize_i2c_bus()
    light_sensor_enabled = bus is not None
    if light_sensor_enabled:
        initialize_bh1750(bus)

    try:
        while running:
            frame1 = picam2.capture_array("lores")
            if frame1 is None:
                log_error("Failed to capture frame1")
                time.sleep(1)
                continue

            time.sleep(0.1)
            frame2 = picam2.capture_array("lores")
            if frame2 is None:
                log_error("Failed to capture frame2")
                time.sleep(1)
                continue

            if detect_motion(frame1, frame2, config):
                record_video(picam2, config, bus, light_sensor_enabled)

            manage_disk_space(config)

    except Exception as e:
        log_error(f"Unexpected error in main loop: {e}")
    finally:
        log_info("Shutting down...")
        try:
            picam2.stop()
        except Exception:
            pass
        try:
            if bus:
                bus.close()
        except Exception:
            pass
        log_info("Shutdown complete.")


if __name__ == "__main__":
    main()

