import cv2
import logging
import signal
import sys
import time

import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

OUTPUT_PIN = 17
ROI = (slice(10, 150), slice(40, 280))

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_gpio(pin):
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
    logging.info(f"GPIO pin {pin} initialized HIGH.")

def initialize_camera():
    try:
        cap = cv2.VideoCapture(0, cv2.CAP_V4L2)
        if not cap.isOpened():
            raise RuntimeError("Failed to open camera (sensor absent or bus error).")
        cap.set(cv2.CAP_PROP_FRAME_RATE, 10)
        logging.info("Camera initialized at 10 fps.")
        return cap
    except Exception as e:
        logging.error(f"Camera initialization failed: {e}")
        return None

def process_frame(frame):
    try:
        return frame[ROI]
    except Exception as e:
        logging.error(f"Frame processing failed: {e}")
        return None

def display_frame(frame):
    try:
        cv2.imshow("Output Image", frame)
    except Exception as e:
        logging.error(f"Display failed: {e}")

def cleanup(cap, pin):
    logging.info("Cleaning up resources...")
    try:
        if cap is not None:
            cap.release()
    except Exception as e:
        logging.error(f"Error releasing camera: {e}")
    try:
        cv2.destroyAllWindows()
    except Exception as e:
        logging.error(f"Error destroying windows: {e}")
    try:
        GPIO.output(pin, GPIO.LOW)
        GPIO.cleanup(pin)
        logging.info("GPIO pin turned off and cleaned up.")
    except Exception as e:
        logging.error(f"Error cleaning up GPIO: {e}")

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    initialize_gpio(OUTPUT_PIN)
    cap = initialize_camera()
    if cap is None:
        cleanup(None, OUTPUT_PIN)
        sys.exit(1)

    try:
        while _running:
            ret, frame = cap.read()
            if not ret:
                logging.error("Failed to grab frame.")
                break

            processed_frame = process_frame(frame)
            if processed_frame is not None:
                display_frame(processed_frame)

            key = cv2.waitKey(1) & 0xFF
            if key == 10:
                logging.info("Enter key pressed, exiting.")
                break
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        cleanup(cap, OUTPUT_PIN)

if __name__ == "__main__":
    main()

