import os
import time
import csv
import socket
import signal
import logging
import datetime
from typing import Optional, Tuple

from libcamera import Transform
from libcamera import controls

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)


class Camera:
    """Wrapper around libcamera.Camera with robust error handling and cleanup."""

    def __init__(self, device_id: int):
        self.device_id = device_id
        self.camera: Optional["libcamera.Camera"] = None
        self._connected = False
        self._initialize()

    def _initialize(self) -> None:
        try:
            self.camera = libcamera.Camera(self.device_id)
            self.camera.set_controls({"ScalerCrop": (0, 0, self.camera.width, self.camera.height)})
            self._connected = True
            logging.info(f"Camera {self.device_id} initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize camera {self.device_id}: {e}")
            self.camera = None
            self._connected = False

    def capture_array(self) -> Optional[bytes]:
        if not self._connected or self.camera is None:
            logging.error(f"Camera {self.device_id} not connected. Cannot capture.")
            return None
        try:
            return self.camera.capture_array()
        except Exception as e:
            logging.error(f"Error capturing image from camera {self.device_id}: {e}")
            return None

    def stop(self) -> None:
        if self._connected and self.camera is not None:
            try:
                self.camera.stop()
            except Exception as e:
                logging.error(f"Error stopping camera {self.device_id}: {e}")
        self._connected = False

    def close(self) -> None:
        if self._connected and self.camera is not None:
            try:
                self.camera.close()
            except Exception as e:
                logging.error(f"Error closing camera {self.device_id}: {e}")
        self._connected = False


class MetadataLogger:
    """Handles metadata logging to CSV and TCP transmission."""

    def __init__(self, metadata_path: str, server_ip: str, server_port: int):
        self.metadata_path = metadata_path
        self.server_ip = server_ip
        self.server_port = server_port
        self._init_csv()

    def _init_csv(self) -> None:
        try:
            os.makedirs(os.path.dirname(self.metadata_path), exist_ok=True)
            with open(self.metadata_path, 'a', newline='') as csvfile:
                writer = csv.writer(csvfile)
                if csvfile.tell() == 0:
                    writer.writerow(['Timestamp', 'Left Image', 'Right Image', 'Resolution', 'Exposure', 'Brightness', 'Contrast'])
        except OSError as e:
            logging.error(f"Error initializing CSV file: {e}")

    def log_metadata(self, timestamp: str, left_image: str, right_image: str, resolution: Tuple[int, int], exposure: int, brightness: int, contrast: int) -> None:
        try:
            with open(self.metadata_path, 'a', newline='') as csvfile:
                writer = csv.writer(csvfile)
                writer.writerow([timestamp, left_image, right_image, resolution, exposure, brightness, contrast])
        except OSError as e:
            logging.error(f"Error writing to CSV file: {e}")

    def transmit_metadata(self, timestamp: str, left_image: str, right_image: str, resolution: Tuple[int, int], exposure: int, brightness: int, contrast: int) -> None:
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
                sock.settimeout(5.0)
                sock.connect((self.server_ip, self.server_port))
                message = (
                    f"Timestamp: {timestamp}\n"
                    f"Left Image: {left_image}\n"
                    f"Right Image: {right_image}\n"
                    f"Resolution: {resolution}\n"
                    f"Exposure: {exposure}\n"
                    f"Brightness: {brightness}\n"
                    f"Contrast: {contrast}\n"
                )
                sock.sendall(message.encode('utf-8'))
        except (socket.timeout, ConnectionRefusedError, OSError) as e:
            logging.error(f"Error transmitting metadata: {e}")


def capture_and_save_images(camera_left: Camera, camera_right: Camera, image_dir: str, metadata_logger: MetadataLogger) -> None:
    timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    left_image_path = os.path.join(image_dir, f"{timestamp}_left.jpg")
    right_image_path = os.path.join(image_dir, f"{timestamp}_right.jpg")

    left_array = camera_left.capture_array()
    right_array = camera_right.capture_array()

    if left_array is not None and right_array is not None:
        try:
            import cv2
            left_img = cv2.imdecode(left_array, cv2.IMREAD_COLOR)
            right_img = cv2.imdecode(right_array, cv2.IMREAD_COLOR)

            if left_img is not None and right_img is not None:
                cv2.imwrite(left_image_path, left_img)
                cv2.imwrite(right_image_path, right_img)

                resolution = (camera_left.camera.width, camera_left.camera.height)
                exposure = camera_left.camera.get_control("ExposureTime")
                brightness = camera_left.camera.get_control("Brightness")
                contrast = camera_left.camera.get_control("Contrast")

                metadata_logger.log_metadata(timestamp, left_image_path, right_image_path, resolution, exposure, brightness, contrast)
                metadata_logger.transmit_metadata(timestamp, left_image_path, right_image_path, resolution, exposure, brightness, contrast)
            else:
                logging.error("Failed to decode captured arrays.")
        except Exception as e:
            logging.error(f"Error saving or processing images: {e}")
    else:
        logging.error("Failed to capture images from one or both cameras.")


def main() -> None:
    camera_left = Camera(0)
    camera_right = Camera(1)
    metadata_logger = MetadataLogger("images/metadata.csv", "127.0.0.1", 65432)
    image_dir = "images"

    os.makedirs(image_dir, exist_ok=True)

    def signal_handler(signum, frame):
        logging.info(f"Signal {signum} received. Shutting down gracefully...")
        camera_left.stop()
        camera_left.close()
        camera_right.stop()
        camera_right.close()
        os._exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            capture_and_save_images(camera_left, camera_right, image_dir, metadata_logger)
            time.sleep(1.0)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        camera_left.stop()
        camera_left.close()
        camera_right.stop()
        camera_right.close()
        logging.info("Cameras stopped and closed. Exiting.")


if __name__ == "__main__":
    main()

