import os
import time
import logging
import threading
import queue
import json
import signal
import sys
import cv2
import numpy as np
import pyzbar.pyzbar as pyzbar
from PIL import Image
from typing import Optional, Tuple, List, Any

CONFIG_FILE = "config.ini"
DEFAULT_CONFIG = {
    "DEFAULT": {
        "motion_threshold": "25",
        "redundancy_time_window": "10.0",
        "reinit_delay": "5.0",
        "frame_buffer_size": "5",
        "cloud_upload_interval": "60",
        "log_level": "INFO",
        "camera_1_device_id": "/dev/video0",
        "camera_2_device_id": "/dev/video2",
    }
}


class QRCodeScanner:
    def __init__(self, config: dict):
        self.config = config
        self.inventory_data: dict = {}
        self.lock = threading.Lock()
        self.running = True
        self.last_scan_time: dict = {}
        self.frame_buffers: dict = {}
        self.camera_resources: dict = {}
        self.worker_threads: list = []
        self.log_level = self.config["DEFAULT"]["log_level"]
        self.setup_logging()
        self.setup_signal_handlers()
        self.setup_cameras()

    def setup_logging(self) -> None:
        log_level = getattr(logging, self.log_level.upper(), logging.INFO)
        logging.basicConfig(
            level=log_level,
            format="%(asctime)s - %(levelname)s - %(message)s",
            handlers=[
                logging.FileHandler("inventory.log"),
                logging.StreamHandler(sys.stdout),
            ],
        )

    def setup_signal_handlers(self) -> None:
        signal.signal(signal.SIGINT, self.signal_handler)
        signal.signal(signal.SIGTERM, self.signal_handler)

    def signal_handler(self, signum, frame) -> None:
        logging.info(f"Signal {signum} received, shutting down gracefully...")
        self.running = False
        self.cleanup()
        sys.exit(0)

    def setup_cameras(self) -> None:
        for idx, device_id in enumerate(["camera_1_device_id", "camera_2_device_id"]):
            try:
                cap = cv2.VideoCapture(device_id)
                if not cap.isOpened():
                    raise IOError(f"Could not open camera at {device_id}")
                cap.set(cv2.CAP_PROP_FRAME_WIDTH, 640)
                cap.set(cv2.CAP_PROP_FRAME_HEIGHT, 480)
                self.camera_resources[idx] = cap
                self.frame_buffers[idx] = []
                self.last_scan_time[idx] = 0.0
                logging.info(f"Camera {idx + 1} initialized at {device_id}")
            except Exception as e:
                logging.error(f"Error initializing camera {idx + 1}: {e}")
                self.camera_resources[idx] = None

    def decode_qr_code(self, frame: np.ndarray) -> Optional[str]:
        try:
            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            decoded_objects = pyzbar.decode(gray)
            if decoded_objects:
                return decoded_objects[0].data.decode("utf-8")
            return None
        except Exception as e:
            logging.error(f"Error decoding QR code: {e}")
            return None

    def detect_motion(self, frame1: np.ndarray, frame2: np.ndarray) -> bool:
        try:
            diff = cv2.absdiff(frame1, frame2)
            gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
