import time
import signal
import threading
import numpy as np
import cv2

CONFIG_FILE = "config.txt"
SNAPSHOT_DIR = "snapshots"

running = True

def signal_handler(sig, frame):
    global running
    running = False

def load_config(filename):
    config = {}
    try:
        with open(filename, "r") as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith("#"):
                    if "=" in line:
                        key, value = line.split("=", 1)
                        config[key.strip()] = value.strip()
        return config
    except FileNotFoundError:
        print(f"Error: Configuration file '{filename}' not found.")
        return None
    except Exception as e:
        print(f"Error parsing configuration file: {e}")
        return None

def parse_int(value, key):
    try:
        return int(value)
    except ValueError:
        print(f"Error: Invalid integer value for '{key}' in config.")
        return None

def parse_float(value, key):
    try:
        return float(value)
    except ValueError:
        print(f"Error: Invalid float value for '{key}' in config.")
        return None

def parse_bool(value, key):
    try:
        return value.lower() in ("true", "1", "yes")
    except AttributeError:
        print(f"Error: Invalid boolean value for '{key}' in config.")
        return None

def initialize_camera():
    try:
        cap = cv2.VideoCapture(0, cv2.CAP_V4L2)
        if not cap.isOpened():
            print("Error: Could not open CSI camera (V4L2).")
            return None
        return cap
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def get_frame(cap):
    try:
        ret, frame = cap.read()
        if not ret or frame is None:
            print("Error: Could not read frame from camera.")
            return None
        return frame
    except Exception as e:
        print(f"Error capturing frame: {e}")
        return None

def calculate_roi_difference(frame1, frame2, roi_x1, roi_y1, roi_x2, roi_y2):
    try:
        roi1 = frame1[roi_y1:roi_y2, roi_x1:roi_x2]
        roi2 = frame2[roi_y1:roi_y2, roi_x1:roi_x2]
        diff = cv2.absdiff(roi1.astype(np.uint8), roi2.astype(np.uint8))
        gray = cv2.cvtColor(diff, cv2.COLOR_RGB2GRAY)
        return gray
    except Exception as e:
        print(f"Error calculating ROI difference: {e}")
        return None

def detect_motion(gray, motion_threshold):
    try:
        diff = cv2.threshold(gray, motion_threshold, 255, cv2.THRESH_BINARY)[1]
        motion_pixels = np.count_nonzero(diff)
        total_pixels = diff.size
        if total_pixels == 0:
            return 0.0
        return (motion_pixels * 100.0) / total_pixels
    except Exception as e:
        print(f"Error detecting motion: {e}")
        return None

def get_cpu_temperature():
    try:
        with open("/sys/class/thermal/thermal_zone0/temp", "r") as f:
            temp_raw = f.read().strip()
            return float(temp_raw) / 1000.0
    except Exception as e:
        print(f"Error reading CPU temperature: {e}")
        return None

