    signal.signal(signal.SIGINT, signal_handler)

    config = load_config(CONFIG_FILE)
    if config is None:
        sys.exit(1)

    roi_x1 = parse_int(config.get("roi_x1", "0"), "roi_x1")
    roi_y1 = parse_int(config.get("roi_y1", "0"), "roi_y1")
    roi_x2 = parse_int(config.get("roi_x2", "640"), "roi_x2")
    roi_y2 = parse_int(config.get("roi_y2", "480"), "roi_y2")
    motion_threshold = parse_int(config.get("motion_threshold", "25"), "motion_threshold")
    confirmation_delay = parse_int(config.get("confirmation_delay", "2"), "confirmation_delay")
    temperature_threshold = parse_float(config.get("temperature_threshold", "80.0"), "temperature_threshold")
    simulated_temperature = parse_bool(config.get("simulated_temperature", "false"), "simulated_temperature")

    if roi_x1 is None or roi_y1 is None or roi_x2 is None or roi_y2 is None or motion_threshold is None or confirmation_delay is None or temperature_threshold is None or simulated_temperature is None:
        print("Error: Invalid configuration values.")
        sys.exit(1)

    if roi_x1 < 0 or roi_y1 < 0 or roi_x2 > 640 or roi_y2 > 480:
        print("Error: ROI coordinates out of bounds.")
        sys.exit(1)

    if motion_threshold < 0 or motion_threshold > 255:
        print("Error: Motion threshold must be between 0 and 255.")
        sys.exit(1)

    if confirmation_delay < 0:
        print("Error: Confirmation delay must be non-negative.")
        sys.exit(1)

    if temperature_threshold < 0:
        print("Error: Temperature threshold must be non-negative.")
        sys.exit(1)

    cap = initialize_camera()
    if cap is None:
        sys.exit(1)

    try:
        while running:
            frame1 = get_frame(cap)
            if frame1 is None:
                time.sleep(0.1)
                continue

            time.sleep(0.1)
            frame2 = get_frame(cap)
            if frame2 is None:
                continue

            gray = calculate_roi_difference(frame1, frame2, roi_x1, roi_y1, roi_x2, roi_y2)
            if gray is None:
                continue

            motion_percentage = detect_motion(gray, motion_threshold)
            if motion_percentage is not None:
                print(f"Motion detected: {motion_percentage:.2f}%")
                time.sleep(confirmation_delay)
                if running:
                    print("Motion confirmed!")
                    save_snapshot(frame2, SNAPSHOT_DIR)

            if not simulated_temperature:
                cpu_temp = get_cpu_temperature()
                if cpu_temp is not None:
                    print(f"CPU Temperature: {cpu_temp:.2f}°C")
                    if cpu_temp > temperature_threshold:
                        print("Temperature Alert!")
            else:
                print("Simulated Temperature: 50.0°C")
                if 50.0 > temperature_threshold:
                    print("Temperature Alert!")

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cap.release()
        cv2.destroyAllWindows()
        print("Camera released. Exiting.")

if __name__ == "__main__":
    main()

