import cv2
import time
import os
import sys

IMAGE_DIR = "images"
MAX_ATTEMPTS = 3
CAPTURE_DELAY = 1.0
MAX_PICTURES = 5


def create_directory(dir_name):
    """Create a directory if it does not exist."""
    try:
        os.makedirs(dir_name, exist_ok=True)
    except OSError as e:
        print(f"Error creating directory '{dir_name}': {e}", file=sys.stderr)
        sys.exit(1)


def initialize_camera(camera_index=0, max_attempts=MAX_ATTEMPTS):
    """Initialize the camera with retry logic."""
    for attempt in range(1, max_attempts + 1):
        try:
            cap = cv2.VideoCapture(camera_index)
            if not cap.isOpened():
                raise RuntimeError("Failed to open camera")
            return cap
        except Exception as e:
            print(f"Attempt {attempt}/{max_attempts} to initialize camera failed: {e}", file=sys.stderr)
            if attempt < max_attempts:
                time.sleep(CAPTURE_DELAY)
    return None


def detect_faces(image, face_cascade):
    """Detect faces in an image using Haar cascade."""
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    return face_cascade.detectMultiScale(gray, scaleFactor=1.3, minNeighbors=5)


def draw_rectangle(image, faces):
    """Draw rectangles around detected faces."""
    for (x, y, w, h) in faces:
        cv2.rectangle(image, (x, y), (x + w, y + h), (255, 0, 0), 2)
    return image


def capture_and_save_image(cap, face_cascade, image_dir, name, count):
    """Capture a frame, detect faces, draw rectangles, and save the image."""
    ret, frame = cap.read()
    if not ret or frame is None:
        print("Failed to capture frame.", file=sys.stderr)
        return False

    faces = detect_faces(frame, face_cascade)
    if len(faces) == 0:
        print("No face detected.")
        return False

    display_frame = draw_rectangle(frame, faces)
    cv2.imshow("Faces", display_frame)
    key = cv2.waitKey(1) & 0xFF

    if key == ord('q'):
        return False
    elif key == ord('y'):
        x, y, w, h = faces[0]
        cropped_face = frame[y:y + h, x:x + w]
        filename = os.path.join(image_dir, f"{name}_{count}.jpg")
        success = cv2.imwrite(filename, cropped_face)
        if success:
            print(f"Saved {filename}")
        else:
            print(f"Failed to save {filename}", file=sys.stderr)
        return True
    return False


def main():
    """Main function to capture and save face images."""
    create_directory(IMAGE_DIR)

    face_cascade = cv2.CascadeClassifier(cv2.data.haarcascades + 'haarcascade_frontalface_default.xml')
    if face_cascade.empty():
        print("Failed to load Haar cascade classifier.", file=sys.stderr)
        sys.exit(1)

    cap = initialize_camera()
    if cap is None:
        print("Failed to initialize camera after multiple attempts.", file=sys.stderr)
        sys.exit(1)

    name = input("What's their name? ").strip()
    if not name:
        print("Name cannot be empty.", file=sys.stderr)
        cap.release()
        sys.exit(1)

    count = 1
    try:
        while count <= MAX_PICTURES:
            if not capture_and_save_image(cap, face_cascade, IMAGE_DIR, name, count):
                break
            count += 1
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        cap.release()
        cv2.destroyAllWindows()
        print("Camera released and windows closed.")


if __name__ == "__main__":
    main()

