import time
import datetime
import os
import json
import logging
import logging.handlers
import threading
import signal
import sys
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

try:
    import smbus2
except ImportError:
    smbus2 = None

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

try:
    from adafruit_amg88xx import AMG88XX
except ImportError:
    AMG88XX = None

CONFIG_FILE = 'config.json'
DEFAULT_CONFIG = {
    'sampling_rate': 5,
    'motion_detection_threshold': 1.0,
    'logging_file_path': 'beehive.log',
    'log_max_size': 1048576,
    'enable_camera': False
}

running = True

def signal_handler(sig, frame):
    global running
    running = False

def load_config(config_file):
    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
        return config
    except FileNotFoundError:
        print(f"Config file not found: {config_file}. Using defaults.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError:
        print(f"Error decoding JSON from {config_file}. Using defaults.")
        return DEFAULT_CONFIG.copy()

def initialize_amg8833(bus_number=1):
    if smbus2 is None:
        logging.error("smbus2 library not installed.")
        return None
    try:
        bus = smbus2.SMBus(bus_number)
        amg = AMG88XX(bus)
        logging.info("AMG8833 initialized successfully.")
        return amg, bus
    except Exception as e:
        logging.error(f"Error initializing AMG8833: {e}")
        return None, None

def read_amg8833(amg, bus):
    if amg is None or bus is None:
        return None
    try:
        pixels = amg.pixels
        return np.array(pixels, dtype=np.float32)
    except Exception as e:
        logging.error(f"Error reading AMG8833: {e}")
        return None

def capture_image(picam2):
    if picam2 is None:
        return None
    try:
        image = picam2.capture_array()
        return image
    except Exception as e:
        logging.error(f"Error capturing image: {e}")
        return None

def visualize_data(data, motion_detected, motion_detection_threshold):
    try:
        plt.clf()
        plt.imshow(data, cmap='jet', interpolation='nearest', vmin=np.min(data), vmax=np.max(data))
        plt.colorbar()
        plt.title(f"Timestamp: {datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}, Motion Detected: {motion_detected}, Threshold: {motion_detection_threshold}")
        plt.savefig('beehive_visualization.png')
        plt.close()
    except Exception as e:
        logging.error(f"Error visualizing data: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config(CONFIG_FILE)
    sampling_rate = config['sampling_rate']
    motion_detection_threshold = config['motion_detection_threshold']
    logging_file_path = config['logging_file_path']
    log_max_size = config['log_max_size']
    enable_camera = config['enable_camera']

    log_formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
    log_handler = logging.handlers.RotatingFileHandler(logging_file_path, maxBytes=log_max_size, backupCount=1)
    log_handler.setFormatter(log_formatter)
    logging.getLogger().addHandler(log_handler)
    logging.getLogger().setLevel(logging.INFO)

    amg = None
    bus = None
    picam2 = None

    for attempt in range(3):
        amg, bus = initialize_amg8833()
        if amg is not None:
            break
        logging.warning(f"Attempt {attempt + 1} failed. Retrying in 2 seconds...")
        time.sleep(2)

    if amg is None:
        logging.error("Failed to initialize AMG8833 after 3 attempts. Exiting.")
        sys.exit(1)

    if enable_camera and Picamera2 is not None:
        try:
            picam2 = Picamera2()
            picam2.configure(picam2.create_still_configuration())
            picam2.start()
            logging.info("Camera initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing camera: {e}")
            picam2 = None
    elif enable_camera:
        logging.warning("Camera library not installed. Disabling camera functionality.")

    circular_buffer = np.zeros((300, 8, 8), dtype=np.float32)
    buffer_index = 0
    buffer_lock = threading.Lock()

    def data_acquisition_thread():
        global running, circular_buffer, buffer_index
        while running:
            try:
