except ImportError:
    Picamera2 = None

try:
    from adafruit_amg88xx import AMG88XX
except ImportError:
    AMG88XX = None

CONFIG_FILE = 'config.json'
DEFAULT_CONFIG = {
    'sampling_rate': 5,
    'motion_detection_threshold': 1.0,
    'logging_file_path': 'beehive.log',
    'log_max_size': 1048576,
    'enable_camera': False
}

running = True

def signal_handler(sig, frame):
    global running
    running = False

def load_config(config_file):
    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
        return config
    except FileNotFoundError:
        print(f"Config file not found: {config_file}. Using defaults.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError:
        print(f"Error decoding JSON from {config_file}. Using defaults.")
        return DEFAULT_CONFIG.copy()

def initialize_amg8833(bus_number=1):
    if smbus2 is None:
        logging.error("smbus2 library not installed.")
        return None
    try:
        bus = smbus2.SMBus(bus_number)
        amg = AMG88XX(bus)
        logging.info("AMG8833 initialized successfully.")
        return amg, bus
    except Exception as e:
        logging.error(f"Error initializing AMG8833: {e}")
        return None, None

def read_amg8833(amg, bus):
    if amg is None or bus is None:
        return None
    try:
        pixels = amg.pixels
        return np.array(pixels, dtype=np.float32)
    except Exception as e:
        logging.error(f"Error reading AMG8833: {e}")
        return None

