import io
import logging
import signal
import threading
import time
from typing import Callable, Optional

from libcamera import Transform
from libcamera.controls import Controls
from libcamera.encoders import MJPEGEncoder
from libcamera.transform import Transform

from general import WebSocketHandler

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """Thread-safe buffer for raw camera streaming data."""

    def __init__(self, jpeg_callback: Optional[Callable] = None):
        self.jpeg_callback = jpeg_callback
        self.buffer = io.BytesIO()
        self.lock = threading.Lock()

    def write(self, data: bytes) -> None:
        """Write raw data; detect JPEG boundaries and broadcast complete frames."""
        try:
            with self.lock:
                self.buffer.write(data)
                data_bytes = bytes(data)
                pos = self.buffer.tell()
                end = self.buffer.seek(0, 2)
                if end > 0 and pos < end:
                    while self.buffer.tell() < end:
                        chunk = self.buffer.read(1024)
                        if not chunk:
                            break
                        if b"\xff\xd8" in chunk:
                            self.buffer.seek(self.buffer.tell() - len(chunk) + 2)
                            frame_data = self.buffer.read(self.buffer.tell())
                            if frame_data:
                                self.jpeg_callback(frame_data)
                            else:
                                logger.warning("Incomplete frame data received.")
                        else:
                            break
        except Exception as e:
            logger.error(f"Error in CameraStreamBuffer.write: {e}", exc_info=True)

    def flush(self) -> None:
        """Broadcast any remaining buffered frame data."""
        try:
            with self.lock:
                if self.buffer.tell() > 0:
                    remaining = self.buffer.getvalue()
                    if remaining:
                        self.jpeg_callback(remaining)
                    self.buffer.seek(0)
                    self.buffer.truncate()
        except Exception as e:
            logger.error(f"Error in CameraStreamBuffer.flush: {e}", exc_info=True)


class MotionDetectionBuffer:
    """Thread-safe buffer for motion detection frames."""

    def __init__(self, motion_callback: Optional[Callable] = None):
        self.motion_callback = motion_callback
        self.buffer = io.BytesIO()
        self.lock = threading.Lock()
        self.previous_frame: Optional[bytes] = None
        self.current_frame: Optional[bytes] = None

    def write(self, data: bytes) -> None:
        """Write raw data; detect JPEG boundaries and perform motion detection."""
        try:
            with self.lock:
                self.buffer.write(data)
                data_bytes = bytes(data)
                pos = self.buffer.tell()
                end = self.buffer.seek(0, 2)
                if end > 0 and pos < end:
                    while self.buffer.tell() < end:
                        chunk = self.buffer.read(1024)
                        if not chunk:
                            break
                        if b"\xff\xd8" in chunk:
                            self.buffer.seek(self.buffer.tell() - len(chunk) + 2)
                            frame_data = self.buffer.read(self.buffer.tell())
                            if frame_data:
                                self.previous_frame = self.current_frame
                                self.current_frame = frame_data
                                if (
                                    self.previous_frame is not None
                                    and self.current_frame is not None
                                ):
                                    self.motion_callback(
                                        self.previous_frame, self.current_frame
                                    )
                            else:
                                logger.warning("Incomplete frame data received.")
                        else:
                            break
        except Exception as e:
            logger.error(f"Error in MotionDetectionBuffer.write: {e}", exc_info=True)

    def flush(self) -> None:
        """Perform motion detection on any remaining buffered frame."""
        try:
            with self.lock:
                if self.buffer.tell() > 0:
                    remaining = self.buffer.getvalue()
                    if remaining:
                        if (
                            self.previous_frame is not None
                            and self.current_frame is not None
                        ):
                            self.motion_callback(
                                self.previous_frame, self.current_frame
                            )
                    self.buffer.seek(0)
                    self.buffer.truncate()
        except Exception as e:
            logger.error(f"Error in MotionDetectionBuffer.flush: {e}", exc_info=True)


class Camera:
    """Raspberry Pi V2 camera wrapper using libcamera."""

    def __init__(
        self,
        framerate: int = 10,
        quality: int = 85,
        buffer_count: int = 2,
        transform: Optional[Transform] = None,
    ):
        self.framerate = framerate
        self.quality = quality
        self.buffer_count = buffer_count
        self.transform = transform or Transform()
        self.camera: Optional["libcamera.Camera"] = None
        self.encoder: Optional[MJPEGEncoder] = None
        self.controls: Optional[Controls] = None
        self._running = False
        self._lock = threading.Lock()

    def start(self) -> None:
        """Initialize and start the camera."""
        try:
            self.camera = self._create_camera()
            self.encoder = MJPEGEncoder()
            self.controls = self.camera.controls
            self.controls.FrameRate = self.framerate
            self.controls.Quality = self.quality
            self.controls.Transform = self.transform
            self.encoder.output = self._output_callback
            self.camera.start_recording(self.encoder, self.buffer_count)
            self._running = True
            logger.info("Camera started successfully.")
        except Exception as e:
            logger.error(f"Failed to start camera: {e}", exc_info=True)
            self.stop()
            raise

    def _create_camera(self) -> "libcamera.Camera":
        """Create and configure the libcamera camera instance."""
        from libcamera import Camera

        return Camera(0)

    def _output_callback(self, data: bytes, **kwargs) -> None:
        """Callback for encoder output; dispatches to the stream buffer."""
        if self.stream_buffer:
            self.stream_buffer.write(data)

    @property
    def is_running(self) -> bool:
        return self._running

    def stop(self) -> None:
        """Stop the camera and release resources."""
        self._running = False
        if self.camera:
            try:
                self.camera.stop_recording()
            except Exception as e:
                logger.error(f"Error stopping recording: {e}", exc_info=True)
            try:
                self.camera.close()
            except Exception as e:
                logger.error(f"Error closing camera: {e}", exc_info=True)
            self.camera = None
        logger.info("Camera stopped.")


def decode_jpeg(data: bytes) -> Optional[bytes]:
    """Decode JPEG data; return None on failure."""
    try:
        from PIL import Image

        with Image.open(io.BytesIO(data)) as img:
            return img.tobytes()
    except Exception as e:
        logger.error(f"JPEG decode failed: {e}", exc_info=True)
        return None


def detect_motion(prev: bytes, curr: bytes) -> None:
    """Placeholder motion detection callback."""
    logger.info("Motion detected.")


def main() -> None:
    """Main entry point: initialize camera, WebSocket, and run capture loop."""
    camera = Camera(framerate=10, quality=85, buffer_count=2)
    stream_buffer = CameraStreamBuffer(jpeg_callback=WebSocketHandler.send_frame)
    motion_buffer = MotionDetectionBuffer(motion_callback=detect_motion)
    camera.stream_buffer = stream_buffer
    camera.motion_buffer = motion_buffer

    def signal_handler(signum, frame):
        logger.info(f"Signal {signum} received, shutting down...")
        camera.stop()
        stream_buffer.flush()
        motion_buffer.flush()
        WebSocketHandler.close_all_connections()
        raise SystemExit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        camera.start()
        while camera.is_running:
            time.sleep(0.1)
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}", exc_info=True)
    finally:
        camera.stop()
        stream_buffer.flush()
        motion_buffer.flush()
        WebSocketHandler.close_all_connections()
        logger.info("Program terminated cleanly.")


if __name__ == "__main__":
    main()

