class FaceRecognitionError(Exception):
    pass


class SoundPlaybackError(Exception):
    pass


class DoorController:
    def __init__(self):
        self.camera: Optional[Picamera2] = None
        self.face_model: Optional[cv2.face.EigenFaceRecognizer] = None
        self.welcome_sound: Optional[sound_helpers.Sound] = None
        self.wait_sound: Optional[sound_helpers.Sound] = None
        self.later_sound: Optional[sound_helpers.Sound] = None
        self.is_running = True
        self.face_id: int = -1
        self.recognizer: Optional[cv2.face] = None
        self.logger = logging.getLogger(__name__)

    def initialize(self) -> None:
        try:
            self.camera = Picamera2()
            self.camera.configure(self.camera.create_preview_configuration(
                main={"format": 'XRGB8888', "size": (640, 480)}
            ))
            self.camera.start()
            self.logger.info("Picamera2 initialized and started.")
        except Exception as e:
            self.logger.error(f"Error initializing camera: {e}")
            raise

