import time
import threading
import signal
import sys
import smbus
import RPi.GPIO as GPIO

# --- LCD I2C / GPIO constants ---
I2C_BUS = 1
LCD_ADDR = 0x27
LCD_WIDTH = 16
LCD_CHR = 1
LCD_CMD = 0
LCD_LINE_1 = 0x80
LCD_LINE_2 = 0xC0
LCD_BACKLIGHT = 0x08
ENABLE = 0b00000100

# --- LED GPIO pins (BCM numbering) ---
LED_PINS = {
    0: 17,
    1: 18,
    2: 23,
    3: 27,
    4: 22,
}

# --- Global state ---
_running = True
_led_lock = threading.Lock()


class LCD:
    """Minimal 16x2 HD44780 I2C LCD driver (PCF8574-style expansion)."""

    def __init__(self, bus_num=I2C_BUS, addr=LCD_ADDR):
        self.addr = addr
        self.bus = smbus.SMBus(bus_num)
        self._backlight = LCD_BACKLIGHT
        self._init_lcd()

    def _write_byte(self, byte, mode):
        high = mode | (byte & 0xF0) | self._backlight
        low = mode | ((byte << 4) & 0xF0) | self._backlight
        self.bus.write_byte(self.addr, high | ENABLE)
        time.sleep(0.001)
        self.bus.write_byte(self.addr, high & ~ENABLE)
        self.bus.write_byte(self.addr, low | ENABLE)
        time.sleep(0.001)
        self.bus.write_byte(self.addr, low & ~ENABLE)

    def _init_lcd(self):
        time.sleep(0.05)
        self._write_byte(0x33, LCD_CMD)
        self._write_byte(0x32, LCD_CMD)
        self._write_byte(0x06, LCD_CMD)
        self._write_byte(0x0C, LCD_CMD)
        self._write_byte(0x28, LCD_CMD)
        self._write_byte(0x01, LCD_CMD)
        time.sleep(0.002)

    def clear(self):
        self._write_byte(0x01, LCD_CMD)
        time.sleep(0.002)

    def message(self, text, line):
        self._write_byte(line, LCD_CMD)
        for ch in text.ljust(LCD_WIDTH)[:LCD_WIDTH]:
            self._write_byte(ord(ch), LCD_CHR)

    def backlight(self, on=True):
        self._backlight = LCD_BACKLIGHT if on else 0x00
        self._write_byte(0x08, LCD_CMD)

    def close(self):
        try:
            self.clear()
            self.backlight(False)
        except Exception:
            pass
        try:
            self.bus.close()
        except Exception:
            pass


class LEDIndicator:
    """Controls a single LED via GPIO."""

    def __init__(self, cls_index, pin):
        self.cls_index = cls_index
        self.pin = pin
        GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)

    def on(self):
        GPIO.output(self.pin, GPIO.HIGH)

    def off(self):
        GPIO.output(self.pin, GPIO.LOW)

    def cleanup(self):
        self.off()


class CPUStats:
    """Thread that periodically reads CPU stats and updates the LCD."""

    def __init__(self, lcd):
        self.lcd = lcd
        self.cpu_thread = None
        self.running = True

    def start(self):
        self.cpu_thread = threading.Thread(target=self._update_loop, daemon=True)
        self.cpu_thread.start()

    def stop(self):
        self.running = False
        if self.cpu_thread and self.cpu_thread.is_alive():
            self.cpu_thread.join(timeout=2.0)

    def _update_loop(self):
        while self.running:
            try:
                cpu_usage = self._get_cpu_usage()
                cpu_temp = self._get_cpu_temp()
                self.lcd.message(f"CPU: {cpu_usage:.1f}%", LCD_LINE_1)
                self.lcd.message(f"Temp: {cpu_temp:.1f}C", LCD_LINE_2)
            except Exception as e:
                print(f"Error updating CPU stats: {e}", file=sys.stderr)
            time.sleep(1.0)

    def _get_cpu_usage(self):
        try:
            with open('/proc/stat', 'r') as f:
                line = f.readline()
            parts = line.split()
            idle = int(parts[4])
            total = sum(int(parts[i]) for i in range(1, 19))
            return 100.0 * (total - idle) / total if total else 0.0
        except Exception:
            return 0.0

    def _get_cpu_temp(self):
        try:
            with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
                return float(f.read().strip()) / 1000.0
        except Exception:
            return 0.0


class LEDController:
    """Manages LED indicators for class indices."""

    def __init__(self):
        self.leds = {}
        for idx, pin in LED_PINS.items():
            self.leds[idx] = LEDIndicator(idx, pin)

    def activate(self, cls_index):
        with _led_lock:
            if cls_index in self.leds:
                self.leds[cls_index].on()
                time.sleep(1.0)
                self.leds[cls_index].off()

    def cleanup(self):
        for led in self.leds.values():
            led.cleanup()


def signal_handler(sig, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)

    lcd = None
    led_controller = None
    cpu_stats = None

    try:
        lcd = LCD()
        lcd.clear()
        lcd.message("Initializing...", LCD_LINE_1)
        lcd.message("Please wait...", LCD_LINE_2)
        time.sleep(2.0)
        lcd.clear()

        led_controller = LEDController()
        cpu_stats = CPUStats(lcd)
        cpu_stats.start()

        while _running:
            try:
                cls_input = input("Enter class index (0-4, or Ctrl+C to exit): ").strip()
                cls_index = int(cls_input)
                if 0 <= cls_index <= 4:
                    led_controller.activate(cls_index)
                else:
                    print("Invalid class index. Please enter a number between 0 and 4.")
            except ValueError:
                print("Invalid input. Please enter an integer.")
            except EOFError:
                break
            except Exception as e:
                print(f"An unexpected error occurred: {e}", file=sys.stderr)
                break

    except Exception as e:
        print(f"Initialization error: {e}", file=sys.stderr)
    finally:
        _running = False
        if cpu_stats:
            cpu_stats.stop()
        if lcd:
            lcd.close()
        if led_controller:
            led_controller.cleanup()
        GPIO.cleanup()
        print("Program terminated.")


if __name__ == "__main__":
    main()

