import smbus
import time
import signal
import sys
from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306
from luma.core.render import canvas

# TSL2561 constants
TSL2561_ADDR = 0x29
TSL2561_COMMAND_BIT = 0xA0
TSL2561_REGISTER_ENABLE = 0x00
TSL2561_REGISTER_CONTROL = 0x01
TSL2561_REGISTER_CHAN0_LOW = 0x14
TSL2561_REGISTER_CHAN1_LOW = 0x16
TSL2561_REGISTER_PART_ID = 0x12
TSL2561_PART_ID = 0x50

# Integration time 101 ms, gain 1x
INTEGRATION_TIME_101MS = 0x00
GAIN_1X = 0x00

I2C_BUS = 1

running = True


def signal_handler(sig, frame):
    global running
    running = False


def init_i2c():
    try:
        return smbus.SMBus(I2C_BUS)
    except FileNotFoundError:
        print(f"Error: I2C bus {I2C_BUS} not found. Enable I2C with 'sudo raspi-config'.")
        return None
    except PermissionError:
        print(f"Error: Permission denied on I2C bus {I2C_BUS}. Run as root or add user to 'i2c' group.")
        return None
    except Exception as e:
        print(f"Error initializing I2C bus {I2C_BUS}: {e}")
        return None


def init_oled():
    try:
        serial = i2c(port=I2C_BUS, address=0x3C)
        return ssd1306(serial)
    except Exception as e:
        print(f"Error initializing OLED display: {e}")
        return None


def init_tsl2561(bus):
    try:
        part_id = bus.read_byte_data(TSL2561_ADDR, TSL2561_REGISTER_PART_ID)
        if part_id != TSL2561_PART_ID:
            print(f"Warning: Unexpected part ID 0x{part_id:02X} at 0x{TSL2561_ADDR:02X}; expected 0x{TSL2561_PART_ID:02X}.")
        else:
            print(f"TSL2561 detected (part ID 0x{part_id:02X}).")

        bus.write_byte_data(TSL2561_ADDR, TSL2561_REGISTER_ENABLE, 0x00)
        bus.write_byte_data(TSL2561_ADDR, TSL2561_REGISTER_CONTROL, INTEGRATION_TIME_101MS | GAIN_1X)
        time.sleep(0.01)
        return True
    except OSError as e:
        print(f"Error: TSL2561 not responding at 0x{TSL2561_ADDR:02X} on bus {I2C_BUS}: {e}")
        return False
    except Exception as e:
        print(f"Error initializing TSL2561: {e}")
        return False


def read_lux(bus):
    try:
        data0 = bus.read_i2c_block_data(TSL2561_ADDR, TSL2561_REGISTER_CHAN0_LOW, 2)
        data1 = bus.read_i2c_block_data(TSL2561_ADDR, TSL2561_REGISTER_CHAN1_LOW, 2)
        ch0 = (data0[1] << 8) | data0[0]
