import os
import time
import signal
import logging
from PIL import Image

try:
    import spidev
    from lib_st7789 import ST7789
except ImportError as e:
    raise ImportError(f"Required libraries not installed: {e}")

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class GifPlayer:
    """
    A class to play GIF animations on an ST7789 display connected to a Raspberry Pi.
    """

    def __init__(self, folder, display_width=240, display_height=240, spi_bus=0, spi_device=0, speed=4000000):
        self.folder = folder
        self.display_width = display_width
        self.display_height = display_height
        self.spi = None
        self.display = None
        self.running = True

        try:
            self.spi = spidev.SpiDev()
            self.spi.open(spi_bus, spi_device)
            self.spi.max_speed_hz = speed
            self.spi.mode = 0
        except Exception as e:
            logging.error(f"Error initializing SPI: {e}")
            raise

        try:
            self.display = ST7789(self.spi, self.display_width, self.display_height)
            self.display.begin()
            logging.info("ST7789 display initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing ST7789 display: {e}")
            self.cleanup()
            raise

        self.gif_files = self._get_gif_files(self.folder)
        if not self.gif_files:
            logging.error(f"No GIF files found in folder: {self.folder}")
            self.cleanup()
            raise FileNotFoundError(f"No GIF files found in folder: {self.folder}")

    def _get_gif_files(self, folder):
        try:
            return [f for f in os.listdir(folder) if f.lower().endswith(".gif")]
        except FileNotFoundError:
            logging.error(f"Folder not found: {folder}")
            return []
        except Exception as e:
            logging.error(f"Error listing files in folder {folder}: {e}")
            return []

    def _convert_to_rgb(self, image):
        try:
            return image.convert('RGB')
        except Exception as e:
            logging.error(f"Error converting image to RGB: {e}")
            return None

    def _display_frame(self, image):
        try:
            self.display.display_image(image)
        except Exception as e:
            logging.error(f"Error displaying frame: {e}")

    def play(self, gif_file):
        try:
            image = Image.open(os.path.join(self.folder, gif_file))
            if image.mode != 'RGB':
                image = self._convert_to_rgb(image)
                if image is None:
                    return

            duration = 100
            try:
                duration = image.info.get("duration", 100)
            except Exception:
                pass

            logging.info(f"Playing GIF: {gif_file} (duration: {duration} ms)")

            while self.running:
                self._display_frame(image)
                time.sleep(duration / 1000.0)

        except FileNotFoundError:
            logging.error(f"File not found: {os.path.join(self.folder, gif_file)}")
        except Exception as e:
            logging.error(f"Error playing GIF: {e}")

    def run(self):
        logging.info("Starting GIF player. Press Ctrl+C to exit.")
        try:
            while self.running:
                for gif_file in self.gif_files:
                    if not self.running:
                        break
                    self.play(gif_file)
        except KeyboardInterrupt:
            logging.info("Exiting GIF player.")
        finally:
            self.cleanup()

    def stop(self):
        self.running = False

    def cleanup(self):
        if self.spi:
            try:
                self.spi.close()
            except Exception:
                pass
            self.spi = None
        if self.display:
            try:
                self.display.clear()
            except Exception:
                pass
            self.display = None


def main():
    gif_folder = "/path/to/your/gifs"
    player = None

    def signal_handler(sig, frame):
        logging.info("Signal received, stopping...")
        if player:
            player.stop()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        player = GifPlayer(gif_folder)
        player.run()
    except Exception as e:
        logging.error(f"Failed to start GIF player: {e}")
    finally:
        if player:
            player.cleanup()


if __name__ == "__main__":
    main()

