import os
import sys
import signal
import logging
import time
from PIL import Image, ImageOps, ImageChops, ImageSequence
import smbus2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SSD1306:
    def __init__(self, bus_num=1, addr=0x3C):
        self.addr = addr
        self.width = 128
        self.height = 64
        self.bus = None
        try:
            self.bus = smbus2.SMBus(bus_num)
            self._init_display()
            logging.info(f"SSD1306 initialized on bus {bus_num}, address 0x{addr:02X}")
        except Exception as e:
            logging.error(f"Failed to initialize SSD1306: {e}")
            raise

    def _init_display(self):
        cmds = [
            0xAE, 0xD5, 0x80, 0xA8, 0x3F, 0xD3, 0x00, 0x40, 0x8D, 0x14,
            0xA1, 0xC8, 0xDA, 0x12, 0x81, 0xCF, 0xD9, 0xF1, 0xDB, 0x40,
            0xA4, 0xA6, 0xAF
        ]
        for cmd in cmds:
            self._write_cmd(cmd)

    def _write_cmd(self, cmd):
        self.bus.write_byte_data(self.addr, 0x00, cmd)

    def _write_data(self, data):
        self.bus.write_i2c_block_data(self.addr, 0x40, [data])

    def display(self, image):
        if image.size != (self.width, self.height):
            image = image.resize((self.width, self.height), Image.LANCZOS)
        pixels = image.convert('1')
        buffer = bytearray(self.width * self.height // 8)
        for x in range(self.width):
            for y in range(self.height):
                if pixels.getpixel((x, y)):
                    buffer[x + y * self.width // 8] |= 1 << (x % 8)
        self._write_cmd(0x21)
        self._write_cmd(0x00)
        self._write_cmd(self.width - 1)
        self._write_cmd(0x00)
        self._write_cmd(self.height // 8 - 1)
        self._write_cmd(0x00)
        for byte in buffer:
            self._write_data(byte)

    def close(self):
        if self.bus:
            try:
                self._write_cmd(0xAE)
                self.bus.close()
                logging.info("SSD1306 display closed.")
            except Exception as e:
                logging.error(f"Error closing SSD1306: {e}")

def load_gif(path):
    try:
        img = Image.open(path)
        if img.format != 'GIF':
            logging.warning(f"File {path} is not a GIF.")
            return None
        return img
    except FileNotFoundError:
        logging.error(f"File not found: {path}")
        return None
    except Exception as e:
        logging.error(f"Error loading GIF {path}: {e}")
        return None

def process_gif(gif_image, display):
    try:
        if not hasattr(gif_image, 'is_animated'):
            logging.warning("GIF has no animation support.")
            return
        if not gif_image.is_animated:
            logging.warning("GIF is not animated.")
            return
        loop_count = gif_image.info.get('loop', 0)
        if loop_count == 0:
            loop_count = -1
        logging.info(f"GIF loop count: {loop_count}")
        frame_count = 0
        while True:
            try:
                frame = gif_image.next()
                frame_count += 1
                logging.info(f"Frame {frame_count} loaded.")
                duration = frame.info.get('duration', 100)
                logging.info(f"  Duration: {duration} ms")
                display.display(frame)
                time.sleep(duration / 1000.0)
            except EOFError:
                break
            except Exception as e:
                logging.error(f"Error processing frame {frame_count}: {e}")
                break
        logging.info(f"Processed {frame_count} frames.")
    except Exception as e:
        logging.error(f"Error processing GIF: {e}")

def main():
    gif_folder = "gifs"
    if not os.path.isdir(gif_folder):
        logging.error(f"Folder not found: {gif_folder}")
        sys.exit(1)
    gif_files = [f for f in os.listdir(gif_folder) if f.lower().endswith('.gif')]
    if not gif_files:
        logging.warning(f"No GIF files found in {gif_folder}")
        sys.exit(0)
    logging.info(f"Found {len(gif_files)} GIF files.")
    display = None
    def signal_handler(sig, frame):
        logging.info("SIGINT received. Exiting...")
        if display:
            display.close()
        sys.exit(0)
    signal.signal(signal.SIGINT, signal_handler)
    try:
        display = SSD1306(bus_num=1, addr=0x3C)
        for gif_file in gif_files:
            path = os.path.join(gif_folder, gif_file)
            gif_image = load_gif(path)
            if gif_image:
                process_gif(gif_image, display)
            else:
                logging.warning(f"Skipping {gif_file}.")
    except Exception as e:
        logging.error(f"Fatal error: {e}")
    finally:
        if display:
            display.close()

if __name__ == "__main__":
    main()

