    global _left_motor_1, _left_motor_2, _right_motor_1, _right_motor_2
    try:
        _left_motor_1 = PWMOutputDevice(LEFT_MOTOR_PIN_1, frequency=PWM_FREQUENCY, initial_value=0)
        _left_motor_2 = PWMOutputDevice(LEFT_MOTOR_PIN_2, frequency=PWM_FREQUENCY, initial_value=0)
        _right_motor_1 = PWMOutputDevice(RIGHT_MOTOR_PIN_1, frequency=PWM_FREQUENCY, initial_value=0)
        _right_motor_2 = PWMOutputDevice(RIGHT_MOTOR_PIN_2, frequency=PWM_FREQUENCY, initial_value=0)
    except Exception as e:
        print(f"Failed to initialize GPIO pins: {e}")
        _cleanup()
        return

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initial robot position and orientation
    car_front_x, car_front_y = 180, -200
    car_back_x, car_back_y = 200, -15
    car_heading = _calculate_angle(car_front_x, car_front_y, car_back_x, car_back_y)

    # Ball and goal positions
    ball_x, ball_y = 180, -200
    goal_x, goal_y = 0, 200

    # Extension to define an image point beyond the ball on the ball-goal line
    extension = 50

    max_iterations = 1000
    iteration = 0

    try:
        while _running and iteration < max_iterations:
            iteration += 1

            # Calculate intercept point
            intercept_point = _calculate_intercept_point(ball_x, ball_y, goal_x, goal_y, extension)
            if intercept_point:
                intercept_x, intercept_y = intercept_point
            else:
                print("Failed to calculate intercept point.")
                break

            # Calculate car front point based on intercept point and car back point
            car_front_x, car_front_y = _calculate_car_front_point_from_intercept(intercept_x, intercept_y, car_back_x, car_back_y)
            if car_front_x is None or car_front_y is None:
                print("Failed to calculate car front point.")
                break

            # Calculate car back point based on car front point and car back point
            car_back_x, car_back_y = _calculate_car_back_point_from_front(car_front_x, car_front_y, car_back_x, car_back_y)
            if car_back_x is None or car_back_y is None:
                print("Failed to calculate car back point.")
                break

            # Calculate heading to intercept point
            heading_to_intercept = _calculate_heading_to_target(car_heading, _calculate_angle(car_front_x, car_front_y, intercept_x, intercept_y))

            # Control loop to align with intercept point
            while _running and abs(heading_to_intercept) > 10:
                if heading_to_intercept < 0:
                    _turn_right(50)
                else:
                    _turn_left(50)
                time.sleep(0.1)
                _stop_motors()
                heading_to_intercept = _calculate_heading_to_target(car_heading, _calculate_angle(car_front_x, car_front_y, intercept_x, intercept_y))

            # Move forward to intercept point
            _move_forward_until_target(100, 10)

            # Turn to face the ball
            _turn_to_target(50)

            # Intercept the ball
            _intercept_ball(100)

            # Turn to face the goal
            _turn_to_target(50)

            # Reach the goal
            _reach_goal(100)

            # Print telemetry data
            print(f"Iteration {iteration}: Ball ({ball_x},{ball_y}), Car Front ({car_front_x},{car_front_y}), Car Back ({car_back_x},{car_back_y}), Goal ({goal_x},{goal_y})")

    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        _stop_motors()
        _cleanup()


if __name__ == "__main__":
    main()

