import signal
import sys
import time

try:
    import smbus2
except ImportError:
    sys.stderr.write("This program requires the 'smbus2' package. Install with: pip install smbus2\n")
    sys.exit(1)

I2C_BUS = 1
I2C_ADDRESS = 0x20
NUM_SENSORS = 8
POLL_INTERVAL_S = 0.1
RETRY_DELAY_S = 1.0

running = True


def handle_signal(signum, frame):
    global running
    running = False


signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)

bus = None
try:
    bus = smbus2.SMBus(I2C_BUS)
except OSError as e:
    sys.stderr.write(f"Error: cannot open I2C bus {I2C_BUS}: {e}\n")
    sys.exit(1)

try:
    while running:
        try:
            raw = bus.read_byte(I2C_ADDRESS)
        except OSError as e:
            sys.stderr.write(f"I2C read error (address 0x{I2C_ADDRESS:02X}): {e}\n")
            time.sleep(RETRY_DELAY_S)
            continue

        for sensor_num in range(NUM_SENSORS):
            bit = 1 << sensor_num
            if raw & bit:
                continue
            print(f"Obstacle detected by sensor {sensor_num}")

        time.sleep(POLL_INTERVAL_S)
finally:
    if bus is not None:
        try:
            bus.close()
        except Exception:
            pass

