import time
import signal
import sys

try:
    import adafruit_dht
    from board import D4
except ImportError:
    print("Error: Required libraries not installed. Install with:")
    print("  pip install adafruit-circuitpython-dht")
    print("  sudo apt-get install libgpiod2")
    sys.exit(1)

# DHT11 requires at least 1 second between reads; we use 2 s for safety.
READ_INTERVAL_S = 2.0
MAX_RETRIES = 5

# Graceful-shutdown flag set by SIGINT / SIGTERM.
_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensor = None
    try:
        try:
            sensor = adafruit_dht.DHT11(D4, use_pulseio=False)
        except Exception as exc:
            print(f"Error: Failed to initialize DHT11 on GPIO4: {exc}")
            sys.exit(1)

        for attempt in range(1, MAX_RETRIES + 1):
            if not _running:
                print("\nInterrupted by user. Exiting.")
                sys.exit(130)

            try:
                temperature = sensor.temperature
                if temperature is None:
                    raise RuntimeError("Sensor returned None")
                print(f"Temperature: {temperature:.1f} C")
                sys.exit(0)
            except RuntimeError as exc:
                # Common DHT11 transient errors: checksum, timeout, or read failure.
                print(f"Attempt {attempt}/{MAX_RETRIES}: read failed ({exc}).")
            except Exception as exc:
                print(f"Attempt {attempt}/{MAX_RETRIES}: unexpected error ({exc}).")

            if attempt < MAX_RETRIES and _running:
                time.sleep(READ_INTERVAL_S)

        print("Error: Could not read temperature from DHT11 after "
              f"{MAX_RETRIES} attempts. Check wiring (GPIO4, BCM pin 7, "
              f"physical pin 7) and ensure the sensor is properly powered.")
        sys.exit(1)

    finally:
        if sensor is not None:
            try:
                sensor.exit()
            except Exception:
                pass


if __name__ == "__main__":
    main()

