import json
import random
import time
import signal
import sys
import threading

import paho.mqtt.client as mqtt

BROKER = "test.mosquitto.org"
PORT = 1883
KEEPALIVE = 60
TOPIC = "classroom/temperature"
MAX_RECONNECT_ATTEMPTS = 3
RETRY_DELAY = 2
READINGS = 5

stop_event = threading.Event()


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        print("Connected to MQTT broker")
    else:
        print(f"Connection failed with reason code: {reason_code}")


def on_disconnect(client, userdata, flags, reason_code, properties):
    print(f"Disconnected from MQTT broker (reason code: {reason_code})")


def on_publish(client, userdata, mid, reason_code, properties):
    pass


def generate_temperature_reading():
    return round(random.uniform(19.00, 26.00), 2)


def publish_readings(client, topic, readings):
    for i in range(readings):
        if stop_event.is_set():
            print("Publishing stopped by event")
            break
        payload = json.dumps({"temperature": generate_temperature_reading(), "index": i})
        info = client.publish(topic, payload, qos=0)
        info.wait_for_publish(timeout=5)
        if info.rc != mqtt.MQTT_ERR_SUCCESS:
            print(f"Failed to publish message {i}: {info.rc}")
        else:
            print(f"Published message {i}: {payload}")


def main():
    client = mqtt.Client(
        mqtt.CallbackAPIVersion.VERSION2,
        client_id="rpi-temp-publisher",
    )
    client.on_connect = on_connect
    client.on_disconnect = on_disconnect
    client.on_publish = on_publish

    connect_event = threading.Event()

    def _connect_attempt():
        for attempt in range(1, MAX_RECONNECT_ATTEMPTS + 1):
            if stop_event.is_set():
                return
            try:
                print(f"Connecting to broker (attempt {attempt}/{MAX_RECONNECT_ATTEMPTS})...")
                client.connect(BROKER, PORT, KEEPALIVE)
                client.loop_start()
                if not connect_event.wait(timeout=10):
                    print(f"Timeout waiting for CONNACK on attempt {attempt}")
                    client.loop_stop()
                    client.disconnect()
                    if attempt < MAX_RECONNECT_ATTEMPTS:
                        time.sleep(RETRY_DELAY)
                        continue
                    print("Failed to connect to broker after all attempts.")
                    return
                break
            except Exception as e:
                print(f"Connection error on attempt {attempt}: {e}")
                if attempt < MAX_RECONNECT_ATTEMPTS:
                    time.sleep(RETRY_DELAY)
        else:
            print("Failed to connect to broker after all attempts.")
            return

    def _signal_handler(signum, frame):
        print(f"\nReceived signal {signum}, stopping...")
        stop_event.set()

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _connect_attempt()
        publish_readings(client, TOPIC, READINGS)
        print(f"Published {READINGS} messages successfully.")
        sys.exit(0)
    except Exception as e:
        print(f"Error during publish: {e}")
        sys.exit(1)
    finally:
        try:
            client.loop_stop()
            client.disconnect()
        except Exception:
            pass


if __name__ == "__main__":
    main()

