import signal
import sys
import time

import serial

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 115200
TIMEOUT = 1          # seconds
POLL_INTERVAL = 0.5  # seconds between reads

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_temperature(ser):
    """Read one line from the RS485 sensor and return the first float, or None on error."""
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None
    if not raw:
        return None  # timeout, no data
    try:
        text = raw.decode('ascii', errors='replace').strip()
    except Exception as exc:
        print(f"Decode error: {exc}", file=sys.stderr)
        return None
    if not text:
        return None
    try:
        return float(text.split(None, 1)[0])
    except (ValueError, IndexError):
        print(f"Malformed data (not a float): '{text}'", file=sys.stderr)
        return None

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Failed to open {SERIAL_PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            temp = read_temperature(ser)
            if temp is not None:
                print(f"Temperature: {temp:.1f} C")
            time.sleep(POLL_INTERVAL)
    finally:
        try:
            ser.close()
        except Exception:
            pass

if __name__ == '__main__':
    main()

