import os
import sys
import time
import signal
import logging
from datetime import datetime

try:
    import adafruit_dht
    import board
except ImportError:
    print("Missing dependencies. Install with:")
    print("  pip install adafruit-circuitpython-dht")
    print("  sudo apt-get install libgpiod2")
    sys.exit(1)

DATA_DIR = "/home/pi/data"
CSV_FILE = os.path.join(DATA_DIR, "sensor_data.csv")
ERROR_LOG = os.path.join(DATA_DIR, "error.log")
DHT_PIN = board.D4

running = True


def signal_handler(signum, frame):
    global running
    running = False


def setup_logging():
    logging.basicConfig(
        filename=ERROR_LOG,
        level=logging.ERROR,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )


def ensure_data_dir():
    try:
        os.makedirs(DATA_DIR, exist_ok=True)
    except OSError as e:
        print(f"Failed to create data directory {DATA_DIR}: {e}", file=sys.stderr)
        sys.exit(1)


def log_csv_row(timestamp, temperature):
    try:
        with open(CSV_FILE, "a", encoding="utf-8") as f:
            f.write(f"{timestamp},{temperature:.1f}\n")
    except OSError as e:
        logging.error(f"Failed to write CSV row: {e}")


def log_error(message):
    logging.error(message)


def main():
    global running

    setup_logging()
    ensure_data_dir()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    sensor = None
    try:
        sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as e:
        log_error(f"Failed to initialize DHT22 on GPIO4: {e}")
        sys.exit(1)

    try:
        while running:
            try:
                temperature = sensor.temperature
                if temperature is None:
                    raise RuntimeError("Sensor returned None")
                timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                log_csv_row(timestamp, temperature)
                print(f"{timestamp} - Temperature: {temperature:.1f} °C")
            except RuntimeError as e:
                timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                log_error(f"{timestamp} - RuntimeError: {e}")
            except Exception as e:
                timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                log_error(f"{timestamp} - Unexpected error: {e}")

            for _ in range(60):
                if not running:
                    break
                time.sleep(1)
    finally:
        if sensor is not None:
            try:
                sensor.exit()
            except Exception:
                pass
        print("Program terminated gracefully.")


if __name__ == "__main__":
    main()

