import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591


def main():
    # Initialize the I2C bus on board.SCL (GPIO3) and board.SDA (GPIO2).
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return

    # Verify the TCA9548A multiplexer is present on the bus.
    try:
        i2c_multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus)
    except Exception as e:
        print(f"Error: TCA9548A multiplexer not found on the I2C bus: {e}")
        return

    # Verify the BME280 sensor is present on the multiplexer.
    try:
        bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(i2c_multiplexer[0])
    except Exception as e:
        print(f"Error: BME280 sensor not found on the multiplexer: {e}")
        return

    # Verify the TSL2591 light sensor is present on the multiplexer.
    try:
        tsl2591_sensor = adafruit_tsl2591.TSL2591(i2c_multiplexer[1])
    except Exception as e:
        print(f"Error: TSL2591 sensor not found on the multiplexer: {e}")
        return

    print("Sensors initialized successfully. Reading data every 2 seconds...")

    try:
        while True:
            try:
                temperature = bme280_sensor.temperature
                humidity = bme280_sensor.humidity
                light_intensity = tsl2591_sensor.lux

                print(
                    f"Temperature: {temperature:.1f} C, "
                    f"Humidity: {humidity:.1f} %, "
                    f"Light Intensity: {light_intensity:.1f} lux"
                )

            except Exception as e:
                # Handle transient I2C read errors without crashing the loop.
                print(f"Error reading sensor data: {e}")

            time.sleep(2)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")


if __name__ == "__main__":
    main()

