import argparse
import json
import logging
import socket
import sys
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.", file=sys.stderr)
    sys.exit(1)


class HydroponicsController:
    """
    A hydroponics controller that manages a water pump and a simulated DHT11
    temperature sensor via a TCP socket interface.
    """

    def __init__(self, relay_pin, dht_pin, listening_port, allowed_ip, log_file):
        self.relay_pin = relay_pin
        self.dht_pin = dht_pin
        self.listening_port = listening_port
        self.allowed_ip = allowed_ip
        self.log_file = log_file
        self.pump_state = False
        self._running = True

        self._setup_logging()
        self._setup_gpio()
        self._setup_socket()

    def _setup_logging(self):
        logging.basicConfig(
            filename=self.log_file,
            level=logging.INFO,
            format='%(asctime)s - %(levelname)s - %(message)s'
        )
        logging.info("Hydroponics controller started.")

    def _setup_gpio(self):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.relay_pin, GPIO.OUT, initial=GPIO.LOW)
            logging.info(f"GPIO setup complete: relay on BCM pin {self.relay_pin}.")
        except Exception as e:
            logging.error(f"GPIO setup failed: {e}")
            raise

    def _setup_socket(self):
        try:
            self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            self.server_socket.bind(('', self.listening_port))
            self.server_socket.listen(1)
            self.server_socket.settimeout(1.0)
            logging.info(f"Listening on port {self.listening_port}.")
        except socket.error as e:
            logging.error(f"Socket setup failed: {e}")
            raise

    def _handle_client(self, client_socket):
        try:
            client_address = client_socket.getpeername()
            if client_address[0] != self.allowed_ip:
                logging.warning(f"Unauthorized connection from {client_address[0]}.")
                client_socket.close()
                return

            data = client_socket.recv(1024).decode('utf-8').strip()
            if not data:
                logging.warning("Empty data received.")
                client_socket.close()
                return

            try:
                command = json.loads(data)
            except json.JSONDecodeError:
                logging.error(f"Invalid JSON from {client_address[0]}: {data}")
                client_socket.sendall(b'{"error": "Invalid JSON"}')
                client_socket.close()
                return

            if not isinstance(command, dict):
                logging.error(f"Invalid command format from {client_address[0]}: {data}")
                client_socket.sendall(b'{"error": "Invalid command format"}')
                client_socket.close()
                return

            command_type = command.get('command')
            if not command_type:
                logging.error(f"Missing 'command' key from {client_address[0]}: {data}")
                client_socket.sendall(b'{"error": "Missing \'command\' key"}')
                client_socket.close()
                return

            if command_type == 'pump_on':
                self.pump_on()
            elif command_type == 'pump_off':
                self.pump_off()
            elif command_type == 'get_status':
                self.get_status(client_socket)
            else:
                logging.warning(f"Unknown command '{command_type}' from {client_address[0]}.")
                client_socket.sendall(b'{"error": "Unknown command"}')

            client_socket.close()

        except socket.timeout:
            pass
        except Exception as e:
            logging.error(f"Error handling client: {e}")
            try:
                client_socket.close()
            except Exception:
                pass

    def pump_on(self):
        try:
            GPIO.output(self.relay_pin, GPIO.HIGH)
            self.pump_state = True
            logging.info("Pump turned ON.")
        except Exception as e:
            logging.error(f"Failed to turn pump ON: {e}")

    def pump_off(self):
        try:
            GPIO.output(self.relay_pin, GPIO.LOW)
            self.pump_state = False
            logging.info("Pump turned OFF.")
        except Exception as e:
            logging.error(f"Failed to turn pump OFF: {e}")

    def get_status(self, client_socket):
        try:
            temperature = 25.0
            status = {
                "pump_state": "on" if self.pump_state else "off",
                "temperature": temperature
            }
            response = json.dumps(status)
            client_socket.sendall(response.encode('utf-8'))
            logging.info(f"Sent status to {client_socket.getpeername()[0]}: {response}")
        except Exception as e:
            logging.error(f"Failed to get status: {e}")

    def run(self):
        try:
            while self._running:
                try:
                    client_socket, address = self.server_socket.accept()
                    logging.info(f"Accepted connection from {address[0]}.")
                    self._handle_client(client_socket)
                except socket.timeout:
                    continue
        except KeyboardInterrupt:
            logging.info("KeyboardInterrupt received. Shutting down...")
        finally:
            self.cleanup()

    def cleanup(self):
        self._running = False
        try:
            GPIO.output(self.relay_pin, GPIO.LOW)
        except Exception:
            pass
        GPIO.cleanup()
        try:
            self.server_socket.close()
        except Exception:
            pass
        logging.info("Cleanup complete. Exiting.")


def main():
    parser = argparse.ArgumentParser(description="Hydroponics Controller")
    parser.add_argument("--relay_pin", type=int, default=17, help="BCM GPIO pin for relay")
    parser.add_argument("--dht_pin", type=int, default=4, help="BCM GPIO pin for DHT11")
    parser.add_argument("--listening_port", type=int, default=12345, help="Listening port")
    parser.add_argument("--allowed_ip", type=str, default="192.168.1.100", help="Allowed IP address")
    parser.add_argument("--log_file", type=str, default="hydroponics.log", help="Log file path")
    args = parser.parse_args()

    try:
        controller = HydroponicsController(
            args.relay_pin, args.dht_pin, args.listening_port,
            args.allowed_ip, args.log_file
        )
        controller.run()
    except Exception as e:
        logging.error(f"Fatal error: {e}")
        sys.exit(1)


if __name__ == "__main__":
    main()

