#!/usr/bin/env python3
"""
CPU Temperature Monitor for Raspberry Pi 4 Model B

Repeatedly reads the on-board CPU temperature sensor and prints the value
every five seconds.  Handles missing thermal files and unexpected errors
without crashing so that the loop can continue.
"""

import time
import sys


def get_cpu_temperature():
    """
    Read the CPU temperature from the Raspberry Pi thermal zone.

    Lazily imports the ``CPUTemperature`` class so that a missing thermal
    file (e.g., on a non-Pi or headless system) raises FileNotFoundError
    during the read rather than at import time.
    """
    from adafruit_blinka.microcontroller.bcm2708 import CPUTemperature

    try:
        cpu = CPUTemperature()
        return cpu.temperature
    except FileNotFoundError:
        raise
    except Exception as exc:
        raise


def main():
    """Main loop: read and print CPU temperature every five seconds."""
    try:
        while True:
            try:
                temp = get_cpu_temperature()
                print(f"CPU Temperature: {temp:.2f} °C")
            except FileNotFoundError:
                print("Error: CPU temperature sensor not available.")
            except Exception as exc:
                print(f"Error reading CPU temperature: {exc}")
            time.sleep(5)
    except KeyboardInterrupt:
        print("\nProgram terminated")
        sys.exit(0)


if __name__ == "__main__":
    main()

