import signal
import sys
import time
import threading
import logging
import numpy as np
import matplotlib.pyplot as plt
import matplotlib.animation as animation

try:
    import smbus2
except ImportError:
    smbus2 = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class ThermalCamera:
    """Thermal camera reader that communicates with the sensor over UART."""

    def __init__(self, bus_number=1, address=0x04, timeout=1.0):
        self.bus_number = bus_number
        self.address = address
        self.timeout = timeout
        self.bus = None
        self.running = False
        self.frame_queue = threading.Queue(maxsize=10)
        self.stop_event = threading.Event()
        self.frame_count = 0
        self._lock = threading.Lock()

    def open(self):
        if smbus2 is None:
            logger.error("smbus2 library not installed; cannot open UART port.")
            return False
        try:
            self.bus = smbus2.SMBus(self.bus_number)
            logger.info(f"Opened UART bus {self.bus_number} for thermal camera at 0x{self.address:02X}.")
            return True
        except Exception as e:
            logger.error(f"Failed to open UART bus {self.bus_number}: {e}")
            self.bus = None
            return False

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
                logger.info("Closed UART bus.")
            except Exception as e:
                logger.error(f"Error closing UART bus: {e}")
            finally:
                self.bus = None

    def read_frame(self):
        if self.bus is None:
            logger.error("UART bus is not open.")
            return None
        try:
            data = self.bus.read_i2c_block_data(self.address, 0x00, 2048)
            if len(data) != 2048:
                logger.warning(f"Incomplete read: expected 2048 bytes, got {len(data)}.")
                return None
            return data
        except Exception as e:
            logger.error(f"Error reading from thermal camera: {e}")
            return None

    def process_frame(self, raw_data):
        try:
            frame = []
            for i in range(0, len(raw_data), 32):
                row_data = raw_data[i:i + 32]
                row = []
                for j in range(0, 32, 4):
                    val = (row_data[j] << 24) | (row_data[j + 1] << 16) | (row_data[j + 2] << 8) | row_data[j + 3]
                    row.append(val & 0xFFF)
                frame.append(row)
            return np.array(frame, dtype=np.int16)
        except Exception as e:
            logger.error(f"Error processing frame: {e}")
            return None

    def run(self):
        self.running = True
        while self.running and not self.stop_event.is_set():
            raw_data = self.read_frame()
            if raw_data is not None:
                frame = self.process_frame(raw_data)
                if frame is not None:
                    with self._lock:
                        self.frame_count += 1
                    self.frame_queue.put(frame)
            time.sleep(0.01)

    def start(self):
        self.reader_thread = threading.Thread(target=self.run, daemon=True)
        self.reader_thread.start()

    def stop(self):
        self.running = False
        self.stop_event.set()
        if self.reader_thread and self.reader_thread.is_alive():
            self.reader_thread.join(timeout=2.0)

    def get_latest_frame(self):
        with self._lock:
            return self.frame_queue.get() if not self.frame_queue.empty() else None


def update_heatmap(frame, thermal_camera, line):
    new_frame = thermal_camera.get_latest_frame()
    if new_frame is not None:
        frame.set_array(new_frame)
    return line


def main():
    thermal_camera = ThermalCamera(bus_number=1, address=0x04, timeout=1.0)

    if not thermal_camera.open():
        sys.exit(1)

    thermal_camera.start()

    try:
        fig, ax = plt.subplots(figsize=(8, 6))
        im = ax.imshow(np.zeros((24, 32)), cmap='inferno', interpolation='nearest', vmin=0, vmax=1000)
        cbar = fig.colorbar(im, ax=ax, label='Temperature (°C)')
        cbar.set_ticks(np.arange(0, 1001, 200))
        ax.set_title('Thermal Camera Feed')
        ax.set_xlabel('X')
        ax.set_ylabel('Y')

        ani = animation.FuncAnimation(
            fig,
            update_heatmap,
            fargs=(thermal_camera, im),
            interval=100,
            blit=False,
            cache_frame_data=False
        )

        plt.show()

    except KeyboardInterrupt:
        logger.info("KeyboardInterrupt received. Exiting...")
    except Exception as e:
        logger.error(f"An error occurred: {e}")
    finally:
        thermal_camera.stop()
        thermal_camera.close()
        plt.close('all')


if __name__ == '__main__':
    main()

