import time
import signal
import sys
from adafruit_circuitpython_dht import DHT22
from board import D22

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_dht22(sensor):
    """
    Reads temperature and humidity from a DHT22 sensor with retry logic.
    Returns (temperature, humidity) or (None, None) on failure.
    """
    for attempt in range(2):
        try:
            temperature = sensor.temperature
            humidity = sensor.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
            print(f"Warning: DHT22 returned None on attempt {attempt + 1}")
        except RuntimeError as e:
            print(f"RuntimeError reading DHT22 (attempt {attempt + 1}): {e}")
        except Exception as e:
            print(f"Unexpected error reading DHT22 (attempt {attempt + 1}): {e}")
        time.sleep(0.1)
    return None, None

def main():
    global _running

    # Register signal handler for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    sensor = None
    try:
        # Initialize DHT22 on BCM pin 22 (board.D22)
        sensor = DHT22(D22, use_pulseio=False)
        print("DHT22 sensor initialized. Waiting 1 second for stabilization...")
        time.sleep(1)

        while _running:
            temperature, humidity = read_dht22(sensor)

            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f} C")
                print(f"Humidity: {humidity:.1f} %")
            else:
                print("Failed to read from DHT22 sensor after retries.")

            # Sleep in small increments to allow prompt response to signals
            for _ in range(30):
                if not _running:
                    break
                time.sleep(0.1)

    except Exception as e:
        print(f"Fatal error: {e}")
    finally:
        if sensor is not None:
            try:
                sensor.exit()
            except Exception:
                pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

