    """Release the DHT11 sensor on exit (signal-safe best-effort)."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None
    if signum is not None:
        sys.exit(0)

def main():
