                print(f"Read error: {e}")
            except Exception as e:
                print(f"Unexpected error during read: {e}")

            time.sleep(5)

    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    finally:
        _cleanup()

if __name__ == "__main__":
