import time
import signal
import sys
import logging
import smbus2
from ina219 import INA219, DeviceRangeError

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

class UPSPlusMonitor:
    def __init__(self, bus_number=1, supply_shunt=0.00725, battery_shunt=0.005):
        self.bus_number = bus_number
        self.supply_shunt = supply_shunt
        self.battery_shunt = battery_shunt
        self.bus = None
        self.supply_sensor = None
        self.battery_sensor = None
        self.running = True

    def initialize_i2c(self):
        try:
            self.bus = smbus2.SMBus(self.bus_number)
            logger.info(f"I2C bus {self.bus_number} initialized.")
        except Exception as e:
            logger.error(f"Failed to initialize I2C bus {self.bus_number}: {e}")
            self.bus = None
            return False
        return True

    def initialize_ina219(self, shunt_resistor, label):
        try:
            sensor = INA219(shunt_resistor, busnum=self.bus_number, address=0x40)
            sensor.configure()
            logger.info(f"{label} INA219 initialized.")
            return sensor
        except Exception as e:
            logger.error(f"Failed to initialize {label} INA219: {e}")
            return None

    def read_supply_data(self):
        if self.supply_sensor is None:
            return None, None, None
        try:
            voltage = self.supply_sensor.voltage()
            current = self.supply_sensor.current()
            power = self.supply_sensor.power()
            return voltage, current, power
        except DeviceRangeError:
            logger.warning("Supply current out of range.")
            return None, None, None
        except Exception as e:
            logger.error(f"Error reading supply data: {e}")
            return None, None, None

    def read_battery_data(self):
        if self.battery_sensor is None:
            return None, None, None
        try:
            voltage = self.battery_sensor.voltage()
            current = self.battery_sensor.current()
            power = self.battery_sensor.power()
            return voltage, current, power
        except DeviceRangeError:
            logger.warning("Battery current out of range.")
            return None, None, None
        except Exception as e:
            logger.error(f"Error reading battery data: {e}")
            return None, None, None

    def get_battery_status(self, current):
        if current is None:
            return "Unknown"
        return "Charging" if current > 0 else "Discharging"

    def run(self):
        if not self.initialize_i2c():
            return

        self.supply_sensor = self.initialize_ina219(self.supply_shunt, "Supply")
        self.battery_sensor = self.initialize_ina219(self.battery_shunt, "Battery")

        if self.supply_sensor is None and self.battery_sensor is None:
            logger.error("No sensors initialized. Exiting.")
            self.cleanup()
            return

        try:
            while self.running:
                supply_voltage, supply_current, supply_power = self.read_supply_data()
                battery_voltage, battery_current, battery_power = self.read_battery_data()

                if supply_voltage is not None and supply_current is not None and supply_power is not None:
                    print(f"Supply Voltage: {supply_voltage:.2f} V")
                    print(f"Supply Current: {supply_current:.2f} mA")
                    print(f"Supply Power: {supply_power:.2f} mW")
                else:
                    print("Supply data unavailable.")

                if battery_voltage is not None and battery_current is not None and battery_power is not None:
                    status = self.get_battery_status(battery_current)
                    print(f"Battery Voltage: {battery_voltage:.2f} V")
                    print(f"Battery Current: {battery_current:.2f} mA ({status})")
                    print(f"Battery Power: {battery_power:.2f} mW")
                else:
                    print("Battery data unavailable.")

                print("-" * 40)
                time.sleep(2)
        except KeyboardInterrupt:
            logger.info("Program terminated by user.")
        except Exception as e:
            logger.error(f"An unexpected error occurred: {e}")
        finally:
            self.cleanup()

    def cleanup(self):
        if self.bus is not None:
            try:
                self.bus.close()
                logger.info("I2C bus closed.")
            except Exception as e:
                logger.error(f"Error closing I2C bus: {e}")
            finally:
                self.bus = None

    def stop(self):
        self.running = False

def main():
    monitor = UPSPlusMonitor()

    def signal_handler(sig, frame):
        logger.info("Signal received, stopping...")
        monitor.stop()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    monitor.run()

if __name__ == "__main__":
    main()

