import time
import datetime
import csv
import random
import signal
import sys
import os
import fcntl
import traceback

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("RPi.GPIO not available. Running in simulation mode.")
    GPIO = None

# Configuration
DHT_PIN_1 = 17
DHT_PIN_2 = 27
HIGH_HUMIDITY_THRESHOLD = 75.0
LOW_HUMIDITY_THRESHOLD = 45.0
DATA_LOG_FILE = "retail_data.csv"
ALERT_LOG_FILE = "retail_alerts.log"
CLOUD_LOG_FILE = "cloud_log.log"
ERROR_LOG_FILE = "error.log"
READ_INTERVAL = 60
MAX_RETRIES = 3
RETRY_DELAY = 2
DEBOUNCE_TIME = 30 * 60

# Global state
last_alert_time = {
    "high_humidity_sensor_1": 0,
    "low_humidity_sensor_1": 0,
    "high_humidity_sensor_2": 0,
    "low_humidity_sensor_2": 0,
}
running = True


def log_error(message):
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    try:
        with open(ERROR_LOG_FILE, "a") as f:
            f.write(f"{timestamp} - ERROR: {message}\n")
            traceback.print_exc(file=f)
    except Exception as e:
        print(f"Failed to write to error log: {e}")


def log_data(timestamp, sensor_id, humidity, temperature):
    try:
        file_exists = os.path.isfile(DATA_LOG_FILE)
        with open(DATA_LOG_FILE, "a", newline="") as csvfile:
            fcntl.flock(csvfile.fileno(), fcntl.LOCK_EX)
            writer = csv.writer(csvfile)
            if not file_exists:
                writer.writerow(["Timestamp", "Sensor ID", "Humidity (%)", "Temperature (°C)"])
            writer.writerow([timestamp, sensor_id, f"{humidity:.2f}", f"{temperature:.2f}"])
            fcntl.flock(csvfile.fileno(), fcntl.LOCK_UN)
    except Exception as e:
        log_error(f"Error writing to data log: {e}")


def check_and_log_alerts(timestamp, sensor_id, humidity, temperature):
    now = time.time()
    alert_types = [
        ("high_humidity", HIGH_HUMIDITY_THRESHOLD),
        ("low_humidity", LOW_HUMIDITY_THRESHOLD),
    ]
    for alert_type, threshold in alert_types:
        if humidity > threshold:
            alert_key = f"{alert_type.replace('_', ' ')} {sensor_id}"
            if now - last_alert_time[alert_key] > DEBOUNCE_TIME:
                alert_message = f"{timestamp} - {alert_key} - Humidity: {humidity:.2f}%, Temperature: {temperature:.2f}°C"
                try:
                    with open(ALERT_LOG_FILE, "a") as f:
                        f.write(alert_message + "\n")
                except Exception as e:
                    log_error(f"Error writing to alert log: {e}")
                last_alert_time[alert_key] = now
                print(alert_message)


def simulate_cloud_push(timestamp, sensor_id, humidity, temperature):
    try:
        with open(CLOUD_LOG_FILE, "a") as f:
            f.write(f"{timestamp} - Simulated Cloud Push - Sensor ID: {sensor_id}, Humidity: {humidity:.2f}%, Temperature: {temperature:.2f}°C\n")
    except Exception as e:
        log_error(f"Error writing to cloud log: {e}")


def read_dht22(pin):
    if GPIO is None:
        return None, None
    try:
        GPIO.setup(pin, GPIO.IN)
        time.sleep(0.5)
        GPIO.setup(pin, GPIO.OUT)
        GPIO.output(pin, GPIO.LOW)
        time.sleep(0.018)
        GPIO.setup(pin, GPIO.IN)
        count = 0
        while GPIO.input(pin) == GPIO.LOW:
            count += 1
            if count > 1000:
                return None, None
        count = 0
        while GPIO.input(pin) == GPIO.HIGH:
            count += 1
            if count > 1000:
                return None, None
        count = 0
        while GPIO.input(pin) == GPIO.LOW:
            count += 1
            if count > 1000:
                return None, None
        count = 0
        while GPIO.input(pin) == GPIO.HIGH:
            count += 1
            if count > 1000:
                return None, None
        if count != 80:
            return None, None
        data = []
        for _ in range(40):
            count = 0
            while GPIO.input(pin) == GPIO.LOW:
                count += 1
                if count > 1000:
                    return None, None
            count = 0
            while GPIO.input(pin) == GPIO.HIGH:
                count += 1
                if count > 1000:
                    return None, None
            if count == 0:
                return None, None
            data.append(count)
        humidity = 0
        for i in range(0, 16, 2):
            humidity += data[i] * 256 + data[i + 1]
        humidity /= 10
        humidity = round(humidity, 2)
        if humidity > 100:
            return None, None
        temperature = 0
        for i in range(16, 32, 2):
            temperature += data[i] * 256 + data[i + 1]
        temperature /= 10
        temperature = round(temperature, 2)
        if temperature < 0 or temperature > 35:
            return None, None
        return humidity, temperature
    except Exception as e:
        log_error(f"Error reading DHT22 on pin {pin}: {e}")
        return None, None


def cleanup_gpio():
    if GPIO is not None:
        try:
            GPIO.cleanup()
        except Exception as e:
            log_error(f"Error cleaning up GPIO: {e}")


def signal_handler(sig, frame):
    global running
    running = False


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    if GPIO is not None:
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(DHT_PIN_1, GPIO.IN)
            GPIO.setup(DHT_PIN_2, GPIO.IN)
        except Exception as e:
            log_error(f"Error initializing GPIO: {e}")
    try:
        while running:
            timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            humidity1, temperature1 = None, None
            humidity2, temperature2 = None, None
            for attempt in range(MAX_RETRIES):
                humidity1 = read_dht22(DHT_PIN_1)
                temperature1 = read_dht22(DHT_PIN_1)
                if humidity1 is not None and temperature1 is not None:
                    break
                if attempt < MAX_RETRIES - 1:
                    time.sleep(RETRY_DELAY)
            for attempt in range(MAX_RETRIES):
                humidity2 = read_dht22(DHT_PIN_2)
                temperature2 = read_dht22(DHT_PIN_2)
                if humidity2 is not None and temperature2 is not None:
                    break
                if attempt < MAX_RETRIES - 1:
                    time.sleep(RETRY_DELAY)
            if humidity1 is not None and temperature1 is not None:
                log_data(timestamp, "Sensor 1", humidity1, temperature1)
                check_and_log_alerts(timestamp, "Sensor 1", humidity1, temperature1)
                if random.random() < 0.8:
                    simulate_cloud_push(timestamp, "Sensor 1", humidity1, temperature1)
            else:
                log_error("Failed to read sensor 1 after multiple retries.")
            if humidity2 is not None and temperature2 is not None:
                log_data(timestamp, "Sensor 2", humidity2, temperature2)
                check_and_log_alerts(timestamp, "Sensor 2", humidity2, temperature2)
                if random.random() < 0.8:
                    simulate_cloud_push(timestamp, "Sensor 2", humidity2, temperature2)
            else:
                log_error("Failed to read sensor 2 after multiple retries.")
            for _ in range(READ_INTERVAL):
                if not running:
                    break
                time.sleep(1)
    except Exception as e:
        log_error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup_gpio()


if __name__ == "__main__":
    main()

