def _handle_signal(signum, frame):
    global _running
    _running = False

signal.signal(signal.SIGINT, _handle_signal)
signal.signal(signal.SIGTERM, _handle_signal)

# ---------------------------------------------------------------------------
# Logging helpers
# ---------------------------------------------------------------------------
def log_line(log_file, message):
    """Append a single line to the log file and flush immediately."""
    try:
        log_file.write(message + "\n")
        log_file.flush()
    except OSError as exc:
        print(f"Warning: failed to write to log file: {exc}", file=sys.stderr)

# ---------------------------------------------------------------------------
# Main loop
# ---------------------------------------------------------------------------
def main():
    log_file = None
    sensor = None

    try:
        # Open log file in append mode; defer to the finally block for
        # guaranteed cleanup.
        log_file = open("temp_log.txt", "a", encoding="utf-8")

        for reading_num in range(10):
            if not _running:
                print("Shutdown requested — stopping early.", file=sys.stderr)
                break

            timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            temperature = None

            # --- Read sensor -------------------------------------------------
            if _HW_AVAILABLE:
                try:
                    temperature = sensor.temperature
                except RuntimeError as exc:
                    # DHT22 single-wire reads occasionally fail transiently;
                    # log and continue rather than crashing.
                    temperature = None
                    print(f"Reading {reading_num + 1}/10: {exc}", file=sys.stderr)
                except Exception as exc:
                    # Unexpected error (e.g. GPIO permission, bus error) —
                    # log and continue so the loop can still flush the file.
                    temperature = None
                    print(f"Unexpected error on reading {reading_num + 1}/10: {exc}", file=sys.stderr)
            else:
                # No hardware — simulate a plausible reading for testing.
                temperature = 25.0

            # --- Build and log the line -------------------------------------
            if temperature is not None:
                log_message = f"{timestamp}, temperature: {temperature:.2f} C"
            else:
                log_message = f"{timestamp}, temperature: ERROR — {sys.exc_info()[1]}"

            log_line(log_file, log_message)
            print(f"Logged: {log_message}")

            # --- Wait between readings (skip after the last) -----------------
            if reading_num < 9 and _running:
                time.sleep(5)

    except OSError as exc:
        print(f"Error opening log file: {exc}", file=sys.stderr)
    finally:
        # --- Clean up resources --------------------------------------------
        if sensor is not None:
            try:
                sensor.exit()
            except Exception:
                pass
        if log_file is not None:
            try:
                log_file.close()
            except OSError:
                pass
        print("Program finished.")

if __name__ == "__main__":
    # --- Initialise hardware (degrade gracefully if unavailable) -----------
    if _HW_AVAILABLE:
        try:
            sensor = adafruit_dht.DHT22(board.D4, use_pulseio=False)
        except Exception as exc:
            print(f"Warning: could not initialise DHT22 on GPIO4: {exc}", file=sys.stderr)
            sensor = None
    else:
        print("Warning: adafruit_dht / board not available — running in simulation mode.", file=sys.stderr)

    main()

