import time
import logging
import paho.mqtt.client as mqtt
from gpiozero import DHT22

import config

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
log = logging.getLogger(__name__)

DEGREE_CELSIUS = '\u00B0C'

running = True

def signal_handler(signum, frame):
    global running
    log.info('Signal %s received, shutting down...', signum)
    running = False

def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        log.info('Connected to MQTT broker')
    else:
        log.error('MQTT connection failed with reason code %s', reason_code)

def on_disconnect(client, userdata, flags, reason_code, properties):
    log.warning('Disconnected from MQTT broker (reason code: %s)', reason_code)

def publish_sensor_data(client, temperature, humidity):
    try:
        temp_topic = f"homie/{config.homieclientid}/{config.homienodes}/temperature"
        hum_topic = f"homie/{config.homieclientid}/{config.homienodes}/humidity"
        info_topic = f"homie/{config.homieclientid}/$state"
        client.publish(temp_topic, f"{temperature:.1f}{DEGREE_CELSIUS}", qos=1)
        client.publish(hum_topic, f"{humidity:.1f}%", qos=1)
        client.publish(info_topic, "on", qos=1)
        log.info('Published: %.1f%s, %.1f%%', temperature, DEGREE_CELSIUS, humidity)
    except Exception as e:
        log.error('Failed to publish sensor data: %s', e)

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION2)
    if getattr(config, 'mqttusername', None):
        client.username_pw_set(config.mqttusername, config.mqttpassword)
    client.on_connect = on_connect
    client.on_disconnect = on_disconnect

    try:
        client.connect(config.mqttbroker, port=config.mqttport, keepalive=60)
    except Exception as e:
        log.error('MQTT connection error: %s', e)
        return

    client.loop_start()

    sensor = None
    try:
        sensor = DHT22(config.dhtgpiopin)
        log.info('DHT22 initialized on BCM pin %s', config.dhtgpiopin)
    except Exception as e:
        log.error('Failed to initialize DHT22 on pin %s: %s', config.dhtgpiopin, e)
        client.loop_stop()
        client.disconnect()
        return

    try:
        while running:
            try:
                temperature = sensor.temperature
                humidity = sensor.humidity
                if temperature is None or humidity is None:
                    log.warning('DHT22 returned None reading')
                else:
                    publish_sensor_data(client, temperature, humidity)
            except RuntimeError as e:
                log.warning('DHT22 read error (will retry): %s', e)
            except Exception as e:
                log.error('Unexpected error reading DHT22: %s', e)

            time.sleep(max(0, config.publishtime))
    finally:
        log.info('Cleaning up resources...')
        if sensor is not None:
            try:
                sensor.close()
            except Exception:
                pass
        try:
            client.loop_stop()
            client.disconnect()
        except Exception:
            pass
        log.info('Shutdown complete')

if __name__ == '__main__':
    main()

