import smbus
import time
import signal
import sys

I2C_BUS = 1
AHT20_ADDR = 0x5C

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _crc8(data):
    crc = 0xFF
    for byte in data:
        crc ^= byte
        for _ in range(8):
            if crc & 0x80:
                crc = ((crc << 1) ^ 0x31) & 0xFF
            else:
                crc = (crc << 1) & 0xFF
    return crc

def _read_block(bus, addr, n):
    return bus.read_i2c_block_data(addr, 0x00, n)

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)

    try:
        bus = smbus.SMBus(I2C_BUS)
    except IOError as e:
        print(f"Error: Failed to open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                bus.write_byte(AHT20_ADDR, 0x01)
                time.sleep(0.02)

                bus.write_byte(AHT20_ADDR, 0x00)
                time.sleep(0.01)

                bus.write_byte(AHT20_ADDR, 0x03)
                time.sleep(0.08)

                data = _read_block(bus, AHT20_ADDR, 7)
                if len(data) < 7:
                    print("Error: Incomplete data read from sensor.", file=sys.stderr)
                    time.sleep(5)
                    continue

                if _crc8(data[:-1]) != data[-1]:
                    print("CRC Error: Computed CRC does not match received CRC.")
                else:
                    raw_h = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
                    raw_t = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF

                    humidity = (raw_h / 2**20) * 100.0
                    temperature_c = (raw_t / 2**20) * 200.0 - 50.0
                    temperature_f = (temperature_c * 9.0 / 5.0) + 32.0

                    ts = time.strftime("%Y-%m-%d %H:%M:%S")
                    print(f"{ts} - Temp: {temperature_c:.2f}C / {temperature_f:.2f}F, Humidity: {humidity:.2f}%")

                time.sleep(5)

            except IOError as e:
                print(f"I2C bus error: {e}", file=sys.stderr)
                time.sleep(5)
            except Exception as e:
                print(f"Unexpected error: {e}", file=sys.stderr)
                time.sleep(5)
    finally:
        bus.close()
        print("I2C bus closed. Exiting.")

if __name__ == "__main__":
    main()

