import signal
import sys
import time
import logging

from ina219 import INA219, DeviceRangeError
from ups import UPS

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("rpi_energy")

_running = True


def _handle_signal(signum, _frame):
    global _running
    log.info("Received signal %s, shutting down...", signum)
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    supply_shunt = 0.00725
    battery_shunt = 0.005

    supply_ina = None
    battery_ina = None
    ups = None

    try:
        supply_ina = INA219(shunt_resistance=supply_shunt, busnum=1, address=0x40)
        supply_ina.configure()
        log.info("Supply INA219 initialised (shunt=%.5f Ω, bus 1, addr 0x40).", supply_shunt)
    except Exception as exc:
        log.error("Failed to initialise supply INA219: %s", exc)

    try:
        battery_ina = INA219(shunt_resistance=battery_shunt, busnum=1, address=0x41)
        battery_ina.configure()
        log.info("Battery INA219 initialised (shunt=%.5f Ω, bus 1, addr 0x41).", battery_shunt)
    except Exception as exc:
        log.error("Failed to initialise battery INA219: %s", exc)

    try:
        ups = UPS()
        ups.begin()
        log.info("UPS controller initialised.")
    except Exception as exc:
        log.error("Failed to initialise UPS controller: %s", exc)

    try:
        while _running:
            try:
                if supply_ina is not None:
                    try:
                        supply_voltage = supply_ina.voltage()
                        supply_current = supply_ina.current()
                        print(f"Supply: {supply_voltage:.3f} V, {supply_current:.3f} mA")
                    except DeviceRangeError:
                        log.warning("Supply current out of range.")
                    except Exception as exc:
                        log.error("Error reading supply INA219: %s", exc)

                if battery_ina is not None:
                    try:
                        battery_voltage = battery_ina.voltage()
                        battery_current = battery_ina.current()
                        print(f"Battery: {battery_voltage:.3f} V, {battery_current:.3f} mA")
                    except DeviceRangeError:
                        log.warning("Battery current out of range.")
                    except Exception as exc:
                        log.error("Error reading battery INA219: %s", exc)

                if ups is not None:
                    try:
                        ups_data = ups.read()
                        print(
                            f"UPS: Proc {ups_data.proc_mv:d}mV, "
                            f"Battery Port {ups_data.batt_port_mv:d}mV, "
                            f"Temp {ups_data.temp:d}C, Capacity {ups_data.capacity:d}%"
                        )
                    except Exception as exc:
                        log.error("Error reading UPS: %s", exc)

            except Exception as exc:
                log.error("Unexpected error in main loop: %s", exc)

            for _ in range(20):
                if not _running:
                    break
                time.sleep(0.1)

    finally:
        log.info("Cleaning up resources...")
        if supply_ina is not None:
            try:
                supply_ina.shutdown()
            except Exception:
                pass
        if battery_ina is not None:
            try:
                battery_ina.shutdown()
            except Exception:
                pass
        if ups is not None:
            try:
                ups.end()
            except Exception:
                pass
        log.info("Program terminated.")


if __name__ == "__main__":
    main()

