import time
import datetime
import signal
import sys
import csv
import os
import RPi.GPIO as GPIO

# Constants
DHT_PIN = 4
LOG_FILE = "humidity_log.csv"
SYSTEM_LOG = "humidity_system.log"
CENTRAL_LOG = "central_log.txt"
TEMP_THRESHOLD_HIGH = 30.0
TEMP_THRESHOLD_LOW = 10.0
HUMIDITY_THRESHOLD_HIGH = 80.0
HUMIDITY_THRESHOLD_LOW = 30.0
READ_INTERVAL = 60
MAX_RETRIES = 3
RETRY_DELAY = 2
WARMUP_TIME = 15

# Global flag for graceful shutdown
_running = True

def signal_handler(signum, frame):
    global _running
    _running = False

def log_message(message, log_file):
    timestamp = datetime.datetime.now().isoformat()
    try:
        with open(log_file, "a") as f:
            f.write(f"{timestamp} - {message}\n")
            f.flush()
    except IOError as e:
        print(f"Error writing to {log_file}: {e}", file=sys.stderr)

def log_data(temperature, humidity, log_file):
    timestamp = datetime.datetime.now().isoformat()
    try:
        with open(log_file, "a", newline="") as f:
            writer = csv.writer(f)
            if f.tell() == 0:
                writer.writerow(["Timestamp", "Temperature (C)", "Humidity (%)"])
            writer.writerow([timestamp, f"{temperature:.2f}", f"{humidity:.2f}"])
            f.flush()
    except IOError as e:
        print(f"Error writing to {log_file}: {e}", file=sys.stderr)

def log_central(temperature, humidity):
    timestamp = datetime.datetime.now().isoformat()
    try:
        with open(CENTRAL_LOG, "a") as f:
            f.write(f"{timestamp} - Temperature: {temperature:.2f}C, Humidity: {humidity:.2f}%\n")
            f.flush()
    except IOError as e:
        print(f"Error writing to {CENTRAL_LOG}: {e}", file=sys.stderr)

def check_thresholds(temperature, humidity):
    if temperature > TEMP_THRESHOLD_HIGH or temperature < TEMP_THRESHOLD_LOW:
        log_message(f"WARNING: Temperature out of range: {temperature:.2f}C", SYSTEM_LOG)
    if humidity > HUMIDITY_THRESHOLD_HIGH or humidity < HUMIDITY_THRESHOLD_LOW:
        log_message(f"WARNING: Humidity out of range: {humidity:.2f}%", SYSTEM_LOG)

def read_dht22():
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            GPIO.setup(DHT_PIN, GPIO.IN)
            time.sleep(0.05)
            GPIO.setup(DHT_PIN, GPIO.OUT)
            GPIO.output(DHT_PIN, GPIO.LOW)
            time.sleep(0.02)
            GPIO.output(DHT_PIN, GPIO.HIGH)
            time.sleep(0.04)
            GPIO.setup(DHT_PIN, GPIO.IN)

            timeout = time.time() + 0.05
            while GPIO.input(DHT_PIN) == GPIO.LOW:
                if time.time() > timeout:
                    raise TimeoutError("Low timeout")
                timeout += 0.05

            timeout = time.time() + 0.05
            while GPIO.input(DHT_PIN) == GPIO.HIGH:
