import subprocess
import time
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

PWM_PIN = 14
PWM_FREQ = 100
TEMP_CMD = ["vcgencmd", "measure_temp"]
CHECK_INTERVAL = 5

fan_speed = 0
running = True

def get_cpu_temp():
    try:
        result = subprocess.run(TEMP_CMD, capture_output=True, text=True, timeout=5)
        if result.returncode != 0:
            logging.error(f"vcgencmd failed: {result.stderr.strip()}")
            return None
        temp_str = result.stdout.strip()
        return float(temp_str.replace("temp=", "").replace("'C", ""))
    except FileNotFoundError:
        logging.error("vcgencmd not found; is this running on a Raspberry Pi?")
        return None
    except subprocess.TimeoutExpired:
        logging.error("vcgencmd timed out")
        return None
    except (ValueError, OSError) as e:
        logging.error(f"Error parsing temperature: {e}")
        return None

def set_fan_speed(speed):
    global fan_speed
    fan_speed = speed
    logging.info(f"Fan speed set to: {speed}")

def signal_handler(sig, frame):
    global running
    logging.info(f"Signal {sig} received, shutting down...")
    running = False

def main():
    global fan_speed
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PWM_PIN, GPIO.OUT)
        pwm = GPIO.PWM(PWM_PIN, PWM_FREQ)
        pwm.start(0)
        logging.info(f"PWM initialized on GPIO{PWM_PIN} at {PWM_FREQ} Hz")
    except ImportError:
        logging.warning("RPi.GPIO not available; running in degraded mode without hardware PWM")
        pwm = None
    except Exception as e:
        logging.warning(f"Failed to initialize PWM on GPIO{PWM_PIN}: {e}; running in degraded mode")
        pwm = None

    try:
        while running:
            temp = get_cpu_temp()
            if temp is not None:
                if temp > 50:
                    set_fan_speed(75)
                elif temp > 45:
                    set_fan_speed(50)
                elif temp > 40:
                    set_fan_speed(25)
                else:
                    set_fan_speed(0)
            else:
                logging.warning("Temperature reading failed; keeping last fan speed")
            for _ in range(CHECK_INTERVAL):
                if not running:
                    break
                time.sleep(1)
    finally:
        if pwm is not None:
            try:
                pwm.stop()
                logging.info("PWM stopped")
            except Exception as e:
                logging.error(f"Error stopping PWM: {e}")
        GPIO.cleanup()
        logging.info("GPIO cleaned up")

if __name__ == "__main__":
    main()

