import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("Error: RPi.GPIO library not found. Install with: sudo apt install python3-rpi.gpio")
    sys.exit(1)

LED_PIN = 17
led_state = False


def cleanup_gpio():
    """Drive the LED low and release the GPIO pin."""
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
    except Exception:
        pass
    try:
        GPIO.cleanup(LED_PIN)
    except Exception:
        pass


def signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT for clean shutdown."""
    print("\nExiting program.")
    cleanup_gpio()
    sys.exit(0)


def main():
    global led_state

    signal.signal(signal.SIGTERM, signal_handler)
    signal.signal(signal.SIGINT, signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"Error: Failed to initialize GPIO: {e}")
        print("Check that you have permission (run with sudo) and the pin is not already in use.")
        sys.exit(1)

    try:
        while True:
            try:
                user_input = input("Enter 'on' to turn the LED on, 'off' to turn it off, or 'exit' to quit: ").strip().lower()
            except EOFError:
                print("\nExiting program.")
                break

            if user_input == "on":
                led_state = True
                GPIO.output(LED_PIN, GPIO.HIGH)
                print(f"LED is now: {led_state}")
                time.sleep(0.1)
            elif user_input == "off":
                led_state = False
                GPIO.output(LED_PIN, GPIO.LOW)
                print(f"LED is now: {led_state}")
                time.sleep(0.1)
            elif user_input == "exit":
                print("Exiting program.")
                break
            else:
                print("Invalid input")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup_gpio()


if __name__ == "__main__":
    main()

