import signal
import sys
import time
import requests

try:
    from gpiozero import LED, MotionSensor
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

LED_PIN = 18
PIR_PIN = 17
SERVER_URL = "http://127.0.0.1:5000/led"
POLL_INTERVAL = 1.0

led = None
pir = None
running = True


def handle_sigint(signum, frame):
    global running
    running = False


def send_led_state(state: str):
    try:
        resp = requests.post(SERVER_URL, json={"led": state}, timeout=5)
        print(f"Server response: {resp.status_code} - {resp.text}")
    except requests.exceptions.RequestException as e:
        print(f"Network error: {e}")


def main():
    global led, pir
    signal.signal(signal.SIGINT, handle_sigint)

    try:
        led = LED(LED_PIN)
        pir = MotionSensor(PIR_PIN)
    except Exception as e:
        print(f"GPIO initialization error: {e}")
        sys.exit(1)

    print("PIR motion sensor monitoring started. Press Ctrl+C to exit.")

    try:
        while running:
            if pir.motion_detected:
                led.on()
                send_led_state("on")
            else:
                led.off()
                send_led_state("off")
            time.sleep(POLL_INTERVAL)
    finally:
        if led is not None:
            led.close()
        if pir is not None:
            pir.close()
        print("GPIO cleanup done.")


if __name__ == "__main__":
    main()

