import sys
import time

try:
    from gpiozero import Button
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

# --- Configuration -----------------------------------------------------------
SENSOR_PINS = [17, 27, 22]          # BCM pin numbers for sensors 1, 2, 3
POLL_INTERVAL = 1.0                  # seconds between readings

# --- Globals for cleanup -----------------------------------------------------
_sensors = []
_running = True


def _cleanup():
    """Release every GPIO resource we acquired."""
    for s in _sensors:
        try:
            s.close()
        except Exception:
            pass
    _sensors.clear()


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def main():
    global _sensors

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # --- Initialize sensors --------------------------------------------------
    try:
        for idx, pin in enumerate(SENSOR_PINS, start=1):
            try:
                sensor = Button(pin, pull_up=True)
                _sensors.append(sensor)
            except (GPIOZeroError, GPIODeviceError) as exc:
                print(f"Error: failed to initialize GPIO{pin} (sensor {idx}): {exc}", file=sys.stderr)
                _cleanup()
                sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error during GPIO initialization: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    # --- Startup message -----------------------------------------------------
    print(f"Monitoring {len(SENSOR_PINS)} sensors on pins {SENSOR_PINS} every {POLL_INTERVAL}s.")

    # --- Main polling loop ---------------------------------------------------
    try:
        while _running:
            for idx, sensor in enumerate(_sensors, start=1):
                try:
                    if sensor.is_active:
                        print(f"Response for sensor {idx}")
                except (GPIOZeroError, GPIODeviceError) as exc:
                    print(f"Error reading sensor {idx} on GPIO{SENSOR_PINS[idx - 1]}: {exc}", file=sys.stderr)
                except Exception as exc:
                    print(f"Unexpected error reading sensor {idx}: {exc}", file=sys.stderr)

            time.sleep(POLL_INTERVAL)

    except KeyboardInterrupt:
        pass
    finally:
        _cleanup()
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

