#!/usr/bin/env python3
"""
led_control.py — Button-controlled LED toggle for Raspberry Pi.

Wiring:
  - LED anode  -> 330 ohm resistor -> GPIO 17 (BCM, physical pin 11)
  - LED cathode -> GND
  - Button     -> 3.3 V (physical pin 1)
                 -> 10 kΩ pull-down resistor -> GPIO 5 (BCM, physical pin 29)
                 -> GND

The on-board pull-up on GPIO 2 is fixed, so we use GPIO 5 with an external
pull-down to avoid conflicts.
"""

import sys
import time

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("RPi.GPIO is not available. Running in mock mode.", file=sys.stderr)
    GPIO = None

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
LED_PIN = 17          # BCM 17 (physical pin 11)
BUTTON_PIN = 5        # BCM 5  (physical pin 29)
POLL_INTERVAL = 0.1   # seconds

# ---------------------------------------------------------------------------
# GPIO setup
# ---------------------------------------------------------------------------
if GPIO is not None:
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    except Exception as exc:
        print(f"GPIO setup failed: {exc}", file=sys.stderr)
        sys.exit(1)
else:
    # Mock mode: initialise state variables
    led_state = False


def cleanup():
    """Turn off the LED and release GPIO resources."""
    if GPIO is not None:
        try:
            GPIO.output(LED_PIN, GPIO.LOW)
            GPIO.cleanup()
        except Exception:
            pass


def main():
    try:
        while True:
            if GPIO is not None:
                button_state = GPIO.input(BUTTON_PIN)
            else:
                # Mock: toggle state on each iteration
                button_state = not led_state
                led_state = not led_state

            if button_state:
                print("Button pressed! LED is ON")
                if GPIO is not None:
                    GPIO.output(LED_PIN, GPIO.HIGH)
            else:
                print("Button released! LED is OFF")
                if GPIO is not None:
                    GPIO.output(LED_PIN, GPIO.LOW)

            time.sleep(POLL_INTERVAL)

    except KeyboardInterrupt:
        print("\nExiting program...")
    except Exception as exc:
        print(f"An error occurred: {exc}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

