import threading
import time

try:
    import dog
except ImportError:
    print("Error: The 'dog' library is not installed. Please install it.")
    sys.exit(1)

# Global variables
log_file = None
receive_thread = None
dog_api_call = None


def cleanup_resources():
    """Clean up resources on exit."""
    global dog_api_call
    if dog_api_call is not None:
        try:
            dog_api_call.stop()
        except Exception:
            pass
        dog_api_call = None


def signal_handler(signum, frame):
    """Handle SIGINT and SIGTERM for graceful shutdown."""
    print(f"\nReceived signal {signum}. Exiting gracefully...")
    cleanup_resources()
    sys.exit(0)


def help_command(args):
    """Display help information."""
    if not args:
        print("Available commands:")
        print("  help [command]: Display help information")
        print("  start <filename>: Start logging data to a file")
        print("  stop: Stop logging data")
        print("  display: Display the contents of the log file")
        print("  send <data>: Send data using DOG.send()")
        print("  write <data>: Write data directly to the log file")
        print("  exit: Stop logging and exit the program")
    else:
        command = args[0].lower()
        if command == "help":
            print("Usage: help [command]")
        elif command == "start":
            print("Usage: start <filename>")
        elif command == "stop":
            print("Usage: stop")
        elif command == "display":
            print("Usage: display")
        elif command == "send":
            print("Usage: send <data>")
        elif command == "write":
            print("Usage: write <data>")
        elif command == "exit":
            print("Usage: exit")
        else:
            print(f"Unknown command: {command}")


def start_command(args):
    """Start logging data to a file."""
    global log_file, receive_thread, dog_api_call

    if not args:
        print("Error: Please specify a filename to log data to.")
        return

    filename = args[0]

    try:
        log_file = open(filename, "a")
        dog_api_call = dog.DataLogger()
        receive_thread = threading.Thread(target=dog_receive, daemon=True)
        receive_thread.start()
        print(f"Logging data to {filename}...")
    except Exception as e:
        print(f"Error starting logging: {e}")
        if log_file:
            log_file.close()
        log_file = None


def stop_command(args):
    """Stop logging data."""
    global log_file, receive_thread, dog_api_call

    if dog_api_call is not None:
        try:
            dog_api_call.stop()
        except Exception as e:
            print(f"Error stopping API call: {e}")
        dog_api_call = None

    if receive_thread and receive_thread.is_alive():
        receive_thread.join(timeout=1.0)
        receive_thread = None

    if log_file:
        try:
            log_file.close()
        except Exception:
            pass
        log_file = None

    print("Logging stopped.")


def display_command(args):
    """Display the contents of the log file."""
    global log_file

    if not log_file:
        print("No log file is currently open.")
        return

    try:
        with open(log_file.name, "r") as f:
            print(f.read())
    except Exception as e:
        print(f"Error displaying log file: {e}")


def send_command(args):
    """Send data using DOG.send()."""
    if not args:
        print("Error: Please specify data to send.")
        return

    data = " ".join(args)
    try:
        dog.send(data)
        print(f"Sent: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")


def write_command(args):
    """Write data directly to the log file."""
    global log_file

    if not log_file:
        print("Error: Logging is not started. Use the 'start' command.")
        return

    data = " ".join(args)
    try:
        log_file.write(data + "\n")
        log_file.flush()
        print(f"Wrote to log: {data}")
    except Exception as e:
        print(f"Error writing to log file: {e}")


def dog_receive():
    """Background thread to receive and log data."""
    while dog_api_call is not None:
        try:
            data = dog.receive()
            if data:
                try:
                    log_file.write(data + "\n")
                    log_file.flush()
                except Exception as e:
                    print(f"Error writing to log file: {e}")
        except Exception as e:
            print(f"Error receiving data: {e}")
            break
        time.sleep(0.1)


def main():
    """Main function to run the command-line interface."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    print("DOG Command Line Interface")
    print("Type 'help' for assistance.")

    while True:
        try:
            command = input("> ").split()
            if not command:
                continue

            cmd = command[0].lower()

            if cmd == "help":
                help_command(command[1:])
            elif cmd == "start":
                start_command(command[1:])
            elif cmd == "stop":
                stop_command(command[1:])
            elif cmd == "display":
                display_command(command[1:])
            elif cmd == "send":
                send_command(command[1:])
            elif cmd == "write":
                write_command(command[1:])
            elif cmd == "exit":
                stop_command([])
                cleanup_resources()
                sys.exit(0)
            else:
                print(f"Unknown command: {cmd}")

        except EOFError:
            print("\nEOF received. Exiting.")
            break
        except KeyboardInterrupt:
            print("\nInterrupted. Exiting.")
            break
        except Exception as e:
            print(f"An unexpected error occurred: {e}")


if __name__ == "__main__":
    main()

