import signal
import sys
import time

import smbus2
from adafruit_tsl2561 import TSL2561
from gpiozero import PWMOutputDevice

# --- Configuration -----------------------------------------------------------
I2C_BUS = 1
TSL2561_ADDR = 0x29
LED_PIN = 18
PWM_FREQ = 1000          # Hz
INTEGRATION_TIME = 0.402  # 402 ms (TSL2561.INTEGRATIONTIME_402MS)
UPDATE_INTERVAL = 1.0    # seconds

# --- Globals for cleanup -----------------------------------------------------
_i2c_bus = None
_sensor = None
_led = None
_running = True


def _cleanup(signum=None, frame=None):
    """Stop PWM, release sensor, close I2C bus on any exit path."""
    global _running, _i2c_bus, _sensor, _led
    _running = False

    if _led is not None:
        try:
            _led.close()
        except Exception:
            pass
        _led = None

    if _sensor is not None:
        try:
            _sensor.deinit()
        except Exception:
            pass
        _sensor = None

    if _i2c_bus is not None:
        try:
            _i2c_bus.close()
        except Exception:
            pass
        _i2c_bus = None

    if signum is not None:
        sys.exit(0)


def _init_i2c():
    """Open the I2C bus; return bus handle or None on failure."""
    try:
        return smbus2.SMBus(I2C_BUS)
    except FileNotFoundError:
        print(f"Error: I2C bus {I2C_BUS} not found. Enable I2C with 'sudo raspi-config'.")
        return None
    except PermissionError:
        print(f"Error: Permission denied on I2C bus {I2C_BUS}. Run as root or add user to 'i2c' group.")
        return None
    except OSError as exc:
        print(f"Error: Cannot open I2C bus {I2C_BUS}: {exc}")
        return None


def _init_sensor(bus):
    """Initialize the TSL2561; return sensor object or None on failure."""
    try:
        sensor = TSL2561(bus, address=TSL2561_ADDR)
        sensor.integration_time = TSL2561.INTEGRATIONTIME_402MS
        sensor.gain = TSL2561.GAIN_AUTO
        sensor.enabled = True
        return sensor
    except ValueError as exc:
        print(f"Error: TSL2561 not detected at 0x{TSL2561_ADDR:02X} on bus {I2C_BUS}: {exc}")
        return None
    except OSError as exc:
        print(f"Error: I2C communication failure while initializing TSL2561: {exc}")
        return None
    except Exception as exc:
        print(f"Error: Unexpected failure initializing TSL2561: {exc}")
        return None


def _init_led():
    """Initialize PWM on GPIO18; return PWMOutputDevice or None on failure."""
    try:
        return PWMOutputDevice(LED_PIN, frequency=PWM_FREQ, initial_value=0)
    except Exception as exc:
        print(f"Error: Failed to initialize PWM on GPIO{LED_PIN}: {exc}")
        return None


def _read_lux(sensor):
    """Return lux reading or None on I2C/sensor error."""
    try:
        return sensor.lux
    except OSError as exc:
        print(f"Warning: I2C read error from TSL2561: {exc}")
        return None
    except Exception as exc:
        print(f"Warning: Unexpected error reading lux: {exc}")
        return None


def _set_brightness(led, lux):
    """Map lux to 0-100% duty cycle and apply it."""
    if lux is None:
        led.value = 0
        return
    brightness = min(100.0, max(0.0, lux)) / 100.0
    led.value = brightness


def main():
