import RPi.GPIO as GPIO
import time
import signal
import sys

# Constants for GPIO pins (BCM numbering)
DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21

# Constants for start and end signals
START_SIGNAL = [1, 0, 1, 1, 1, 0, 1, 1]
END_SIGNAL = [1, 1, 1, 1, 1, 1, 1, 1]

# Transmit delay (seconds)
TRANSMIT_DELAY = 0.0005

# Reception timeout (seconds)
RECEPTION_TIMEOUT = 1

# Global flag for graceful shutdown
_running = True


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def setup_gpio():
    """Initialize GPIO pins for both transmission and reception."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)

    for pin in (DATA_OUT_PIN, TIMER_OUT_PIN, DATA_IN_PIN, TIMER_IN_PIN):
        try:
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
        except Exception as e:
            print(f"Error setting up GPIO pin {pin}: {e}", file=sys.stderr)
            GPIO.cleanup()
            sys.exit(1)


def send_signal(signal):
    """Send a list of bits (0 or 1) over the GPIO pins."""
    for bit in signal:
        if not _running:
            return False
        GPIO.output(DATA_OUT_PIN, bit)
        GPIO.output(TIMER_OUT_PIN, 1)
        time.sleep(TRANSMIT_DELAY)
        GPIO.output(TIMER_OUT_PIN, 0)

    return True


def receive_signal(timeout=RECEPTION_TIMEOUT):
    """Receive a list of bits (0 or 1) from the GPIO pins, returning None on timeout."""
    received_signal = []
    start_time = time.time()

    while _running:
        if time.time() - start_time > timeout:
            print("Error: Reception timeout.", file=sys.stderr)
            return None

        # Wait for TIMER_IN_PIN to go HIGH (start of bit)
        while GPIO.input(TIMER_IN_PIN) == 0:
            if not _running:
                return None
            if time.time() - start_time > timeout:
                return None

        received_signal.append(GPIO.input(DATA_IN_PIN))

        # Wait for TIMER_IN_PIN to go LOW (end of bit)
        while GPIO.input(TIMER_IN_PIN) == 1:
            if not _running:
                return None
            if time.time() - start_time > timeout:
                return None

    return None


def transmit_data(data):
    """Transmit data by sending the start signal, data, and end signal."""
    if not send_signal(START_SIGNAL):
        return False
    if not send_signal(data):
        return False
    return send_signal(END_SIGNAL)


def receive_data():
    """Receive data by waiting for the start signal, then reading the payload."""
    received_start = receive_signal()
    if received_start is None or received_start != START_SIGNAL:
        print("Error: Invalid start signal received.", file=sys.stderr)
        return None

    received_data = []
    while _running:
        received_bit = receive_signal()
        if received_bit is None:
            print("Error: Incomplete data reception.", file=sys.stderr)
            return None
        if received_bit == END_SIGNAL:
            break
        received_data.append(received_bit)

    return received_data


def cleanup_gpio():
    """Clean up GPIO resources."""
    GPIO.cleanup()


def main():
    """Main function to demonstrate the transmit/receive protocol."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        setup_gpio()

        # Example data to transmit (list of lists)
        example_data = [[0, 1, 0, 1], [1, 0, 1, 0]]

        # Transmit the data
        if transmit_data(example_data):
            print("Data transmitted successfully.")
        else:
            print("Error: Data transmission failed.", file=sys.stderr)

        # Receive the data
        received_data = receive_data()
        if received_data is not None:
            print("Received data:", received_data)
        else:
            print("Error: Data reception failed.", file=sys.stderr)

    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
    finally:
        cleanup_gpio()


if __name__ == "__main__":
    main()

