import signal
import sys
import time
import logging
import zmq

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)


class PIDHandler:
    """
    A PID controller handler that manages error outputs, ZeroMQ communication,
    and a watchdog timer.
    """

    def __init__(self, logger, pwm_pin=12, err_pin=10,
                 pwm_frequency=1000, watchdog_timeout=20):
        self.logger = logger
        self.pwm_pin = pwm_pin
        self.err_pin = err_pin
        self.pwm_frequency = pwm_frequency
        self.watchdog_timeout = watchdog_timeout

        self.pwm = None
        self.err_state = False
        self.global_err_state = False
        self.last_msg = time.time()
        self.subscriptions = []
        self.sub_handlers = []
        self.context = None
        self.socket = None
        self._initialized = False

        if GPIO is not None:
            try:
                GPIO.setmode(GPIO.BOARD)
                GPIO.setwarnings(False)
                self._setup_gpio()
                self._initialized = True
                self.logger.info("GPIO initialized successfully.")
            except Exception as e:
                self.logger.error(f"Failed to initialize GPIO: {e}")
                self._initialized = False
        else:
            self.logger.warning("RPi.GPIO not available; running in mock mode.")

    def _setup_gpio(self):
        try:
            GPIO.setup(self.pwm_pin, GPIO.OUT)
            GPIO.setup(self.err_pin, GPIO.OUT)
            self.pwm = GPIO.PWM(self.pwm_pin, self.pwm_frequency)
            self.pwm.start(0)
            self.set_error_output(False)
        except Exception as e:
            self.logger.error(f"Error setting up GPIO pins: {e}")
            raise

    def _cleanup_gpio(self):
        if self._initialized and GPIO is not None:
            try:
                if self.pwm is not None:
                    self.pwm.stop()
            except Exception as e:
                self.logger.error(f"Error stopping PWM: {e}")
            try:
                GPIO.cleanup()
                self.logger.info("GPIO cleaned up.")
            except Exception as e:
                self.logger.error(f"Error cleaning up GPIO: {e}")

    def _init_zmq(self):
        try:
            self.context = zmq.Context.instance()
            self.socket = self.context.socket(zmq.SUB)
            self.socket.setsockopt_string(zmq.SUBSCRIBE, '')
            self.socket.connect('ipc:///tmp/pid_handler.ipc')
            self.logger.info("ZMQ socket connected.")
        except Exception as e:
            self.logger.error(f"Failed to initialize ZMQ: {e}")
            raise

    def _close_zmq(self):
        if self.socket is not None:
            try:
                self.socket.close(linger=0)
            except Exception as e:
                self.logger.error(f"Error closing ZMQ socket: {e}")
            self.socket = None
        if self.context is not None:
            try:
                self.context.term()
            except Exception as e:
                self.logger.error(f"Error terminating ZMQ context: {e}")
            self.context = None

    def update_error_output(self):
        if self._initialized and GPIO is not None:
            try:
                GPIO.output(self.err_pin, self.global_err_state)
            except Exception as e:
                self.logger.error(f"Error updating error output: {e}")
        else:
            self.logger.warning("GPIO not initialized; cannot update error output.")

    def set_error_output(self, state):
        self.err_state = state
        self.global_err_state = state
        self.update_error_output()

    def handle_message(self, channel, handler, **kwargs):
        if self.socket is None:
            self.logger.warning("ZMQ socket not initialized; cannot handle message.")
            return
        try:
            self.last_msg = time.time()
            self.logger.debug(f"Received message on channel {channel}: {kwargs}")
            for callback in self.subscriptions:
                callback(channel=channel, handler=handler, **kwargs)
        except zmq.ZMQError as e:
            self.logger.error(f"ZMQ error handling message: {e}")
        except Exception as e:
            self.logger.error(f"Error handling message: {e}")

    def check_watchdog(self):
        if time.time() - self.last_msg > self.watchdog_timeout:
            self.logger.warning("Watchdog timeout triggered!")
            self.set_error_output(True)

    def run(self):
        if self.socket is None:
            self._init_zmq()

        try:
            while True:
                self.check_watchdog()
                try:
                    self.socket.recv(flags=zmq.NOBLOCK)
                except zmq.Again:
                    pass
                except zmq.ZMQError as e:
                    self.logger.error(f"ZMQ error in non-blocking recv: {e}")
                time.sleep(0.1)
        except KeyboardInterrupt:
            self.logger.info("Exiting PID handler loop.")
        finally:
            self._close_zmq()
            self._cleanup_gpio()

    def cleanup(self):
        self._close_zmq()
        self._cleanup_gpio()


def signal_handler(signum, frame):
    logging.getLogger(__name__).info(f"Signal {signum} received, exiting.")
    if 'handler' in globals():
        handler.cleanup()
    sys.exit(0)


if __name__ == '__main__':
    handler = PIDHandler(logging.getLogger())
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    handler.run()

