# Raspberry Pi 5 Fingerprint Authentication Program
# Uses Adafruit Fingerprint sensor over I2C (SCL=GPIO3, SDA=GPIO2)

import time
import board
import busio
import adafruit_fingerprint


def main():
    # Initialize I2C bus on GPIO3 (SCL) and GPIO2 (SDA)
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return

    # Initialize the fingerprint sensor
    try:
        fingerprint_sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
    except Exception as e:
        print(f"Error initializing fingerprint sensor: {e}")
        i2c_bus.deinit()
        return

    # Main loop for continuous authentication
    try:
        while True:
            try:
                # Wait one second between authentication attempts
                time.sleep(1)

                # Acquire fingerprint image
                try:
                    image = fingerprint_sensor.get_image()
                except RuntimeError as e:
                    print(f"Sensor error (no finger or busy): {e}")
                    continue
                except ValueError as e:
                    print(f"I2C bus locked: {e}")
                    continue

                # Convert image to template
                try:
                    template = fingerprint_sensor.image_2_tz(1)
                except Exception as e:
                    print(f"Error converting image to template: {e}")
                    continue

                # Search the fingerprint database
                try:
                    result = fingerprint_sensor.finger_search(template)
                except Exception as e:
                    print(f"Error searching database: {e}")
                    continue

                # Check if a match was found
                if result[0] == adafruit_fingerprint.OK:
                    print("Access Granted")
                    print(f"Matched ID: {result[1]}, Confidence: {result[2]}")
                else:
                    print("Access Denied")

            except KeyboardInterrupt:
                print("\nExiting program...")
                break
            except Exception as e:
                print(f"An unexpected error occurred: {e}")
                continue

    finally:
        # Clean up resources
        print("Cleaning up...")
        try:
            i2c_bus.deinit()
        except Exception:
            pass
        print("Done.")


if __name__ == "__main__":
    main()

