import signal
import sys
import time

import RPi.GPIO as GPIO
from lib_tft144 import TFT144

WIDTH = 128
HEIGHT = 128


class TFTDisplay:
    """Manage a TFT144 display and its SPI/GPIO resources."""

    def __init__(self, spi_bus=0, spi_device=0,
                 dc_pin=8, rst_pin=18, led_pin=23,
                 orientation=90):
        self.spi_bus = spi_bus
        self.spi_device = spi_device
        self.dc_pin = dc_pin
        self.rst_pin = rst_pin
        self.led_pin = led_pin
        self.orientation = orientation
        self.spi = None
        self.tft = None
        self._initialized = False

    def _init_gpio(self):
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        for pin in (self.dc_pin, self.rst_pin, self.led_pin):
            GPIO.setup(pin, GPIO.OUT)
        GPIO.output(self.led_pin, GPIO.HIGH)

    def _init_tft(self):
        self.spi = GPIO.SPI(self.spi_bus, self.spi_device)
        self.tft = TFT144(
            self.spi,
            self.dc_pin,
            self.rst_pin,
            self.led_pin,
            orientation=self.orientation,
        )
        self._initialized = True

    def initialize(self):
        self._init_gpio()
        self._init_tft()
        atexit.register(self.cleanup)
        signal.signal(signal.SIGTERM, self._signal_handler)

    def _signal_handler(self, signum, frame):
        self.cleanup()
        sys.exit(0)

    def cleanup(self):
        if self._initialized:
            try:
                if self.spi is not None:
                    self.spi.close()
            except Exception:
                pass
            try:
                GPIO.cleanup()
            except Exception:
                pass
            self._initialized = False

    def display_text(self, text, font_num=1, color=(0, 0, 0)):
        try:
            self.tft.put_str(text, font_num=font_num, color=color)
        except Exception as e:
            print(f"Error displaying text: {e}")

    def clear_display(self, color=(255, 0, 0)):
        try:
            self.tft.clear_display(color)
        except Exception as e:
            print(f"Error clearing display: {e}")

    def display_character_set(self):
        posx = posy = 0
        for i in range(32, 128):
            try:
                self.tft.put_char(chr(i), posx, posy, 1, (0, 0, 0))
            except Exception as e:
                print(f"Error displaying character {i}: {e}")
            posx += self.tft.fontW
            if posx + self.tft.fontW > WIDTH:
                posx = 0
                posy += self.tft.fontH
        print("Done displaying character set (32-127)")

    def display_extended_charset(self):
        posx = posy = 0
        for i in range(1, 256):
            try:
                self.tft.put_char(chr(i), posx, posy, 3, (0, 0, 0))
            except Exception as e:
                print(f"Error displaying extended character {i}: {e}")
            posx += self.tft.fontW
            if posx + self.tft.fontW > WIDTH:
                posx = 0
                posy += self.tft.fontH
        print("Done displaying extended character set (1-255)")

    def display_phrase(self, phrase, font_num=1, color=(0, 0, 0)):
        try:
            self.tft.put_str(phrase, font_num=font_num, color=color)
        except Exception as e:
            print(f"Error displaying phrase: {e}")

    def display_color_cycle(self):
        colors = [(255, 0, 0), (0, 255, 0), (0, 0, 255), (255, 255, 0),
                  (255, 0, 255), (0, 255, 255)]
        while True:
            for color in colors:
                try:
                    self.tft.clear_display(color)
                except Exception as e:
                    print(f"Error clearing display: {e}")
                time.sleep(1)


def main():
    display = TFTDisplay()
    try:
        display.initialize()
        display.display_color_cycle()
    except KeyboardInterrupt:
        print("Exiting program")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        display.cleanup()


if __name__ == "__main__":
    main()

