    sys.exit(1)

PWM_PIN = 12
PWM_FREQ = 25000

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def cleanup():
    try:
        if 'pwm' in globals() and pwm is not None:
            pwm.ChangeDutyCycle(0)
            pwm.stop()
    except Exception:
        pass
    try:
        GPIO.cleanup()
    except Exception:
        pass

def main():
    global pwm
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)

    pwm = None
    try:
        GPIO.setup(PWM_PIN, GPIO.OUT)
        pwm = GPIO.PWM(PWM_PIN, PWM_FREQ)
        pwm.start(0)
    except Exception as e:
        print(f"Warning: Could not initialize hardware PWM on GPIO{PWM_PIN} at {PWM_FREQ} Hz: {e}")
        print("Falling back to software PWM.")
        try:
            GPIO.setup(PWM_PIN, GPIO.OUT)
            pwm = GPIO.PWM(PWM_PIN, PWM_FREQ)
            pwm.start(0)
        except Exception as e2:
            print(f"Error: Could not initialize PWM at all: {e2}")
            GPIO.cleanup()
            sys.exit(1)

    try:
        while _running:
            try:
                user_input = input("Enter fan speed (0-100, or 'q' to quit): ").strip()
            except EOFError:
                break

            if user_input.lower() == 'q':
                break

            try:
                fan_speed = float(user_input)
            except ValueError:
                print("Invalid input. Please enter a number between 0 and 100, or 'q' to quit.")
                continue

            if not 0 <= fan_speed <= 100:
                print("Fan speed must be between 0 and 100.")
                continue

            try:
                pwm.ChangeDutyCycle(fan_speed)
            except Exception as e:
                print(f"Error setting PWM duty cycle: {e}")

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

