# Program: Simple LED Blink with Robust Error Handling
# Description: Blinks an LED connected to GPIO17 on a Raspberry Pi 3 Model B+.
#              Prints messages on/off transitions and handles KeyboardInterrupt
#              and initialization errors gracefully.

import time
import signal
import sys

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, BadPinFactory
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

LED_PIN = 17


def cleanup(led=None):
    """Turn off the LED and release resources."""
    if led is not None:
        try:
            led.off()
            led.close()
        except Exception:
            pass


def main():
    led = None
    try:
        led = LED(LED_PIN)
    except BadPinFactory:
        print("Error: No GPIO pin factory available. Are you running on a Raspberry Pi?")
        sys.exit(1)
    except GPIOZeroError as e:
        print(f"Error initializing LED on GPIO{LED_PIN}: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error during LED initialization: {e}")
        sys.exit(1)

    try:
        while True:
            led.on()
            print("LED is ON")
            time.sleep(1)

            led.off()
            print("LED is OFF")
            time.sleep(1)
    except KeyboardInterrupt:
        print("Program stopped. LED is OFF.")
    except Exception as e:
        print(f"An error occurred during the blink loop: {e}")
    finally:
        cleanup(led)


if __name__ == "__main__":
    main()

