#!/usr/bin/env python3
"""
Rainbow HAT binary counter.

Touchpad A (GPIO5) = bit 4 (MSB)
Touchpad B (GPIO6) = bit 2 (middle)
Touchpad C (GPIO12) = bit 1 (LSB)

Discrete LEDs: red (GPIO7), green (GPIO8), blue (GPIO8)
APA102: data GPIO10, clock GPIO11
Buzzer: GPIO13

Requires: rainbowhat, adafruit-circuitpython-apa102, adafruit-circuitpython-busio,
          adafruit-circuitpython-charlieplexed, adafruit-circuitpython-displayio.
"""

import signal
import sys
import time

import board
import busio
import digitalio
import adafruit_apa102.apa102 as apa102
from adafruit_charlieplexed import Charlieplexed
from rainbowhat import Touch, Display, LEDS, APA102

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
TOUCH_PINS = [board.D5, board.D6, board.D12]          # GPIO5, GPIO6, GPIO12
DISCRETE_PINS = (board.D7, board.D8, board.D8)        # red, green, blue
APA102_PINS = (board.D10, board.D11)                 # data, clock
BUZZER_PIN = board.D13

BIT_VALUES = [4, 2, 1]

# ---------------------------------------------------------------------------
# Globals (initialised in main)
# ---------------------------------------------------------------------------
bit_states = [False, False, False]
running = True

# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def cleanup(signum=None, frame=None):
    """Turn off everything and exit cleanly."""
    global running
    running = False
    try:
        if 'display' in globals() and display is not None:
            display.clear()
            display.show()
    except Exception as e:
        print(f"Error clearing display: {e}", file=sys.stderr)
    try:
        if 'leds' in globals() and leds is not None:
            leds.fill(0)
            leds.show()
    except Exception as e:
        print(f"Error clearing LEDs: {e}", file=sys.stderr)
    try:
        if 'apa102_strip' in globals() and apa102_strip is not None:
            apa102_strip.fill((0, 0, 0))
            apa102_strip.show()
    except Exception as e:
        print(f"Error clearing APA102: {e}", file=sys.stderr)
