    try:
        GPIO.output(LED_PIN, GPIO.LOW)
    except Exception as e:
        print(f"Error turning LED off: {e}")
        raise


def cleanup_gpio():
    """Clean up GPIO resources by resetting the pin and releasing the mode."""
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
        GPIO.cleanup()
    except Exception as e:
