# Program: Simple LED Blink
# Description: Blinks an LED connected to GPIO17 (BCM numbering) on a Raspberry Pi 3 Model B+
# at 1 Hz (1 s on, 1 s off) using gpiozero.

import time
import sys

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, BadPinFactory
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(0)

LED_PIN = 17


def main():
    """Blink the LED on GPIO17 at 1 Hz until interrupted."""
    led = None
    try:
        # Attempt to create the LED object; this raises BadPinFactory if no usable
        # pin factory is available (e.g., running on a non-Pi platform).
        try:
            led = LED(LED_PIN)
        except BadPinFactory as exc:
            print(f"Error: No usable pin factory available. {exc}", file=sys.stderr)
            sys.exit(0)
        except GPIOZeroError as exc:
            print(f"Error: Failed to initialize GPIO{LED_PIN}: {exc}", file=sys.stderr)
            sys.exit(0)

        # Use the LED object's built-in blink method with background set to False
        # so that the main thread blocks on the on/off cycle.
        led.blink(on_time=1.0, off_time=1.0, background=False)

    except KeyboardInterrupt:
        print("\nProgram stopped by user.")

    finally:
        # Ensure the LED is turned off and the pin is released on every exit path.
        if led is not None:
            try:
                led.close()
            except Exception:
                pass


if __name__ == "__main__":
    main()

