import time
import signal
import requests
from gpiozero import Button

# Configuration
BUTTON_PIN = 17
SERVER_URL = 'http://localhost:8000/quality'
PART_ID = 'PART-204'
POLL_INTERVAL = 2  # seconds

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False

def generate_quality_report(passed: bool, defect_count: int) -> dict:
    """Generates a quality report dictionary."""
    return {
        'part_id': PART_ID,
        'passed': passed,
        'defect_count': defect_count
    }

def transmit_quality_report(report: dict) -> None:
    """Sends the quality report to the server and prints the status code."""
    try:
        response = requests.post(
            SERVER_URL,
            json=report,
            headers={'Content-Type': 'application/json'},
            timeout=10
        )
        print(f'Server response: {response.status_code}')
    except requests.exceptions.Timeout:
        print('Error: Request timed out while communicating with the server.')
    except requests.exceptions.ConnectionError as e:
        print(f'Error: Could not connect to the server. {e}')
    except requests.exceptions.HTTPError as e:
        print(f'Error: Server returned an HTTP error. {e}')
    except requests.exceptions.RequestException as e:
        print(f'Error: Failed to send report. {e}')

def main() -> None:
    """Main function to monitor the button and transmit quality reports."""
    global _running

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize the button with internal pull-up and active-low logic
    try:
        button = Button(BUTTON_PIN, pull_up=True, bounce_time=None)
    except Exception as e:
        print(f'Error: Failed to initialize GPIO{BUTTON_PIN}. {e}')
        return

    print(f'Monitoring button on GPIO{BUTTON_PIN}. Press Ctrl+C to exit.')

    try:
        while _running:
            if button.is_pressed:
                report = generate_quality_report(passed=False, defect_count=1)
            else:
                report = generate_quality_report(passed=True, defect_count=0)

            transmit_quality_report(report)
            time.sleep(POLL_INTERVAL)

    except Exception as e:
        print(f'Unexpected error: {e}')
    finally:
        # gpiozero handles its own cleanup on garbage collection,
        # but we explicitly close the device for immediate resource release.
        try:
            button.close()
        except Exception:
            pass
        print('GPIO cleanup completed.')

if __name__ == '__main__':
    main()

