import argparse
import json
import logging
import signal
import sys
import time
from collections import deque
from typing import Dict, Optional, Tuple

import numpy as np
import tflite_runtime.interpreter as tflite

try:
    import smbus2 as smbus
except ImportError:
    import smbus

try:
    import ina219
except ImportError:
    ina219 = None

try:
    import waveshare_vibration as waveshare_vibration
except ImportError:
    waveshare_vibration = None


class SensorReadError(Exception):
    pass


class ConfigurationError(Exception):
    pass


class VibrationSensor:
    def __init__(self, bus_num: int, addr: int, simulate: bool = False):
        self.bus_num = bus_num
        self.addr = addr
        self.simulate = simulate
        self.bus = None
        self.scale_factor = 1.0
        self.x_readings = deque(maxlen=5)
        self.y_readings = deque(maxlen=5)
        self.z_readings = deque(maxlen=5)
        self.current_readings = deque(maxlen=5)
        self.running = True

    def _init_hardware(self):
        if self.simulate:
            return
        try:
            self.bus = smbus.SMBus(self.bus_num)
        except Exception as e:
            raise SensorReadError(f"Failed to open I2C bus {self.bus_num}: {e}")

    def _read_vibration(self) -> Tuple[float, float, float]:
        if self.simulate:
            return (np.random.uniform(-100, 100) / 1000.0,
                    np.random.uniform(-100, 100) / 1000.0,
                    np.random.uniform(-100, 100) / 1000.0)
        try:
            x, y, z = self.sensor.get_x_y_z()
            return (x / 1000.0, y / 1000.0, z / 1000.0)
        except Exception as e:
            raise SensorReadError(f"Failed to read vibration sensor: {e}")

    def _read_current(self) -> float:
        if self.simulate:
            return np.random.uniform(0.0, 10.0)
        try:
            return self.ina.read_current()
        except Exception as e:
            raise SensorReadError(f"Failed to read current sensor: {e}")

    def read_data(self) -> Tuple[float, float, float, float]:
        try:
            self._init_hardware()
            self.sensor = waveshare_vibration.VibrationSensor(
                self.bus, addr=self.addr
            )
            self.ina = ina219.INA219(
                self.bus, busnum=self.bus_num, address=self.addr
            )
            self.ina.shunt_resistance = 0.1
            self.scale_factor = 1.0

            x, y, z = self._read_vibration()
            current = self._read_current()

            self.x_readings.append(x)
            self.y_readings.append(y)
            self.z_readings.append(z)
            self.current_readings.append(current)

            avg_x = sum(self.x_readings) / len(self.x_readings)
            avg_y = sum(self.y_readings) / len(self.y_readings)
            avg_z = sum(self.z_readings) / len(self.z_readings)
            avg_current = sum(self.current_readings) / len(self.current_readings)

            return (avg_x, avg_y, avg_z, avg_current)
        except SensorReadError as e:
            logging.error(f"Sensor read error: {e}")
            if self.bus:
                try:
                    self.bus.close()
                except Exception:
                    pass
                self.bus = None
            return (0.0, 0.0, 0.0, 0.0)
        except Exception as e:
            logging.error(f"Unexpected error reading data: {e}")
            if self.bus:
                try:
                    self.bus.close()
                except Exception:
                    pass
                self.bus = None
            return (0.0, 0.0, 0.0, 0.0)

    def stop(self):
        self.running = False


def load_config(config_file: str) -> Dict[str, str]:
    try:
        with open(config_file, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        logging.warning(f"Configuration file not found: {config_file}. Using defaults.")
        return {}
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in configuration file: {e}. Using defaults.")
        return {}


def apply_config(config: Dict[str, str], defaults: Dict[str, str]) -> Dict[str, str]:
    applied = defaults.copy()
    for key, value in config.items():
        if key in applied:
            applied[key] = value
    return applied


def main():
    parser = argparse.ArgumentParser(description="Vibration and current monitoring with TFLite inference.")
    parser.add_argument("--bus_num", type=int, default=1, help="I2C bus number (default: 1)")
    parser.add_argument("--sensor_addr", type=int, default=0x68, help="I2C address of the sensor (default: 0x68)")
    parser.add_argument("--threshold", type=float, default=0.8, help="Failure probability threshold (default: 0.8)")
    parser.add_argument("--endpoint", type=str, default="http://example.com/alerts", help="HTTP endpoint for alerts (default: http://example.com/alerts)")
    parser.add_argument("--model_path", type=str, default="model.tflite", help="Path to the TensorFlow Lite model (default: model.tflite)")
    parser.add_argument("--log_file", type=str, default="vibration_monitor.log", help="Path to the log file (default: vibration_monitor.log)")
    parser.add_argument("--config_file", type=str, default=None, help="Path to the JSON configuration file")
    parser.add_argument("--simulate", action="store_true", help="Simulate sensor data instead of reading from hardware")
    args = parser.parse_args()

    defaults = {
        "bus_num": 1,
        "sensor_addr": 0x68,
        "threshold": 0.8,
        "endpoint": "http://example.com/alerts",
        "model_path": "model.tflite",
        "log_file": "vibration_monitor.log",
        "simulate": False,
    }

    if args.config_file:
        config = load_config(args.config_file)
        applied = apply_config(config, defaults)
        args.bus_num = int(applied.get("bus_num", args.bus_num))
        args.sensor_addr = int(applied.get("sensor_addr", args.sensor_addr))
        args.threshold = float(applied.get("threshold", args.threshold))
        args.endpoint = applied.get("endpoint", args.endpoint)
        args.model_path = applied.get("model_path", args.model_path)
        args.log_file = applied.get("log_file", args.log_file)
        args.simulate = bool(applied.get("simulate", args.simulate))
    else:
        args.simulate = bool(defaults.get("simulate", args.simulate))

    logging.basicConfig(
        filename=args.log_file,
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s'
    )
    logging.info("Starting vibration monitoring system")

    sensor = VibrationSensor(args.bus_num, args.sensor_addr, args.simulate)

    def signal_handler(sig, frame):
        logging.info("Received SIGINT, shutting down...")
        sensor.stop()

    signal.signal(signal.SIGINT, signal_handler)

    try:
        interpreter = tflite.Interpreter(model_path=args.model_path)
        interpreter.allocate_tensors()
        input_details = interpreter.get_input_details()
        output_details = interpreter.get_output_details()

        while sensor.running:
            x, y, z, current = sensor.read_data()

            input_data = np.array([[x, y, z, current]], dtype=np.float32)
            interpreter.set_tensor(input_details[0]['index'], input_data)
            interpreter.invoke()
            output_data = interpreter.get_tensor(output_details[0]['index'])
            failure_probability = output_data[0][0]

            logging.info(f"X: {x:.3f}, Y: {y:.3f}, Z: {z:.3f}, Current: {current:.3f}, Failure Probability: {failure_probability:.3f}")

            if failure_probability > args.threshold:
                logging.warning(f"Potential failure detected! Probability: {failure_probability:.3f}")
                try:
                    import requests
                    requests.post(args.endpoint, json={"failure_probability": failure_probability}, timeout=5)
                except requests.exceptions.RequestException as e:
                    logging.error(f"Failed to send alert: {e}")

            time.sleep(1)

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        sensor.stop()
        logging.info("Vibration monitoring system stopped.")


if __name__ == "__main__":
    main()

