    sys.exit(1)

# --- Configuration ---
BASE_SERVO_PIN = 17
SHOULDER_SERVO_PIN = 27
GRIPPER_SERVO_PIN = 22

I2C_BUS = 1
TCS34725_ADDRESS = 0x29

PWM_FREQUENCY = 50

# --- Logging Setup ---
logging.basicConfig(
    filename='robotic_arm.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# --- Global State for Cleanup ---
_running = True
_servos = []
_i2c = None


def signal_handler(signum, frame):
    global _running
    _running = False
    logging.info(f"Signal {signum} received, shutting down.")


def initialize_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(BASE_SERVO_PIN, GPIO.OUT)
    GPIO.setup(SHOULDER_SERVO_PIN, GPIO.OUT)
    GPIO.setup(GRIPPER_SERVO_PIN, GPIO.OUT)


def create_servo(pin):
    try:
        return GPIO.PWM(pin, PWM_FREQUENCY)
    except Exception as e:
        logging.error(f"Failed to create PWM on pin {pin}: {e}")
        return None


def set_servo_angle(servo, angle):
    if servo is None:
