        return
    try:
        if not (0 <= angle <= 180):
            raise ValueError(f"Angle {angle} out of range (0-180)")
        duty = (angle / 18.0) + 2.5
        servo.start(0)
        servo.ChangeDutyCycle(duty)
        time.sleep(0.02)
        servo.ChangeDutyCycle(0)
        servo.stop()
    except Exception as e:
        logging.error(f"Error setting servo angle: {e}")


