    global _i2c
    try:
        _i2c = I2C(I2C_BUS)
        sensor = TCS34725(_i2c, address=TCS34725_ADDRESS)
        sensor.enable()
        sensor.set_integration_time(TCS34725.INTEGRATIONTIME_200MS)
        sensor.set_gain(TCS34725.GAIN_1X)
        sensor.set_color_filter(TCS34725.COLOR_FILTER_DISABLE)
