            s.stop()
        except Exception:
            pass
    _servos = []
    try:
        GPIO.cleanup()
    except Exception:
        pass
    if _i2c is not None:
        try:
            _i2c.deinit()
        except Exception:
            pass
        _i2c = None
    logging.info("GPIO and I2C resources released.")


def main():
    global _servos
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        initialize_gpio()
        _servos = [create_servo(BASE_SERVO_PIN),
                   create_servo(SHOULDER_SERVO_PIN),
                   create_servo(GRIPPER_SERVO_PIN)]

        color_sensor = initialize_color_sensor()

        if not _running:
            return

        color = read_color(color_sensor)
        weight = read_weight()

        if not _running:
            return

        logging.info(f"Color: {color}, Weight: {weight:.2f}g")
        sort_object(color, weight)

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

