import time
import signal
import sys
import logging
from PIL import Image
import smbus2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
I2C_BUS = 1
TCS34725_ADDRESS = 0x29
INTEGRATION_TIME_50MS = 0x00
GAIN_4X = 0x10
ENABLE_POWERON = 0x01
ENABLE_AEN = 0x02
ENABLE_PON = 0x01

running = True

def signal_handler(sig, frame):
    global running
    running = False

def initialize_i2c():
    try:
        return smbus2.SMBus(I2C_BUS)
    except Exception as e:
        logging.error(f"Error initializing I2C bus: {e}")
        return None

def initialize_sensor(bus):
    try:
        bus.write_byte_data(TCS34725_ADDRESS, 0x80, INTEGRATION_TIME_50MS | GAIN_4X)
        bus.write_byte_data(TCS34725_ADDRESS, 0x81, ENABLE_AEN | ENABLE_PON)
        logging.info("TCS34725 sensor initialized successfully.")
        return True
    except Exception as e:
        logging.error(f"Error initializing TCS34725 sensor: {e}")
        return False

def read_color_data(bus):
    try:
        data = bus.read_i2c_block_data(TCS34725_ADDRESS, 0x8C, 4)
        r = ((data[1] & 0x0F) << 8) | data[0]
        g = ((data[3] & 0x0F) << 8) | data[2]
        b = ((data[5] & 0x0F) << 8) | data[4]
        c = ((data[7] & 0x0F) << 8) | data[6]
        return r, g, b, c
    except Exception as e:
        logging.error(f"Error reading color data: {e}")
        return 0, 0, 0, 0

def get_dominant_color(image_path):
    try:
        image = Image.open(image_path).convert('RGB')
        image = image.resize((100, 100))
        pixels = image.load()
        width, height = image.size
        color_counts = {}
        for x in range(width):
            for y in range(height):
                color = pixels[x, y]
                color_counts[color] = color_counts.get(color, 0) + 1
        dominant_color = max(color_counts, key=color_counts.get)
        return dominant_color
    except FileNotFoundError:
        logging.error(f"Image file not found: {image_path}")
        return (0, 0, 0)
    except Exception as e:
        logging.error(f"Error processing image: {e}")
        return (0, 0, 0)

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    bus = initialize_i2c()
    if bus is None:
        sys.exit(1)

    if not initialize_sensor(bus):
        bus.close()
        sys.exit(1)

    try:
        while running:
            red, green, blue, clear = read_color_data(bus)
            print(f"Raw Sensor Data - Red: {red}, Green: {green}, Blue: {blue}, Clear: {clear}")

            dominant_color = get_dominant_color("image.jpg")
            print(f"Dominant Color in image.jpg: {dominant_color}")

            time.sleep(1)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        bus.close()
        logging.info("I2C bus deinitialized.")

if __name__ == "__main__":
    main()

