import time
import sys

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, GPIOZeroWarning
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

LED_PIN = 17
MOISTURE_THRESHOLD = 30
INITIAL_MOISTURE = 50
MOISTURE_DECREMENT = 1
WATERING_INTERVAL = 2


def main():
    led = None
    try:
        led = LED(LED_PIN)
    except GPIOZeroError as e:
        print(f"Error initializing LED on BCM pin {LED_PIN}: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error initializing LED: {e}")
        sys.exit(1)

    moisture = INITIAL_MOISTURE

    try:
        while True:
            print(f"Soil Moisture: {moisture}")

            if moisture < MOISTURE_THRESHOLD:
                print("Watering started!")
                led.on()
                time.sleep(WATERING_INTERVAL)
                moisture += MOISTURE_DECREMENT
                if moisture > MOISTURE_THRESHOLD:
                    print("Watering stopped!")
                    led.off()
            else:
                moisture -= MOISTURE_DECREMENT
                if moisture < 0:
                    moisture = INITIAL_MOISTURE
                    print("Simulating rain! Moisture reset to initial value.")

            time.sleep(WATERING_INTERVAL)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        if led is not None:
            led.off()
            led.close()
        print("Program finished.")


if __name__ == "__main__":
    main()

