import random
import time
import signal
import sys

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.")
    sys.exit(1)

PUMP_PIN = 17
MOISTURE_THRESHOLD = 30
ITERATIONS = 5
DELAY_SECONDS = 2

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_moisture():
    return random.randint(0, 100)

def control_pump(moisture_level):
    if moisture_level < MOISTURE_THRESHOLD:
        GPIO.output(PUMP_PIN, GPIO.HIGH)
        return "ON (moisture too low)"
    else:
        GPIO.output(PUMP_PIN, GPIO.LOW)
        return "OFF (moisture adequate)"

def cleanup():
    try:
        GPIO.output(PUMP_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PUMP_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO initialization error: {e}")
        sys.exit(1)

    try:
        for i in range(1, ITERATIONS + 1):
            if not _running:
                break
            moisture = read_moisture()
            state = control_pump(moisture)
            print(f"Reading {i}/{ITERATIONS}: Moisture = {moisture}%, Pump {state}")
            time.sleep(DELAY_SECONDS)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

