    """Turn the LED on when light_level is below 50 %, off otherwise."""
    if light_level < 50:
        led.on()
        print("LED ON: Light level too low")
    else:
        led.off()
        print("LED OFF: Light level adequate")


def run_light_control(led, cycles=CYCLES, delay=DELAY_SECONDS):
    """Run the light-control simulation for the configured number of cycles."""
    for i in range(cycles):
        light_level = read_light_level()
        print(f"Cycle {i + 1}/{cycles}: Light level: {light_level}%")
        control_led(led, light_level)
        if i < cycles - 1:
            time.sleep(delay)


