import RPi.GPIO as GPIO
import time
import datetime
import sys

# BCM pin connected to the PIR sensor output (HC-SR501)
PIR_PIN = 4

# Feeding time windows (24-hour format)
FEEDING_WINDOWS = [(7, 8), (18, 19)]  # 07:00-08:00 and 18:00-19:00

# Debounce time in seconds between feeds
DEBOUNCE_TIME = 60

# Global variable to track the last feeding time
last_feeding_time = 0.0


def is_feeding_time(now):
    """Check if the current time is within the allowed feeding windows."""
    current_hour = now.hour
    return any(start <= current_hour < end for start, end in FEEDING_WINDOWS)


def setup_gpio():
    """Initialize GPIO settings for the PIR sensor."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PIR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)


def cleanup_gpio():
    """Clean up GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception:
        pass


def main():
    """Main function to monitor the PIR sensor and control the feeder."""
    global last_feeding_time

    setup_gpio()

    try:
        while True:
            try:
                motion_detected = GPIO.input(PIR_PIN)
            except Exception as e:
                print(f"Error reading GPIO pin: {e}")
                time.sleep(1)
                continue

            if motion_detected:
                now = datetime.datetime.now()
                print(f"Motion detected at {now.strftime('%Y-%m-%d %H:%M:%S')}")

                if is_feeding_time(now) and (time.time() - last_feeding_time) > DEBOUNCE_TIME:
                    print(f"Feeding initiated at {now.strftime('%Y-%m-%d %H:%M:%S')}")
                    # Code to trigger the feeder would go here
                    last_feeding_time = time.time()
                else:
                    print("Not feeding time or recently fed.")

            time.sleep(1)

    except KeyboardInterrupt:
        print("Exiting program...")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        cleanup_gpio()


if __name__ == "__main__":
    main()

