import time
import signal
import sys

try:
    import library.pi as lib
except ImportError:
    raise RuntimeError("library.pi module not found. Please install or verify the path.")


class MotorError(Exception):
    """Custom exception for motor-related errors."""
    pass


class Motor:
    """
    A class to control a DC motor via a DC motor driver (e.g. L298N) on a Raspberry Pi.
    Uses hardware PWM on a specified BCM pin.
    """

    def __init__(self, driver, pin=18, frequency=1000):
        """
        Initializes the Motor object.

        Args:
            driver (library.pi): The driver library instance.
            pin (int): The BCM pin number connected to the motor driver's PWM input.
            frequency (int): The PWM frequency in Hz.
        """
        if not isinstance(driver, lib.Pi):
            raise MotorError("Invalid driver instance provided. Expected a library.pi instance.")

        self.driver = driver
        self.pin = pin
        self.frequency = frequency
        self._pwm = None

        try:
            self.driver.set_pwm_frequency(self.pin, self.frequency)
            self.driver.set_pwm_dutycycle(self.pin, 0)
        except Exception as e:
            raise MotorError(f"Failed to initialize PWM on pin {self.pin}: {e}") from e

    def set_frequency(self, frequency):
        """
        Sets the PWM frequency.

        Args:
            frequency (int): The desired PWM frequency in Hz.
        """
        if not isinstance(frequency, int) or frequency <= 0:
            raise MotorError("Frequency must be a positive integer.")

        try:
            self.driver.set_pwm_frequency(self.pin, frequency)
            self.frequency = frequency
        except Exception as e:
            raise MotorError(f"Failed to set PWM frequency: {e}") from e

    def set_duty_cycle(self, duty_cycle):
        """
        Sets the PWM duty cycle.

        Args:
            duty_cycle (int): The desired duty cycle (0-255).
        """
        if not isinstance(duty_cycle, int) or not 0 <= duty_cycle <= 255:
            raise MotorError("Duty cycle must be an integer between 0 and 255.")

        try:
            self.driver.set_pwm_dutycycle(self.pin, duty_cycle)
        except Exception as e:
            raise MotorError(f"Failed to set PWM duty cycle: {e}") from e

    def stop(self):
        """Stops the motor by setting the duty cycle to 0."""
        try:
            self.driver.set_pwm_dutycycle(self.pin, 0)
        except Exception as e:
            raise MotorError(f"Failed to stop motor: {e}") from e

    def close(self):
        """Releases resources and stops the motor."""
        self.stop()

    def __del__(self):
        """Destructor to ensure the motor is stopped."""
        try:
            self.stop()
        except Exception:
            pass


def main():
    """Demonstrates basic usage of the Motor class."""
    driver = None
    motor = None

    def signal_handler(sig, frame):
        print("\nExiting...")
        if motor is not None:
            motor.close()
        if driver is not None:
            driver.close()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        driver = lib.Pi()
        motor = Motor(driver, pin=18, frequency=1000)

        print("Motor running at 50% duty cycle...")
        motor.set_duty_cycle(128)
        time.sleep(2)

        print("Stopping motor...")
        motor.stop()

    except MotorError as e:
        print(f"Motor error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if motor is not None:
            motor.close()
        if driver is not None:
            driver.close()


if __name__ == "__main__":
    main()

