import signal
import sys
import logging
import pymodbus
from pymodbus.client import ModbusSerialClient
from pymodbus.constants import Endian
from pymodbus.payload import BinaryPayloadDecoder
from pymodbus.exceptions import ModbusException

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class ModbusRTUDevice:
    """
    Represents a Modbus RTU device connected via UART on a Raspberry Pi.
    Provides methods for reading and writing holding registers with robust error handling.
    """

    def __init__(self, port='/dev/serial0', baudrate=115200, timeout=1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.client = None
        self.registers = {}
        self._running = True

    def connect(self):
        """Establishes a connection to the Modbus device."""
        try:
            self.client = ModbusSerialClient(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=8,
                parity='N',
                stopbits=1,
                timeout=self.timeout
            )
            if not self.client.connect():
                raise ConnectionError(f"Failed to open UART port {self.port}")
            logger.info(f"Connected to Modbus device on {self.port} at {self.baudrate} baud.")
            return True
        except Exception as e:
            logger.error(f"Error connecting to Modbus device: {e}")
            self.client = None
            return False

    def disconnect(self):
        """Closes the connection to the Modbus device."""
        if self.client:
            try:
                self.client.close()
                logger.info("Disconnected from Modbus device.")
            except Exception as e:
                logger.error(f"Error disconnecting from Modbus device: {e}")
            finally:
                self.client = None

    def _read_registers(self, address, count=2, slave=1):
        """Reads holding registers from the Modbus device."""
        if not self.client:
            logger.error("Modbus client not connected. Cannot read registers.")
            return None
        try:
            result = self.client.read_holding_registers(
                address=address,
                count=count,
                slave=slave
            )
            if result.isError():
                logger.error(f"Modbus error reading registers at address {address}: {result}")
                return None
            decoder = BinaryPayloadDecoder.fromRegisters(
                result.registers,
                byteorder=Endian.BIG,
                wordorder=Endian.BIG
            )
            return decoder.decode_16bit_uint(0)
        except ModbusException as e:
            logger.error(f"Modbus exception reading registers at address {address}: {e}")
            return None
        except Exception as e:
            logger.error(f"Unexpected error reading registers at address {address}: {e}")
            return None

    def _write_register(self, address, value, slave=1):
        """Writes a single holding register to the Modbus device."""
        if not self.client:
            logger.error("Modbus client not connected. Cannot write register.")
            return False
        try:
            result = self.client.write_holding_register(
                address=address,
                value=value,
                slave=slave
            )
            if result.isError():
                logger.error(f"Modbus error writing register at address {address}: {result}")
                return False
            return True
        except ModbusException as e:
            logger.error(f"Modbus exception writing register at address {address}: {e}")
            return False
        except Exception as e:
            logger.error(f"Unexpected error writing register at address {address}: {e}")
            return False

    def _write_registers(self, address, values, slave=1):
        """Writes multiple holding registers to the Modbus device."""
        if not self.client:
            logger.error("Modbus client not connected. Cannot write registers.")
            return False
        try:
            result = self.client.write_multiple_registers(
                address=address,
                values=values,
                slave=slave
            )
            if result.isError():
                logger.error(f"Modbus error writing registers at address {address}: {result}")
                return False
            return True
        except ModbusException as e:
            logger.error(f"Modbus exception writing registers at address {address}: {e}")
            return False
        except Exception as e:
            logger.error(f"Unexpected error writing registers at address {address}: {e}")
            return False

    def register_map(self, name, address, r_w='R'):
        """Registers a map entry for a specific register or group of registers."""
        self.registers[name] = {
            'R/W': r_w,
            'Register': address,
            'functioncode': 3 if r_w == 'R' else 6
        }
        logger.info(f"Registered map entry: {name} at register {address}, R/W: {r_w}")

    def read_register(self, name):
        """Reads the value of a registered register."""
        if name not in self.registers:
            logger.error(f"Register '{name}' not found in the register map.")
            return None
        addr = self.registers[name]['Register']
        count = 2 if self.registers[name]['R/W'] == 'R' else 1
        return self._read_registers(addr, count=count)

    def write_register(self, name, value):
        """Writes a value to a registered register."""
        if name not in self.registers:
            logger.error(f"Register '{name}' not found in the register map.")
            return False
        addr = self.registers[name]['Register']
        if self.registers[name]['R/W'] == 'R':
            logger.error(f"Register '{name}' is read-only and cannot be written to.")
            return False
        return self._write_register(addr, value)

    def write_registers(self, name, values):
        """Writes a list of values to a registered register range."""
        if name not in self.registers:
            logger.error(f"Register '{name}' not found in the register map.")
            return False
        addr = self.registers[name]['Register']
        if self.registers[name]['R/W'] == 'R':
            logger.error(f"Register '{name}' is read-only and cannot be written to.")
            return False
        return self._write_registers(addr, values)

    def cleanup(self):
        """Releases resources and disconnects from the Modbus device."""
        self.disconnect()


def main():
    device = ModbusRTUDevice(port='/dev/serial0', baudrate=115200, timeout=1.0)

    def signal_handler(sig, frame):
        logger.info("Signal received, shutting down...")
        device.cleanup()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not device.connect():
        logger.warning("Modbus device connection failed. Exiting gracefully.")
        device.cleanup()
        sys.exit(1)

    try:
        # Example register map for a servo motor controller
        device.register_map('servo_position', 0x0000, 'R')
        device.register_map('servo_speed', 0x0002, 'R')
        device.register_map('servo_power', 0x0004, 'W')

        # Read servo position
        pos = device.read_register('servo_position')
        if pos is not None:
            logger.info(f"Servo Position: {pos}")

        # Write servo power (1 = ON, 0 = OFF)
        if device.write_register('servo_power', 1):
            logger.info("Servo power set to ON.")

        # Write servo speed (1000 = max speed)
        if device.write_register('servo_speed', 1000):
            logger.info("Servo speed set to 1000.")

    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
    finally:
        device.cleanup()


if __name__ == "__main__":
    main()

