import time
import logging
import signal
import sys

try:
    from automation import Automation
except ImportError:
    logging.error("The 'automation' library is not installed. Install it with: pip install automation")
    sys.exit(0)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

DOOR_CLOSED = 1
DOOR_OPEN = 0


class GarageDoor:
    """
    Controls a garage door using a Raspberry Pi and a Pimoroni Automation HAT.

    Wiring / assumptions:
      - Magnetic reed switch wired to Automation HAT input channel 1 (GPIO26, BCM).
        HIGH (1) = door closed, LOW (0) = door open.
      - Relay output relay.one drives the garage-door opener solenoid.
    """

    def __init__(self, state_pin=1, relay_name="one", open_duration=0.5):
        self.state_pin = state_pin
        self.relay_name = relay_name
        self.open_duration = open_duration
        self._automation = None
        self._closed = False
        self._shutting_down = False

        try:
            self._automation = Automation()
        except Exception as exc:
            logging.error("Failed to initialize Automation HAT: %s", exc)
            raise

        try:
            self._automation.setup()
        except Exception as exc:
            logging.error("Automation HAT setup failed: %s", exc)
            raise

        try:
            self.relay = self._automation.get_relay(self.relay_name)
        except Exception as exc:
            logging.error("Failed to access relay '%s': %s", self.relay_name, exc)
            raise

        try:
            self.state_input = self._automation.get_input(self.state_pin)
        except Exception as exc:
            logging.error("Failed to access input %d: %s", self.state_pin, exc)
            raise

        logging.info(
            "GarageDoor initialized: state_pin=%d, relay=%s, open_duration=%.2fs",
            self.state_pin, self.relay_name, self.open_duration,
        )

    def _read_state(self):
        """Return DOOR_CLOSED or DOOR_OPEN, or None on error."""
        try:
            value = self.state_input.read()
        except Exception as exc:
            logging.error("Error reading state input %d: %s", self.state_pin, exc)
            return None

        if value is None:
            logging.error("State input %d returned None", self.state_pin)
            return None

        if value not in (0, 1):
            logging.error("Unexpected state value %r on input %d", value, self.state_pin)
            return None

        return value

    def _set_relay(self, should_be_on):
        """Energize or de-energize the relay, logging errors."""
        try:
            if should_be_on:
                self.relay.on()
                logging.info("Relay %s energized", self.relay_name)
            else:
                self.relay.off()
                logging.info("Relay %s de-energized", self.relay_name)
        except Exception as exc:
            logging.error("Error controlling relay %s: %s", self.relay_name, exc)

    def _open_door(self):
        logging.info("Opening garage door")
        self._set_relay(True)
        time.sleep(self.open_duration)
        self._set_relay(False)
        logging.info("Garage door opened")

    def _close_door(self):
        logging.info("Closing garage door")
        self._set_relay(True)
        time.sleep(self.open_duration)
        self._set_relay(False)
        logging.info("Garage door closed")

    def run(self):
        """Main control loop: monitor the reed switch and actuate the relay."""
        try:
            while not self._shutting_down:
                state = self._read_state()

                if state is None:
                    logging.warning("Skipping cycle due to read error")
                    time.sleep(1)
                    continue

                if state == DOOR_CLOSED and not self._closed:
                    self._close_door()
                    self._closed = True
                elif state == DOOR_OPEN and self._closed:
                    self._open_door()
                    self._closed = False

                time.sleep(1)

        except KeyboardInterrupt:
            logging.info("Program interrupted by user")
        except Exception as exc:
            logging.error("Unexpected error in main loop: %s", exc)
        finally:
            self.cleanup()

    def cleanup(self):
        """Ensure the relay is OFF and the Automation HAT is released."""
        if self._automation is not None:
            try:
                if hasattr(self, "relay") and self.relay is not None:
                    self.relay.off()
                    logging.info("Relay %s turned off during cleanup", self.relay_name)
            except Exception as exc:
                logging.error("Error turning off relay during cleanup: %s", exc)

            try:
                self._automation.cleanup()
                logging.info("Automation HAT cleanup completed")
            except Exception as exc:
                logging.error("Error during Automation HAT cleanup: %s", exc)


def _signal_handler(signum, frame, garage_door):
    logging.info("Signal %d received, shutting down", signum)
    garage_door._shutting_down = True


if __name__ == "__main__":
    garage_door = None
    try:
        garage_door = GarageDoor(state_pin=1, relay_name="one", open_duration=0.5)

        signal.signal(signal.SIGINT, lambda s, f: _signal_handler(s, f, garage_door))
        signal.signal(signal.SIGTERM, lambda s, f: _signal_handler(s, f, garage_door))

        garage_door.run()

    except Exception as exc:
        logging.error("Fatal error: %s", exc)
        if garage_door is not None:
            garage_door.cleanup()
        sys.exit(0)

