        except Exception as exc:
            logging.error("Error controlling relay %s: %s", self.relay_name, exc)

    def _open_door(self):
        logging.info("Opening garage door")
        self._set_relay(True)
        time.sleep(self.open_duration)
        self._set_relay(False)
        logging.info("Garage door opened")

    def _close_door(self):
        logging.info("Closing garage door")
        self._set_relay(True)
        time.sleep(self.open_duration)
        self._set_relay(False)
        logging.info("Garage door closed")

    def run(self):
        """Main control loop: monitor the reed switch and actuate the relay."""
        try:
            while not self._shutting_down:
                state = self._read_state()

                if state is None:
                    logging.warning("Skipping cycle due to read error")
                    time.sleep(1)
                    continue

                if state == DOOR_CLOSED and not self._closed:
                    self._close_door()
                    self._closed = True
                elif state == DOOR_OPEN and self._closed:
                    self._open_door()
                    self._closed = False

                time.sleep(1)

        except KeyboardInterrupt:
            logging.info("Program interrupted by user")
        except Exception as exc:
            logging.error("Unexpected error in main loop: %s", exc)
        finally:
            self.cleanup()

    def cleanup(self):
        """Ensure the relay is OFF and the Automation HAT is released."""
        if self._automation is not None:
            try:
                if hasattr(self, "relay") and self.relay is not None:
                    self.relay.off()
                    logging.info("Relay %s turned off during cleanup", self.relay_name)
            except Exception as exc:
                logging.error("Error turning off relay during cleanup: %s", exc)

            try:
                self._automation.cleanup()
                logging.info("Automation HAT cleanup completed")
            except Exception as exc:
                logging.error("Error during Automation HAT cleanup: %s", exc)


def _signal_handler(signum, frame, garage_door):
    logging.info("Signal %d received, shutting down", signum)
    garage_door._shutting_down = True


if __name__ == "__main__":
    garage_door = None
    try:
        garage_door = GarageDoor(state_pin=1, relay_name="one", open_duration=0.5)

        signal.signal(signal.SIGINT, lambda s, f: _signal_handler(s, f, garage_door))
        signal.signal(signal.SIGTERM, lambda s, f: _signal_handler(s, f, garage_door))

        garage_door.run()

    except Exception as exc:
        logging.error("Fatal error: %s", exc)
        if garage_door is not None:
            garage_door.cleanup()
        sys.exit(0)

