import time
import signal
import sys

try:
    from gpiozero import OutputDevice, PWMOutputDevice
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)


class Laser:
    """Controls a laser diode via a digital GPIO output."""

    def __init__(self, pin=17):
        self.pin = pin
        self._device = None
        try:
            self._device = OutputDevice(pin)
        except Exception as e:
            raise RuntimeError(f"Failed to initialize laser on GPIO{pin}: {e}") from e

    def on(self):
        if self._device is not None:
            self._device.on()

    def off(self):
        if self._device is not None:
            self._device.off()

    def close(self):
        if self._device is not None:
            self._device.close()
            self._device = None


class Aim:
    """Controls two servo motors (horizontal and vertical) and a laser."""

    def __init__(self, hp, vp, laser, ld=0.5, sd=0.1):
        self.hp = hp
        self.vp = vp
        self.laser = laser
        self.ld = ld
        self.sd = sd
        self._h_servo = None
        self._v_servo = None
        try:
            self._h_servo = PWMOutputDevice(18)
            self._v_servo = PWMOutputDevice(19)
        except Exception as e:
            raise RuntimeError(f"Failed to initialize servo PWM on GPIO18/19: {e}") from e

    def _set_servo(self, servo, value):
        if servo is None:
            return
        try:
            servo.value = value
        except Exception as e:
            print(f"Warning: failed to set servo value: {e}")

    def aim(self, b):
        if not isinstance(b, (list, tuple)):
            raise ValueError("Target positions must be a list or tuple")
        if not all(isinstance(x, int) and 1 <= x <= 10 for x in b):
            raise ValueError("Target positions must be integers between 1 and 10")
        if not b:
            return
        try:
            for i in b:
                self._set_servo(self._h_servo, self.hp[i - 1])
                self._set_servo(self._v_servo, self.vp[i - 1])
                self.laser.on()
                time.sleep(self.ld)
                self.laser.off()
                self._set_servo(self._h_servo, self.hp[10])
                self._set_servo(self._v_servo, self.vp[10])
                time.sleep(self.sd / 2)
        except Exception as e:
            print(f"Error during aiming: {e}")
            self.laser.off()
            raise

    def close(self):
        if self._h_servo is not None:
            self._h_servo.close()
            self._h_servo = None
        if self._v_servo is not None:
            self._v_servo.close()
            self._v_servo = None


def main():
    hp = [0.0] * 10
    vp = [0.0] * 10
    laser = Laser(17)
    aim = Aim(hp, vp, laser, ld=0.5, sd=0.1)

    def cleanup(signum=None, frame=None):
        laser.off()
        aim.close()
        laser.close()
        if signum is not None:
            sys.exit(0)

    signal.signal(signal.SIGTERM, cleanup)

    try:
        aim.aim([1, 2, 3])
    except KeyboardInterrupt:
        print("\nInterrupted by user")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        laser.off()
        aim.close()
        laser.close()


if __name__ == "__main__":
    main()

