import time
import signal
import sys
import smbus2

# PCA9685 constants
I2C_BUS = 1
PCA9685_ADDR = 0x40
PCA9685_MODE1 = 0x00
PCA9685_PRESCALE = 0xFE
PCA9685_LED0_ON_L = 0x06
PCA9685_LED0_ON_H = 0x07
PCA9685_LED0_OFF_L = 0x08
PCA9685_LED0_OFF_H = 0x09
PCA9685_ALL_LED_ON_L = 0xFA
PCA9685_ALL_LED_ON_H = 0xFB
PCA9685_ALL_LED_OFF_L = 0xFC
PCA9685_ALL_LED_OFF_H = 0xFD

# Servo channel assignments
BASE = 0
DROP = 1
SEEK = 2
GRAB = 4

# Drop angles for different materials
DROP_ANGLES = {
    "metal": 135,
    "plastic": 180,
    "paper": 90
}

# Global state
bus = None
running = True


def signal_handler(sig, frame):
    global running
    running = False


def init_pca9685():
    global bus
    try:
        bus = smbus2.SMBus(I2C_BUS)
        # Probe the device address
        bus.read_byte_data(PCA9685_ADDR, PCA9685_MODE1)
        # Reset oscillator
        bus.write_byte_data(PCA9685_ADDR, PCA9685_MODE1, 0x00)
        time.sleep(0.005)
        # Set prescaler for ~1kHz PWM (default ~25kHz)
        bus.write_byte_data(PCA9685_ADDR, PCA9685_PRESCALE, 0x02)
        # Enable auto-increment and restart
        bus.write_byte_data(PCA9685_ADDR, PCA9685_MODE1, 0x20)
        time.sleep(0.005)
        # Clear all channels
        bus.write_i2c_block_data(PCA9685_ADDR, PCA9685_ALL_LED_OFF_L, [0x00, 0x00, 0x00, 0x00])
        return True
    except OSError as e:
        print(f"Error initializing PCA9685 on I2C bus {I2C_BUS} at address 0x{PCA9685_ADDR:02X}: {e}")
        return False


def set_pwm(channel, on, off):
    if not 0 <= channel <= 15:
        raise ValueError(f"Invalid channel {channel}; must be 0-15")
    if not 0 <= on <= 4095:
        raise ValueError(f"Invalid on value {on}; must be 0-4095")
    if not 0 <= off <= 4095:
        raise ValueError(f"Invalid off value {off}; must be 0-4095")
    reg = PCA9685_LED0_ON_L + 4 * channel
    bus.write_i2c_block_data(PCA9685_ADDR, reg, [on & 0xFF, (on >> 8) & 0xFF, off & 0xFF, (off >> 8) & 0xFF])


