import signal
import sys
import time

import board
import busio
import adafruit_seesaw.seesaw
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

# --- Configuration -----------------------------------------------------------
I2C_ADDRESS = 0x20          # Adafruit Seesaw default I2C address (0x20 or 0x21)
DRY_SOIL_THRESHOLD = 500   # Moisture below this => pump ON
PUMP_PIN = 17              # BCM GPIO17 (physical pin 11)
POLL_INTERVAL = 10         # seconds between readings

# --- Globals for cleanup -----------------------------------------------------
_pump = None
_running = True


def _cleanup(signum=None, frame=None):
    """Turn the pump off and release GPIO resources on exit."""
    global _pump, _running
    _running = False
    if _pump is not None:
        try:
            _pump.off()
            _pump.close()
        except GPIOZeroError:
            pass
    if signum is not None:
        sys.exit(0)


def _init_pump():
    """Initialize the pump control pin; return an OutputDevice or None."""
    try:
        return OutputDevice(PUMP_PIN, active_high=True, initial_value=False)
    except GPIOZeroError as exc:
        print(f"ERROR: cannot initialize pump GPIO{PUMP_PIN}: {exc}", file=sys.stderr)
        return None


def _init_sensor():
    """Initialize the I2C bus and Seesaw sensor; return sensor or None."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"ERROR: cannot open I2C bus: {exc}", file=sys.stderr)
        return None

    try:
        sensor = adafruit_seesaw.seesaw.Seesaw(i2c, addr=I2C_ADDRESS)
    except ValueError:
        # ValueError is raised when the device is not found at the given address
        print(f"ERROR: no Seesaw found at I2C address 0x{I2C_ADDRESS:02X}", file=sys.stderr)
        return None
    except Exception as exc:
        print(f"ERROR: sensor initialization failed: {exc}", file=sys.stderr)
        return None

    return sensor


def _read_moisture(sensor):
    """Return a moisture reading or None on error."""
    try:
        return sensor.moisture_read()
    except OSError as exc:
        # I2C bus error (e.g., sensor disconnected, NACK)
        print(f"ERROR: I2C read failed: {exc}", file=sys.stderr)
        return None
    except Exception as exc:
        print(f"ERROR: unexpected sensor read failure: {exc}", file=sys.stderr)
        return None


def _set_pump(pump, state):
    """Drive the pump pin; if pump is None, log only."""
    if pump is None:
        print(f"Pump control unavailable — cannot set to {state}")
        return
    try:
        if state == "ON":
            pump.on()
        elif state == "OFF":
            pump.off()
        else:
            print(f"WARNING: invalid pump state '{state}'")
    except GPIOZeroError as exc:
        print(f"ERROR: cannot set pump {state}: {exc}", file=sys.stderr)


def main():
    global _pump

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    _pump = _init_pump()
    sensor = _init_sensor()

    if sensor is None or _pump is None:
        print("ERROR: sensor or pump initialization failed. Exiting.", file=sys.stderr)
        _cleanup()
        return

    print("Soil moisture monitor started. Press Ctrl+C to stop.")

    while _running:
        moisture = _read_moisture(sensor)

        if moisture is None:
            # Safety: ensure pump is off when sensor data is unavailable
            _set_pump(_pump, "OFF")
            print("Sensor read failed — pump turned OFF for safety.")
        else:
            print(f"Soil Moisture: {moisture}")
            if moisture < DRY_SOIL_THRESHOLD:
                _set_pump(_pump, "ON")
                print("Pump: ON")
            else:
                _set_pump(_pump, "OFF")
                print("Pump: OFF")

        # Sleep in small increments so signals are caught promptly
        slept = 0
        while _running and slept < POLL_INTERVAL:
            time.sleep(0.5)
            slept += 0.5

    _cleanup()


if __name__ == "__main__":
    main()

