import signal
import sys
import json
import logging
from http.server import BaseHTTPRequestHandler, HTTPServer

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
logger = logging.getLogger(__name__)

RELAY_PIN = 23
SERVER_PORT = 5000

relay = None
server = None


def cleanup(signum=None, frame=None):
    """Release GPIO resources and shut down the server cleanly."""
    global relay, server
    if relay is not None:
        try:
            relay.close()
            logger.info("GPIO cleanup completed.")
        except Exception as e:
            logger.error("Error during GPIO cleanup: %s", e)
    if server is not None:
        try:
            server.shutdown()
            server.server_close()
            logger.info("HTTP server stopped.")
        except Exception as e:
            logger.error("Error stopping server: %s", e)
    if signum is not None:
        sys.exit(0)


def handle_relay_request(state: str) -> dict:
    """Set the relay state and return a JSON response."""
    if state == "on":
        relay.on()
    elif state == "off":
        relay.off()
    else:
        raise ValueError("Invalid relay state. Must be 'on' or 'off'.")
    return {"status": "Relay state changed"}


class RelayHandler(BaseHTTPRequestHandler):
    """HTTP request handler for relay control."""

    def do_POST(self):
        if self.path == "/relay":
            try:
                content_length = int(self.headers.get('Content-Length', 0))
                post_data = self.rfile.read(content_length).decode('utf-8')
                data = json.loads(post_data)

                if not isinstance(data, dict):
                    raise ValueError("Invalid request. Payload must be a JSON object.")

                if "state" not in data:
                    raise ValueError("Invalid request. Payload must contain a 'state' key.")

                relay_state = data["state"]
                if not isinstance(relay_state, str):
                    raise ValueError("Invalid request. 'state' must be a string.")

                if relay_state not in ("on", "off"):
                    raise ValueError("Invalid request. 'state' must be 'on' or 'off'.")

                response_data = handle_relay_request(relay_state)
                self.send_response(200)
                self.send_header('Content-type', 'application/json')
                self.end_headers()
                self.wfile.write(json.dumps(response_data).encode('utf-8'))

            except (json.JSONDecodeError, ValueError) as e:
                logger.error("Invalid request: %s", e)
                self.send_response(400)
                self.send_header('Content-type', 'application/json')
                self.end_headers()
                self.wfile.write(json.dumps({"error": "Invalid request"}).encode('utf-8'))
            except Exception as e:
                logger.exception("An unexpected error occurred: %s", e)
                self.send_response(500)
                self.send_header('Content-type', 'application/json')
                self.end_headers()
                self.wfile.write(json.dumps({"error": "Internal server error"}).encode('utf-8'))
        else:
            self.send_response(404)
            self.end_headers()

    def log_message(self, format, *args):
        logger.info("HTTP: %s - %s", self.client_address[0], format % args)


def main():
    global relay, server
    try:
        relay = OutputDevice(RELAY_PIN)
        relay.off()
        logger.info("GPIO initialized. Relay on GPIO%d set to LOW.", RELAY_PIN)
    except (GPIOZeroError, GPIODeviceError) as e:
        logger.error("Failed to initialize GPIO: %s", e)
        sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        server = HTTPServer(('0.0.0.0', SERVER_PORT), RelayHandler)
        logger.info("Starting server on port %d", SERVER_PORT)
        server.serve_forever()
    except OSError as e:
        logger.error("Failed to start server: %s", e)
        cleanup()
        sys.exit(1)


if __name__ == '__main__':
    main()

