import signal
import sys
import time

try:
    import smbus2 as smbus
except ImportError:
    import smbus

try:
    from adafruit_ccs811 import Adafruit_CCS811
except ImportError:
    Adafruit_CCS811 = None

I2C_BUS = 1
I2C_ADDRESS = 0x5C
READ_INTERVAL = 2.0
NUM_READINGS = 5

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def initialize_sensor(bus_number, address):
    if Adafruit_CCS811 is None:
        print("Error: adafruit-circuitpython-ccs811 not installed.")
        return None
    try:
        bus = smbus.SMBus(bus_number)
    except FileNotFoundError:
        print(f"Error: I2C bus {bus_number} not found. Enable I2C via raspi-config.")
        return None
    except PermissionError:
        print(f"Error: Permission denied on I2C bus {bus_number}. Run as root or add user to 'i2c' group.")
        return None
    except OSError as e:
        print(f"Error opening I2C bus {bus_number}: {e}")
        return None

    try:
        sensor = Adafruit_CCS811(i2c_bus=bus, address=address)
    except ValueError as e:
        print(f"Error: CCS811 not detected at address 0x{address:02X} on bus {bus_number}: {e}")
        bus.close()
        return None
    except OSError as e:
        print(f"Error communicating with CCS811 on bus {bus_number}: {e}")
        bus.close()
        return None

    try:
        sensor.data_ready_interrupt = False
    except AttributeError:
        pass

    return sensor, bus


def read_co2_concentration(sensor, num_readings=NUM_READINGS, interval=READ_INTERVAL):
    readings_taken = 0
    while readings_taken < num_readings and _running:
        try:
            co2_concentration = sensor.read_CO2()
            if co2_concentration is not None:
                print(f"CO2 Concentration: {co2_concentration:.2f} ppm")
                readings_taken += 1
            else:
                print("Warning: Sensor returned None for CO2 concentration.")
        except OSError as e:
            print(f"I2C communication error during reading: {e}")
        except Exception as e:
            print(f"Unexpected error reading sensor: {e}")

        if readings_taken < num_readings and _running:
            time.sleep(interval)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    sensor = initialize_sensor(I2C_BUS, I2C_ADDRESS)
    if sensor is None:
        print("Failed to initialize CCS811 sensor. Exiting.")
        sys.exit(1)

    try:
        read_co2_concentration(sensor)
    finally:
        if sensor is not None:
            try:
                sensor.deinit()
            except Exception:
                pass
        try:
            sensor.bus.close()
        except Exception:
            pass
        print("Resources cleaned up. Exiting.")


if __name__ == "__main__":
    main()

