import signal
import sys
import time
import logging
from typing import Optional, Dict, Any, Tuple

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class ESP8266:
    """
    A class to control an ESP8266 Wi-Fi module via AT commands over UART.
    """

    def __init__(self, port: str = '/dev/serial0', baud_rate: int = 115200, timeout: float = 1.0) -> None:
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.uart: Optional[Any] = None
        self._running = True

        try:
            import serial
            self.uart = serial.Serial(
                port=port,
                baudrate=baud_rate,
                timeout=timeout,
                write_timeout=timeout
            )
            logging.info(f"Opened UART port {port} at {baud_rate} baud.")
        except serial.SerialException as e:
            logging.error(f"Failed to open UART port {port}: {e}")
            self.uart = None
        except Exception as e:
            logging.error(f"Unexpected error opening UART port {port}: {e}")
            self.uart = None

    def _send_command(self, command: bytes, terminator: bytes = b'OK', timeout: float = 1.0) -> Optional[bytes]:
        if self.uart is None:
            logging.error("UART not initialized.")
            return None

        try:
            self.uart.reset_input_buffer()
            self.uart.write(command)
            self.uart.flush()

            end_time = time.time() + timeout
            response = b''
            while time.time() < end_time:
                if self.uart.in_waiting > 0:
                    chunk = self.uart.read(self.uart.in_waiting)
                    if chunk:
                        response += chunk
                        if terminator in response:
                            return response
                else:
                    time.sleep(0.01)
            return None
        except serial.SerialTimeoutException as e:
            logging.error(f"Write timeout on command {command!r}: {e}")
            return None
        except serial.SerialException as e:
            logging.error(f"Serial error sending command {command!r}: {e}")
            return None
        except Exception as e:
            logging.error(f"Unexpected error sending command {command!r}: {e}")
            return None

    def test_connection(self) -> bool:
        response = self._send_command(b'AT', b'OK', timeout=self.timeout)
        return response is not None and b'OK' in response

    def restart(self) -> bool:
        response = self._send_command(b'AT+RST', b'OK', timeout=self.timeout)
        if response is None:
            return False
        time.sleep(2)
        return self.test_connection()

    def connect_wifi(self, ssid: str, password: str) -> bool:
        command = f'AT+CWJAP="{ssid}","{password}"'.encode('utf-8')
        response = self._send_command(command, b'OK', timeout=10.0)
        return response is not None and b'OK' in response

    def disconnect_wifi(self) -> bool:
        response = self._send_command(b'AT+CWQAP', b'OK', timeout=self.timeout)
        return response is not None and b'OK' in response

    def get_ip(self) -> Optional[str]:
        response = self._send_command(b'AT+CIFSR', b'OK', timeout=self.timeout)
        if response is None:
            return None
        try:
            lines = response.decode('utf-8', errors='ignore').split('\r\n')
            for line in lines:
                if 'STAIP' in line:
                    parts = line.split('=')
                    if len(parts) >= 2:
                        ip_str = parts[-1].strip()
                        if ip_str:
                            return ip_str
            return None
        except Exception as e:
            logging.error(f"Error parsing IP address: {e}")
            return None

    def send_http_request(self, method: str, url: str, host: str, port: int = 80, headers: Optional[Dict[str, str]] = None, data: Optional[str] = None) -> Optional[bytes]:
        if self.uart is None:
            logging.error("UART not initialized.")
            return None

        try:
            self.uart.reset_input_buffer()
            start_cmd = f'AT+CIPSTART="TCP","{host}",{port}'.encode('utf-8')
            start_resp = self._send_command(start_cmd, b'OK', timeout=self.timeout)
            if start_resp is None or b'OK' not in start_resp:
                logging.error("Failed to start TCP connection.")
                return None

            request = self._build_http_request(method, url, host, port, headers, data)
            send_cmd = f'AT+CIPSEND={len(request)}'.encode('utf-8')
