            self.uart.flush()

            end_time = time.time() + 5.0
            response = b''
            while time.time() < end_time:
                if self.uart.in_waiting > 0:
                    chunk = self.uart.read(self.uart.in_waiting)
                    if chunk:
                        response += chunk
                        if b'CLOSED' in response:
                            break
                else:
                    time.sleep(0.01)
            return response
        except serial.SerialException as e:
            logging.error(f"Serial error during HTTP request: {e}")
            return None
        except Exception as e:
            logging.error(f"Unexpected error during HTTP request: {e}")
            return None

    def receive_http_response(self, timeout: float = 5.0) -> Optional[bytes]:
        if self.uart is None:
            logging.error("UART not initialized.")
            return None

        try:
            end_time = time.time() + timeout
            response = b''
