            return response
        except serial.SerialException as e:
            logging.error(f"Serial error during HTTP response reception: {e}")
            return None
        except Exception as e:
            logging.error(f"Unexpected error during HTTP response reception: {e}")
            return None

    @staticmethod
    def _build_http_request(method: str, url: str, host: str, port: int, headers: Optional[Dict[str, str]] = None, data: Optional[str] = None) -> bytes:
        request = f"{method} {url} HTTP/1.1\r\n"
