import serial
import time
import signal
import sys
import RPi.GPIO as GPIO

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERIAL_TIMEOUT = 1
ALARM_GPIO_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_INTERVAL = 1

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baudrate, timeout):
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None

def initialize_gpio(pin):
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)

def read_radiation_level(serial_port):
    try:
        raw = serial_port.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        return float(line)
    except ValueError:
        return None
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None

def control_alarm(pin, radiation_level, threshold):
    if radiation_level > threshold:
        GPIO.output(pin, GPIO.HIGH)
        print("Radiation level exceeded threshold! Alarm triggered.")
    else:
        GPIO.output(pin, GPIO.LOW)

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, SERIAL_TIMEOUT)
    if serial_connection is None:
        sys.exit(1)

    try:
        initialize_gpio(ALARM_GPIO_PIN)
        alarm_active = False

        while _running:
            radiation_level = read_radiation_level(serial_connection)

            if radiation_level is not None:
                print(f"Radiation Level: {radiation_level:.2f} uSv/h")
                control_alarm(ALARM_GPIO_PIN, radiation_level, RADIATION_THRESHOLD)
                alarm_active = radiation_level > RADIATION_THRESHOLD
            else:
                print("Invalid data received from sensor.")

            time.sleep(READ_INTERVAL)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
        GPIO.cleanup()
        print("Resources cleaned up. Exiting.")

if __name__ == "__main__":
    main()

