        if not data:
            return None
        return float(data)
    except ValueError:
        print(f"Invalid data received (not a float): '{data}'", file=sys.stderr)
        return None
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None

def log_flow_rate(log_file, flow_rate):
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - Flow Rate: {flow_rate} L/min\n'
    try:
        with open(log_file, 'a') as f:
            f.write(log_entry)
    except OSError as e:
        print(f"Error writing to log file {log_file}: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        sys.exit(1)

    try:
        while _running:
            flow_rate = read_flow_rate(serial_connection)
            if flow_rate is not None:
                print(f'Flow Rate: {flow_rate} L/min')
                log_flow_rate(LOG_FILE, flow_rate)
            time.sleep(READ_INTERVAL)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

