        if len(sentence) < 3:
            return False
        try:
            csum = 0
            for ch in sentence[1:]:
                csum ^= ord(ch)
            return csum == int(sentence[0], 16)
        except (ValueError, IndexError):
            return False

    def _parse_ggga(self, sentence: str) -> Optional[GPS_readings]:
        if not sentence.startswith('$GPGGA'):
            return None
        if not self._nmea_checksum(sentence):
            logging.warning(f"Checksum failed for: {sentence}")
            return None
        fields = sentence.split(',')
        if len(fields) < 15:
            logging.warning(f"Incomplete GPGGA fields: {len(fields)}")
            return None
        try:
            fix_quality = int(fields[6])
            if fix_quality == 0:
                logging.info("No GPS fix yet.")
                return None
            lat_raw = fields[2]
            lat_dir = fields[3]
            lon_raw = fields[4]
            lon_dir = fields[5]
            if not lat_raw or not lat_dir or not lon_raw or not lon_dir:
                logging.warning("Missing N/S or E/W indicators.")
                return None
            lat_deg = int(lat_raw // 100)
            lat_min = lat_raw - lat_deg * 100
            lat_dec = lat_min / 60.0
            if lat_dir == 'S':
                lat_dec = -lat_dec
            lon_deg = int(lon_raw // 100)
            lon_min = lon_raw - lon_deg * 100
            lon_dec = lon_min / 60.0
            if lon_dir == 'W':
                lon_dec = -lon_dec
            latitude = lat_deg + lat_dec
            longitude = lon_deg + lon_dec
            altitude = float(fields[9]) if fields[9] else None
            satellite_count = int(fields[7]) if fields[7] else None
            return GPS_readings(latitude=latitude, longitude=longitude, altitude=altitude, satellite_count=satellite_count)
        except (ValueError, IndexError) as e:
            logging.error(f"Error parsing GPS data: {e}")
            return None

    def read_gps_data(self) -> Optional[GPS_readings]:
        if self.serial_port is None or not self.serial_port.is_open:
            logging.error("Serial port not open.")
            return None
        try:
            raw = self.serial_port.readline()
            if not raw:
                logging.warning("Read timeout: no data received.")
                return None
            sentence = raw.decode('ascii', errors='replace').strip()
            if not sentence:
                return None
            return self._parse_ggga(sentence)
        except serial.SerialException as e:
            logging.error(f"Serial communication error: {e}")
            return None
        except Exception as e:
            logging.error(f"Unexpected error reading GPS data: {e}")
            return None

def main():
    gps_reader = GPSReader()
    running = True

    def signal_handler(signum, frame):
        nonlocal running
        logging.info(f"Signal {signum} received, shutting down...")
        running = False

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not gps_reader.connect():
