from typing import Optional, Dict, Any

from gpiod import gpsd

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)


class SimpleGPS:
    """Minimal GPS parser that reads raw NMEA sentences over UART."""

    def __init__(self, port: str = "/dev/serial0", baudrate: int = 9600) -> None:
        self.port = port
        self.baudrate = baudrate
        self.gps_socket: Optional[gpsd.GPSD] = None
        self._closed = False

    def connect(self) -> bool:
        """Open the UART port and return True on success, False on failure."""
        try:
            self.gps_socket = gpsd.GPSD(self.port, self.baudrate)
            logging.info(
                "Connected to GPS on %s at %d baud.", self.port, self.baudrate
            )
            return True
        except OSError as exc:
            logging.error("Failed to connect to GPS on %s: %s", self.port, exc)
            self.gps_socket = None
            return False
        except Exception as exc:
            logging.error("Unexpected error opening %s: %s", self.port, exc)
            self.gps_socket = None
            return False

    def read_data(self) -> Optional[str]:
        """Read one line of decoded NMEA data.

        Returns the stripped line, or None if no data is available, the
        connection is closed, or a read/decode error occurs.
        """
        if self.gps_socket is None:
            return None
        try:
            raw = self.gps_socket.read()
        except OSError as exc:
            logging.error("UART read error: %s", exc)
            self.close()
            return None
        except Exception as exc:
            logging.error("Unexpected read error: %s", exc)
            self.close()
            return None

        if not raw:
            return None

        try:
            return raw.decode("utf-8", errors="ignore").strip()
        except Exception as exc:
            logging.error("Decode error: %s", exc)
            self.close()
            return None

    def parse_gga(self, data: str) -> Optional[Dict[str, Any]]:
        """Parse a $GPGGA or $GNGGA sentence into a dict.

        Returns None if the sentence is malformed or not a GGA sentence.
        """
        if not data.startswith("$GPGGA") and not data.startswith("$GNGGA"):
            return None

        fields = data.split(",")
        if len(fields) < 15:
            logging.warning("GGA line too short: %r", data)
            return None

        try:
            utc_time = fields[1]
            lat = self._decode_coord(fields[2], fields[3])
            lon = self._decode_coord(fields[4], fields[5])
            fix_quality = int(fields[6]) if fields[6] else None
            num_satellites = int(fields[7]) if fields[7] else None
        except (ValueError, IndexError) as exc:
            logging.warning("Failed to parse GGA fields: %s - %r", exc, data)
            return None

        return {
            "utc_time": utc_time,
            "latitude": lat,
            "longitude": lon,
            "fix_quality": fix_quality,
            "num_satellites": num_satellites,
        }

    @staticmethod
    def _decode_coord(value: str, direction: str) -> Optional[float]:
        """Convert a GPS coordinate field to decimal degrees."""
        if not value:
            return None
        try:
            deg_minutes = float(value)
            if deg_minutes == 0.0:
                return 0.0
            degrees = int(deg_minutes / 100.0)
            minutes = deg_minutes - (degrees * 100.0)
            decimal = degrees + (minutes / 60.0)
            if direction in ("S", "W"):
                decimal = -decimal
            return decimal
        except (ValueError, IndexError):
            return None

    def close(self) -> None:
        """Safely close the UART connection."""
        if self._closed:
            return
        self._closed = True
        if self.gps_socket is not None:
            try:
                self.gps_socket.close()
                logging.info("GPS connection closed.")
            except Exception as exc:
                logging.error("Error closing GPS connection: %s", exc)
            finally:
                self.gps_socket = None


def _main() -> None:
    gps = SimpleGPS(port="/dev/serial0", baudrate=9600)

    if not gps.connect():
        sys.exit(1)

    def _signal_handler(signum, frame):
        logging.info("Signal %d received, shutting down.", signum)
        gps.close()
        sys.exit(0)

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        while True:
            line = gps.read_data()
            if line is None:
                continue
            parsed = gps.parse_gga(line)
            if parsed:
                logging.info("Parsed GGA: %s", parsed)
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received.")
    finally:
        gps.close()


if __name__ == "__main__":
    _main()

