import signal
import sys
import threading
from contextlib import contextmanager

try:
    import serial
except ImportError:
    print("This script requires the 'pyserial' library. Install it with: pip install pyserial", file=sys.stderr)
    sys.exit(1)

from flask import Flask, Response, request, jsonify

app = Flask(__name__)

# Thread-safe lock for accessing the data list
data_lock = threading.Lock()

# In-memory data store
data_store = [
    {"id": 1, "name": "Item 1", "done": False},
    {"id": 2, "name": "Item 2", "done": False},
]

# Thread-safe lock for accessing the serial port
uart_lock = threading.Lock()

# Global reference to the serial port
uart_port = None


@contextmanager
def open_uart(port='/dev/ttyUSB0', baudrate=9600, timeout=1):
    """Context manager for opening and closing the UART port."""
    global uart_port
    with uart_lock:
        if uart_port is not None and uart_port.is_open:
            try:
                uart_port.close()
            except Exception:
                pass
            uart_port = None

        try:
            uart_port = serial.Serial(
                port=port,
                baudrate=baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=timeout,
            )
            yield uart_port
        finally:
            with uart_lock:
                if uart_port is not None and uart_port.is_open:
                    try:
                        uart_port.close()
                    except Exception:
                        pass
                    uart_port = None


@app.route('/version', methods=['GET'])
def get_version():
    """Sends the *IDN? command to the instrument and returns its response."""
    global uart_port
    with open_uart() as port:
        if port is None or not port.is_open:
            return Response("Error: Could not open UART port", status=500, mimetype='text/plain')

        try:
            port.write(b"*IDN?\n")
            port.flush()
            response = port.readline()
            if not response:
                return Response("Error: No response from instrument (timeout)", status=504, mimetype='text/plain')
            return Response(response.decode('ascii', errors='replace').strip(), mimetype='text/plain')
        except serial.SerialException as e:
            return Response(f"Error: Serial communication failed: {e}", status=500, mimetype='text/plain')
        except Exception as e:
            return Response(f"Error: Unexpected error: {e}", status=502, mimetype='text/plain')


@app.route('/data', methods=['GET', 'POST'])
def manage_data():
    """Handles GET and POST requests for data management."""
    global data_store

    with data_lock:
        if request.method == 'GET':
            return jsonify(data_store)

        elif request.method == 'POST':
            name = request.form.get('name')
            done = 'done' in request.form

            if not name or not isinstance(name, str):
                return jsonify({"error": "Invalid 'name' field. Must be a non-empty string."}), 400

            new_id = data_store[-1]['id'] + 1 if data_store else 1
            data_store.append({
                "id": new_id,
                "name": name,
                "done": done,
            })
            return jsonify(data_store[-1]), 201

        return jsonify({"error": "Invalid request method."}), 405


