import serial
import signal
import sys
from datetime import datetime

SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = "power_consumption.log"

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def log_power_data(power_value):
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"{timestamp} - Power: {power_value} W\n"
    try:
        with open(LOG_FILE, "a", encoding="utf-8") as logfile:
            logfile.write(log_entry)
    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            print(f"Opened {SERIAL_PORT} @ {BAUD_RATE} 8N1. Reading power data...")
            while _running:
                try:
                    raw_line = ser.readline()
                    if not raw_line:
                        continue
                    line = raw_line.decode("ascii", errors="replace").strip()
                    if not line:
                        continue
                    power_value = float(line)
                    log_power_data(power_value)
                except ValueError:
                    print(f"Invalid data received (not numeric): {line!r}", file=sys.stderr)
                except OSError as e:
                    print(f"Serial read error: {e}", file=sys.stderr)
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f"OS error opening serial port: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        print("Program terminated. UART port closed.")

if __name__ == "__main__":
    main()

