import http.server
import socketserver
import json
import serial
import time
import signal
import sys

PORT = 8000
SERIAL_PORT = '/dev/ttyUSB0'
BAUDRATE = 9600
SERIAL_TIMEOUT = 1.0

data = [
    {"id": 1, "name": "Item 1", "done": False},
    {"id": 2, "name": "Item 2", "done": False},
]

serial_connection = None
httpd = None


def init_serial():
    global serial_connection
    try:
        serial_connection = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUDRATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=SERIAL_TIMEOUT,
        )
        if not serial_connection.is_open:
            raise serial.SerialException(f"Failed to open {SERIAL_PORT}")
        print(f"Serial connection established on {SERIAL_PORT} @ {BAUDRATE} baud.")
    except serial.SerialException as e:
        print(f"Error initializing serial connection: {e}", file=sys.stderr)
        serial_connection = None


def send_scpi_query(query: str) -> str:
    if serial_connection is None or not serial_connection.is_open:
        return "Serial port not available."
    try:
        serial_connection.reset_input_buffer()
        serial_connection.reset_output_buffer()
        serial_connection.write(query.encode('utf-8'))
        time.sleep(0.1)
        raw = serial_connection.read(serial_connection.in_waiting or 64)
        return raw.decode('utf-8', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Error communicating with serial device: {e}", file=sys.stderr)
        return "Serial communication error."


class Handler(http.server.BaseHTTPRequestHandler):
    def _send_response(self, status_code: int, message: str) -> None:
        self.send_response(status_code)
        self.send_header('Content-type', 'text/html')
        self.end_headers()
        body = message.replace('\n', '<br>')
        self.wfile.write(body.encode('utf-8'))

    def do_GET(self):
        if self.path == '/version':
            response = send_scpi_query('*IDN?\n')
            self._send_response(200, response)
        elif self.path.startswith('/getdata'):
            self._send_response(200, json.dumps(data))
        elif self.path.startswith('/getset/'):
            try:
                item_id = int(self.path.split('/')[-1])
            except ValueError:
                self._send_response(400, 'Invalid item ID.')
                return
            item = next((it for it in data if it['id'] == item_id), None)
            if item is None:
                self._send_response(404, 'Item not found.')
                return
            self._send_response(200, json.dumps(item))
        elif self.path.startswith('/getpost/'):
            try:
                item_id = int(self.path.split('/')[2])
                name = self.path.split('/')[3]
            except (ValueError, IndexError):
                self._send_response(400, 'Invalid request format.')
                return
            item = next((it for it in data if it['id'] == item_id), None)
            if item is None:
                self._send_response(404, 'Item not found.')
                return
            item['name'] = name
            self._send_response(200, json.dumps(data))
        elif self.path == '/postjson':
            self._send_response(200, json.dumps(data))
        else:
            self._send_response(404, 'Not found.')

    def do_POST(self):
        if self.path == '/postjson':
            content_type = self.headers.get('Content-Type', '')
            if 'application/json' in content_type:
                try:
                    length = int(self.headers.get('Content-Length', 0))
                    body = self.rfile.read(length).decode('utf-8')
                    decoded = json.loads(body)
                    new_id = data[-1]['id'] + 1 if data else 1
                    new_item = {
                        'id': new_id,
                        'name': decoded.get('name', ''),
                        'done': decoded.get('done', False),
                    }
                    data.append(new_item)
                    self._send_response(201, json.dumps(data))
                except (json.JSONDecodeError, ValueError) as e:
                    self._send_response(400, f"Invalid JSON: {e}")
            elif 'application/x-www-form-urlencoded' in content_type:
                try:
                    name = self.headers.get('Content-Disposition', '')
                    if 'name=' in name:
                        name = name.split('name=')[1]
                    else:
                        name = ''
                    new_id = data[-1]['id'] + 1 if data else 1
                    new_item = {
                        'id': new_id,
                        'name': name,
                        'done': False,
                    }
                    data.append(new_item)
                    self._send_response(201, json.dumps(data))
                except (IndexError, ValueError) as e:
                    self._send_response(400, f"Invalid form data: {e}")
            else:
                self._send_response(415, 'Unsupported media type.')
        else:
            self._send_response(404, 'Not found.')

    def log_message(self, format, *args):
        pass


def cleanup(signum=None, frame=None):
    global httpd, serial_connection
    if httpd is not None:
        try:
            httpd.shutdown()
        except Exception:
            pass
    if serial_connection is not None and serial_connection.is_open:
        try:
            serial_connection.close()
            print("Serial port closed.")
        except Exception as e:
            print(f"Error closing serial port: {e}", file=sys.stderr)
    if signum is not None:
        sys.exit(0)


def main():
    global httpd
    init_serial()
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    try:
        httpd = socketserver.TCPServer(('0.0.0.0', PORT), Handler)
        print(f"Serving at port {PORT}")
        httpd.serve_forever()
    except OSError as e:
        print(f"Error starting server: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == '__main__':
    main()

