import signal
import sys
import time

from bluetooth_socket import RFCOMM


class BluetoothApp:
    """
    A class to manage a Bluetooth connection and communication on a
    Raspberry Pi using the `bluetooth_socket` API.
    """

    def __init__(self, port: int = 4, channel: int = 4,
                 baudrate: int = 38400, device_path: str = "/dev/rfcomm4"):
        self.port = port
        self.channel = channel
        self.baudrate = baudrate
        self.device_path = device_path
        self.bluetooth = None
        self._running = True

    def _handle_signal(self, signum, frame):
        """Signal handler for graceful shutdown."""
        print(f"\nReceived signal {signum}, shutting down...")
        self._running = False

    def connect(self) -> None:
        """Establishes the Bluetooth connection."""
        try:
            self.bluetooth = RFCOMM(
                port=self.port,
                channel=self.channel,
                baudrate=self.baudrate,
                device=self.device_path
            )
            self.bluetooth.connect()
            print(f"Connected to Bluetooth device at {self.device_path}")
        except Exception as e:
            raise RuntimeError(f"Failed to connect to Bluetooth device: {e}")

    def disconnect(self) -> None:
        """Closes the Bluetooth connection if open."""
        if self.bluetooth is not None:
            try:
                self.bluetooth.close()
                print("Bluetooth connection closed.")
            except Exception as e:
                print(f"Error closing Bluetooth connection: {e}")
            finally:
                self.bluetooth = None

    def run(self) -> None:
        """Runs the main application loop."""
        signal.signal(signal.SIGINT, self._handle_signal)
        signal.signal(signal.SIGTERM, self._handle_signal)

        try:
            self.connect()
            while self._running:
                try:
                    user_command = input("Enter command (or 'exit' to quit): ")
                except EOFError:
                    print("\nEOF received, exiting...")
                    break

                if user_command.strip().lower() == "exit":
                    print("Exit command received.")
                    break

                message = f"X{user_command}\n"
                try:
                    bytes_written = self.bluetooth.send(message.encode("utf-8"))
                    if bytes_written != len(message.encode("utf-8")):
                        print(f"Warning: incomplete write ({bytes_written}/{len(message)} bytes).")
                    else:
                        print(f"Sent ({bytes_written} bytes): {message.strip()}")
                except Exception as e:
                    raise RuntimeError(f"Failed to send data: {e}")

                time.sleep(0.1)

        except RuntimeError as e:
            print(f"RuntimeError: {e}")
        except Exception as e:
            print(f"An unexpected error occurred: {e}")
        finally:
            self.disconnect()


if __name__ == "__main__":
    app = BluetoothApp()
    app.run()

